KB.lade("mexiko",[{"id":"mexiko-tacos-al-pastor","name":"Tacos al Pastor (Heimküche)","originalname":"Tacos al pastor","kueche":"mexiko","region":"Mexiko-Stadt / Puebla","beliebtheit":98,"hauptkategorie":"fleisch","fleischsorte":"schwein","gang":"hauptgericht","kurz":"Hauchdünn geschnittenes Schweinefleisch in einer rauchig-roten Chili-Achiote-Marinade, scharf angebraten und mit karamellisierter Ananas in warmen Maistortillas serviert – der Taco, der in Rankings regelmäßig ganz oben steht.","hintergrund":"Tacos al pastor sind eine mexikanische Antwort auf den Drehspieß der libanesischen Einwanderer, die ab den 1930er-Jahren Shawarma nach Puebla und Mexiko-Stadt brachten. Statt Lamm wurde Schwein genommen, statt Joghurt-Gewürzen kam eine Adobo aus getrockneten Chilis, Achiote und Ananas ins Spiel. An der Taquería dreht sich das Fleisch als Turm (trompo) vor dem Feuer, an dessen Spitze eine Ananas sitzt; der Taquero schneidet das Fleisch direkt in die Tortilla und lässt ein Stück Ananas hinterherfliegen. In der TasteAtlas-Bewertung wurde der Taco al pastor zum bestbewerteten Gericht der Welt gekürt. Zu Hause lässt sich der Effekt mit einer sehr heißen Pfanne oder dem Backofengrill gut nachbauen.","portionen":4,"zeit":{"vorbereitung":50,"garen":25,"ruhen":720},"schwierigkeit":2,"zutaten":[{"gruppe":"Fleisch und Marinade","liste":[{"menge":900,"einheit":"g","name":"Schweinenacken (Schweinekamm) ohne Knochen","hinweis":"gut marmoriert, Metzger bitten, ihn halb angefroren in 5 mm dünne Scheiben zu schneiden"},{"menge":4,"einheit":"Stück","name":"getrocknete Guajillo-Chilis","hinweis":"Mexiko-Laden oder Online-Gewürzhandel; Ersatz: Pasilla oder milde Ancho"},{"menge":2,"einheit":"Stück","name":"getrocknete Ancho-Chilis","hinweis":"für Süße und Tiefe"},{"menge":2,"einheit":"EL","name":"Achiote-Paste (Annatto)","hinweis":"gibt Farbe und erdig-pfeffrigen Geschmack; online oder im Lateinamerika-Laden"},{"menge":150,"einheit":"ml","name":"Ananassaft","hinweis":"am besten frisch gepresst oder naturtrüb"},{"menge":3,"einheit":"EL","name":"Weißweinessig oder Apfelessig","hinweis":""},{"menge":4,"einheit":"Zehe","name":"Knoblauch","hinweis":""},{"menge":1,"einheit":"TL","name":"Kreuzkümmel, gemahlen","hinweis":""},{"menge":1,"einheit":"TL","name":"getrockneter Oregano","hinweis":"mexikanischer Oregano falls vorhanden, sonst normaler"},{"menge":2,"einheit":"Stück","name":"Gewürznelken","hinweis":""},{"menge":2,"einheit":"TL","name":"Salz","hinweis":""},{"menge":2,"einheit":"EL","name":"Pflanzenöl","hinweis":"zum Pürieren und Braten"}]},{"gruppe":"Zum Servieren","liste":[{"menge":16,"einheit":"Stück","name":"kleine Maistortillas (ca. 12 cm)","hinweis":"Maisanteil möglichst hoch, siehe Rezept Tortillas de maíz"},{"menge":0.5,"einheit":"Stück","name":"frische Ananas","hinweis":"in fingerdicke Scheiben schneiden"},{"menge":1,"einheit":"Stück","name":"weiße Zwiebel","hinweis":"sehr fein gewürfelt"},{"menge":1,"einheit":"Bund","name":"Koriandergrün","hinweis":"grob gehackt"},{"menge":2,"einheit":"Stück","name":"Limetten","hinweis":"in Spalten"},{"menge":null,"einheit":"","name":"Salsa verde oder Salsa roja","hinweis":"siehe Rezept Salsa Roja und Salsa Verde"}]}],"ausruestung":["gusseiserne Pfanne oder Grillpfanne","Standmixer","Gefrierbeutel oder Schüssel mit Deckel zum Marinieren","scharfes Messer","Backblech mit Alufolie (für die Grillvariante)"],"schritte":[{"titel":"Mise en place und Fleisch vorbereiten","aktion":"vorbereiten","text":"Lege den Schweinenacken für etwa 45 Minuten ins Gefrierfach, damit er außen fest wird, und schneide ihn dann mit einem langen, sehr scharfen Messer quer zur Faser in Scheiben von etwa 5 Millimetern Dicke. Dünne Scheiben nehmen die Marinade schnell auf und werden später in der heißen Pfanne außen knusprig, bevor sie innen trocken werden. Schäle die Knoblauchzehen, halbiere die Ananas und entferne Schale und Strunk, wiege alle Gewürze ab und stelle Pflanzenöl, Mixer und eine große Schüssel bereit. Wenn du alles vor dir stehen hast, geht die Marinade in wenigen Minuten.","dauer":10,"tipp":"Ein halb angefrorenes Fleischstück lässt sich mit minimalem Druck gleichmäßig dünn schneiden."},{"titel":"Chilis entstielen und rösten","aktion":"vorbereiten","text":"Schneide die Stiele der getrockneten Chilis ab, schlitze sie der Länge nach auf und schüttle die Kerne heraus; ein Teil der Kerne darf drinbleiben, wenn du es schärfer magst. Erhitze eine trockene Pfanne auf mittlere Hitze und röste die Chilihälften pro Seite nur etwa 15 bis 20 Sekunden, bis sie leicht duften und biegsam sind. Sobald es nach Rauch und Rosinen riecht, sind sie fertig – wirst du länger rösten oder dunkelbraun werden lassen, schmecken sie bitter und die ganze Marinade kippt. Drücke die Chilis dabei kurz mit dem Pfannenwender an, damit sie Kontakt zur heißen Fläche haben.","dauer":5,"tipp":"Chilis, die schwarze Flecken bekommen haben, besser wegwerfen – Bitterkeit lässt sich später nicht mehr ausgleichen."},{"titel":"Chilis einweichen","aktion":"vorbereiten","text":"Gib die gerösteten Chilis in eine hitzebeständige Schüssel und übergieße sie mit etwa 400 Millilitern kochend heißem Wasser. Beschwere sie mit einem kleinen Teller, damit sie vollständig untertauchen, und lass sie 20 Minuten ziehen. Sie sind bereit, wenn sich das Fruchtfleisch weich anfühlt, die Haut nicht mehr ledrig ist und das Wasser rötlich-braun gefärbt ist. Das Einweichwasser ist leicht bitter; gieße es also weg und verwende später lieber den Ananassaft zum Pürieren, außer du brauchst einen Schluck, um den Mixer in Gang zu bringen.","dauer":20,"tipp":""},{"titel":"Adobo-Marinade pürieren","aktion":"mischen","text":"Gib die abgetropften Chilis zusammen mit Achiote-Paste, Ananassaft, Essig, Knoblauch, Kreuzkümmel, Oregano, den Nelken, dem Salz und einem Esslöffel Öl in den Standmixer. Püriere 1 bis 2 Minuten auf höchster Stufe, bis eine glatte, samtige Paste in tiefem Rot entsteht; sie soll dickflüssig wie Ketchup sein. Ist sie zu fest, rührst du esslöffelweise Ananassaft nach, ist sie zu flüssig, bleibt sie später nicht am Fleisch haften. Schmecke mit einem Tropfen auf dem Finger ab: sauer, rauchig, leicht süß und mit Salz im Vordergrund – das Fleisch nimmt später nur einen Teil davon auf.","dauer":5,"tipp":"Wer es feiner mag, streicht die Marinade durch ein Sieb; so bleiben keine Chilihäutchen zurück."},{"titel":"Fleisch marinieren","aktion":"marinieren","text":"Gib die Fleischscheiben in eine große Schüssel oder einen Gefrierbeutel und knete die Marinade gründlich ein, bis jede Scheibe rundum bedeckt ist. Drücke die Luft aus dem Beutel, verschließe ihn und lege ihn für mindestens 8, besser 12 bis 24 Stunden in den Kühlschrank. Die Säure aus Essig und Ananas lockert die Fasern, die Ananas enthält außerdem das Enzym Bromelain, das Eiweiß abbaut. Nach spätestens einem Tag solltest du braten, sonst wird das Fleisch breiig. Wende den Beutel zwischendurch einmal.","dauer":720,"tipp":"Nicht länger als 24 Stunden marinieren – Ananasenzyme machen das Fleisch sonst weich und mehlig."},{"titel":"Ananas und Beilagen vorbereiten","aktion":"schneiden","text":"Nimm das Fleisch eine halbe Stunde vor dem Braten aus dem Kühlschrank, damit es nicht eiskalt in die Pfanne kommt. Schneide die Ananas in 1 Zentimeter dicke Scheiben, entferne den harten Strunk in der Mitte und würfle sie später in kleine Stücke. Würfle die Zwiebel sehr fein, hacke den Koriander grob, schneide die Limetten in Spalten und stelle die Salsa bereit. Wärme außerdem den Backofen auf 80 Grad Ober-/Unterhitze vor, damit du fertiges Fleisch und die Tortillas warm halten kannst.","dauer":10,"tipp":""},{"titel":"Ananas anbraten","aktion":"braten","text":"Erhitze die gusseiserne Pfanne bei hoher Hitze ohne Fett, bis sie leicht raucht, und lege die Ananasscheiben hinein. Sie sollen 2 bis 3 Minuten pro Seite ungestört liegen, bis sie dunkelbraune, fast schwarze Röstflecken haben und sich der Zucker karamellisiert. Der Duft wird deutlich süßer und leicht rauchig; die Ananas zischt dabei kräftig. Nimm sie heraus, lass sie kurz abkühlen und schneide sie in 1 Zentimeter große Würfel, die später zu den Tacos kommen.","dauer":8,"tipp":"Gerade bei Ananas aus der Dose gut abtropfen lassen, sonst dämpft sie nur statt zu karamellisieren."},{"titel":"Fleisch scharf anbraten","aktion":"braten","text":"Erhitze die Pfanne erneut bei hoher Hitze, gib einen Teelöffel Öl hinein und brate das Fleisch in drei bis vier Portionen, damit die Pfanne nicht abkühlt. Schüttle überschüssige Marinade nicht ab, aber gib auch nicht zu viel davon in die Pfanne. Die Scheiben sollen pro Seite 2 bis 3 Minuten brutzeln, bis sie an den Rändern dunkelrot-braun und knusprig sind und die Marinade kleine, angeröstete Krusten bildet. Es soll laut zischen, nicht köcheln: Wenn Flüssigkeit austritt, ist die Pfanne zu voll oder nicht heiß genug. Halte fertige Portionen im Ofen warm.","dauer":15,"tipp":"Wer einen Backofengrill hat, kann die Scheiben auf einem Rost bei 250 °C Grillstufe etwa 6 Minuten pro Seite rösten – nahe am Grill bekommen die Ränder echte Röstaromen."},{"titel":"Fleisch hacken und abschmecken","aktion":"hacken","text":"Lege alle Fleischscheiben zusammen auf ein Brett und hacke sie grob in etwa 1 Zentimeter große Stücke, so wie es der Taquero am Spieß tut. Gib die Stücke zurück in die Pfanne, mische die Ananaswürfel unter und brate alles eine Minute bei hoher Hitze, damit sich Fleisch und Frucht verbinden. Probiere ein Stück und schmecke mit etwas Salz und einigen Tropfen Limettensaft ab; das Fleisch soll würzig, leicht süßlich und kräftig nach Chili schmecken, ohne zu trocken zu wirken. Falls es trocken scheint, gib einen Esslöffel Ananassaft in die Pfanne.","dauer":3,"tipp":""},{"titel":"Tortillas wärmen","aktion":"braten","text":"Erhitze eine trockene Pfanne oder ein Comal auf mittlere bis hohe Hitze und lege die Tortillas einzeln hinein. Wende sie nach etwa 30 Sekunden, wenn sich kleine braune Flecken zeigen und sie leicht aufquellen; die zweite Seite braucht weitere 20 bis 30 Sekunden. Schlage fertige Tortillas sofort in ein sauberes Küchentuch, damit sie im Dampf weich und biegsam bleiben. Zwei Tortillas pro Taco übereinander sind in vielen Taquerías üblich und verhindern, dass der saftige Taco durchweicht.","dauer":5,"tipp":""},{"titel":"Anrichten und essen","aktion":"anrichten","text":"Lege eine warme Tortilla in die flache Hand, gib zwei Esslöffel Fleisch-Ananas-Mischung darauf und streue Zwiebelwürfel und Koriander darüber. Träufle etwas Salsa darauf und drücke eine Limettenspalte aus; falte den Taco nur leicht und iss ihn sofort, denn er schmeckt am besten, wenn Fleisch und Tortilla noch heiß sind. Serviere die restlichen Zutaten in Schälchen am Tisch, damit sich jeder seine Tacos selbst belegen kann. Wer mag, reicht dazu Radieschenscheiben und eingelegte Zwiebeln.","dauer":0,"tipp":"Kleine Tortillas, nicht überfüllen: Ein Taco ist ein Zwei-Bissen-Gericht."}],"profitipps":["Die Scheiben so dünn wie möglich schneiden und im heißen Pfannenboden braten – nur so entsteht die knusprig-saftige Textur vom Spieß.","Chilis nur kurz anrösten (15–20 Sekunden pro Seite); verbrannte Chilis machen die Adobo dauerhaft bitter.","Achiote nicht weglassen: Er liefert das typische Rot und die erdige Note, die Paprikapulver nicht ersetzt.","Nie zu viel Fleisch auf einmal braten, sonst dünstet es in der eigenen Flüssigkeit und wird grau.","Gabriela Cámara kocht die Ananas in Butter mit; ein Löffel Butter in der Ananas-Pfanne verstärkt die Karamellnote."],"varianten":["Al-pastor-Spieß im Ofen: Scheiben auf einem Holzspieß dicht stapeln, bei 220 °C Umluft 40 Minuten rösten und von außen abschneiden.","Mit Hähnchenschenkel statt Schwein (Pollo al pastor).","Gringas: Taco al pastor in Mehltortilla mit geschmolzenem Käse."],"beilagen":["Salsa verde","Salsa roja","Frijoles refritos","Mexikanischer Reis","eingelegte rote Zwiebeln"],"getraenk":"Kaltes Lagerbier (z. B. Pacífico oder Helles), Horchata oder Agua de Jamaica","koeche":[{"name":"Gabriela Cámara","bezug":"Stellt in ihrem MasterClass-Programm Tacos al pastor mit hausgemachter Adobo rojo vor und gart die Ananas in Butter mit – Grundlage für den Butter-Tipp.","quelle":"https://www.masterclass.com/articles/gabriela-camara-top-recipes"}],"quellen":[{"titel":"Tacos al Pastor Named The World's Tastiest Dish (Journey Mexico)","url":"https://www.journeymexico.com/?p=32652"},{"titel":"Uncomplicated Mexican dishes rate among world's best (Guadalajara Reporter)","url":"https://theguadalajarareporter.net/index.php/featured/61332-uncomplicated-mexican-dishes-rate-among-world-s-best"},{"titel":"Gabriela Camara – Top Recipes (MasterClass)","url":"https://www.masterclass.com/articles/gabriela-camara-top-recipes"}],"bild":"taco","farben":["#b8341e","#e08a2f","#f2d27a"],"schlagworte":["Streetfood","Taco-Abend","TasteAtlas","Klassiker"],"vegetarisch_moeglich":false},{"id":"mexiko-guacamole","name":"Guacamole","originalname":"Guacamole","kueche":"mexiko","region":"Zentralmexiko","beliebtheit":96,"hauptkategorie":"vegan","fleischsorte":"","gang":"sauce","kurz":"Cremig, frisch und kräftig gesalzen: echte Guacamole aus reifen Avocados, Chili, Zwiebel und Koriander – im Mörser zerdrückt, nicht püriert.","hintergrund":"Der Name kommt aus dem Nahuatl: ahuacamolli bedeutet Avocadosauce, und das Gericht wird in Mexiko seit der Zeit der Azteken zubereitet. Traditionell entsteht es im Molcajete, einem Mörser aus Vulkanstein, in dem Chili, Zwiebel und Salz zu einer Paste zerrieben werden, bevor die Avocado dazukommt. Die Basis ist bewusst schlicht, Tomate und Limette sind je nach Region Zugabe. In Mexiko isst man Guacamole zu Tacos, Carnitas und gegrilltem Fleisch ebenso wie mit warmen Tortilla-Chips. In TasteAtlas-Listen der besten Gerichte der Welt taucht sie ebenfalls auf.","portionen":4,"zeit":{"vorbereitung":15,"garen":0,"ruhen":0},"schwierigkeit":1,"zutaten":[{"gruppe":"Guacamole","liste":[{"menge":3,"einheit":"Stück","name":"reife Hass-Avocados","hinweis":"sie sollen auf leichten Druck nachgeben, aber nicht matschig sein"},{"menge":0.25,"einheit":"Stück","name":"weiße Zwiebel","hinweis":"sehr fein gehackt, ein Teil davon wird mit zerrieben"},{"menge":1,"einheit":"Stück","name":"frische grüne Chili (Serrano oder Jalapeño)","hinweis":"Serrano ist schärfer; Ersatz: kleine grüne Spitzpaprika mit einer Msp. Chilipulver"},{"menge":3,"einheit":"EL","name":"Koriandergrün","hinweis":"fein gehackt, mit Stielen"},{"menge":0.5,"einheit":"Stück","name":"Limette","hinweis":"Saft, nach Bedarf mehr"},{"menge":1,"einheit":"TL","name":"grobes Meersalz","hinweis":""},{"menge":1,"einheit":"Stück","name":"reife Tomate","hinweis":"optional; entkernt und gewürfelt"}]}],"ausruestung":["Molcajete oder stabile Schüssel mit Gabel","kleines scharfes Messer","Klarsichtfolie"],"schritte":[{"titel":"Zutaten vorbereiten","aktion":"vorbereiten","text":"Schneide die Zwiebel in sehr feine Würfel von etwa 2 Millimetern und hacke den Koriander samt zarten Stielen fein, denn die Stiele tragen viel Aroma. Entferne bei der Chili den Stiel; mit Kernen wird die Guacamole deutlich schärfer, ohne Kerne milder. Wenn du Tomate verwendest, halbiere sie, kratze Kerne und Saft heraus und würfle nur das feste Fruchtfleisch, sonst wird die Guacamole wässrig. Alle Zutaten sollten bereit stehen, bevor du die Avocados aufschneidest, weil das Fruchtfleisch an der Luft schnell bräunt.","dauer":0,"tipp":""},{"titel":"Chili, Zwiebel und Salz zur Paste verreiben","aktion":"hacken","text":"Gib Chili, die Hälfte der Zwiebel, die Hälfte des Korianders und das Salz in den Molcajete und zerreibe alles mit dem Stößel zu einer grünlichen, feuchten Paste. Das grobe Salz wirkt dabei wie Schleifmittel und bricht die Zellwände auf, sodass das Aroma in die Paste übergeht. Hast du keinen Mörser, hacke alles auf einem Brett sehr fein und drücke es mit der Messerflanke und etwas Salz zu einer Paste. Die Paste soll intensiv duften und fast schon zu stark schmecken, denn die Avocado verdünnt sie.","dauer":3,"tipp":"Dieser Schritt ist der Unterschied zwischen Restaurant-Guacamole und Instant-Dip: Aroma aus Chili und Zwiebel wird erst durch Zerreiben freigesetzt."},{"titel":"Avocados aufschneiden und entsteinen","aktion":"schneiden","text":"Halbiere die Avocados der Länge nach rund um den Kern, drehe die Hälften gegeneinander und löse sie. Schlage mit der Klinge vorsichtig in den Kern, drehe ihn heraus und löse ihn mit dem Messerrücken. Hole das Fruchtfleisch mit einem großen Löffel aus der Schale. Es sollte hellgrün bis gelblich sein, ohne braune Flecken oder Fäden; braune Stellen schneidest du großzügig weg. Eine reife Avocado erkennst du daran, dass der kleine Stielansatz sich leicht lösen lässt und darunter grün, nicht braun, ist.","dauer":0,"tipp":""},{"titel":"Avocado zerdrücken","aktion":"mischen","text":"Gib das Avocadofleisch zur Paste und zerdrücke es mit Gabel oder Stößel grob, sodass noch kleine Stückchen stehen bleiben. Die Konsistenz soll cremig, aber nicht glatt sein, denn kleine Avocadostücke geben der Guacamole Biss. Püriere sie auf keinen Fall im Mixer, das macht sie zu einer schleimigen Creme und nimmt ihr den Charakter. Arbeite zügig, damit das Fruchtfleisch nicht oxidiert und seine Farbe behält.","dauer":3,"tipp":""},{"titel":"Abschmecken und Frische ergänzen","aktion":"abschmecken","text":"Rühre die restliche Zwiebel, den restlichen Koriander und, falls gewünscht, die Tomate unter. Gib zunächst nur einen Teelöffel Limettensaft dazu, rühre um und probiere: Es sollte frisch, leicht sauer, salzig und mit einer grünen Schärfe schmecken. Erst wenn der Geschmack flach wirkt, mehr Salz oder Limette ergänzen. Salz ist das Wichtigste, denn fettreiche Avocado braucht deutlich mehr davon, als man zunächst vermutet. Vergiss nicht, kurz zu warten, nachdem du gesalzen hast, bis sich der Geschmack verbunden hat.","dauer":2,"tipp":"Ein Stück Tortilla-Chip als Probierlöffel nehmen – so schmeckst du es genau so, wie es später gegessen wird."},{"titel":"Servieren und frisch halten","aktion":"anrichten","text":"Serviere die Guacamole sofort im Molcajete oder in einer Schale, am besten mit warmen Tortillas, Tostadas oder als Beilage zu Tacos und Carnitas. Wenn sie ein paar Stunden warten muss, drücke Klarsichtfolie direkt auf die Oberfläche, sodass keine Luft eindringt; das verhindert das Braunwerden besser als ein darin liegender Kern. Schmecke vor dem Servieren noch einmal mit Salz und Limette ab, da kalte Guacamole weniger intensiv schmeckt. Im Kühlschrank hält sie sich so etwa einen halben Tag, danach leidet die Farbe.","dauer":0,"tipp":""}],"profitipps":["Hass-Avocados verwenden: Sie sind cremiger und aromatischer als die glatten, grünen Sorten.","Die Paste aus Chili, Zwiebel und Salz zuerst zerreiben – so entfaltet sich das Aroma.","Nie pürieren; grob zerdrücken, damit Stücke bleiben.","Mehr Salz als gedacht: Avocado schluckt Geschmack.","Klarsichtfolie direkt auf die Oberfläche legen, nicht nur über die Schüssel."],"varianten":["Mit Tomate und etwas Knoblauch (modern, in Restaurants verbreitet)","Mit Granatapfelkernen und Röstzwiebeln (Guacamole del Norte)","Scharf mit gerösteter Salsa Macha als Topping"],"beilagen":["Tortilla-Chips","Tostadas","Tacos","Carnitas"],"getraenk":"Margarita, Mezcal oder ein kaltes helles Bier","koeche":[],"quellen":[{"titel":"Uncomplicated Mexican dishes rate among world's best (Guadalajara Reporter)","url":"https://theguadalajarareporter.net/index.php/featured/61332-uncomplicated-mexican-dishes-rate-among-world-s-best"},{"titel":"Tacos al Pastor Named The World's Tastiest Dish (Journey Mexico)","url":"https://www.journeymexico.com/?p=32652"}],"bild":"dip","farben":["#6e8f3a","#a9c25a","#f1e8a8"],"schlagworte":["Dip","vegan","Party","Schnell"],"vegetarisch_moeglich":true},{"id":"mexiko-mole-poblano","name":"Mole Poblano","originalname":"Mole poblano de guajolote","kueche":"mexiko","region":"Puebla","beliebtheit":92,"hauptkategorie":"fleisch","fleischsorte":"huhn","gang":"hauptgericht","kurz":"Eine samtige, dunkelbraune Sauce aus Chilis, Nüssen, Gewürzen und einem Hauch Schokolade über zartem Geflügel – das Festgericht Mexikos schlechthin.","hintergrund":"Mole poblano gilt als das Nationalgericht Mexikos und wird zu Hochzeiten, Taufen und am Día de Muertos serviert. Die Legende erzählt, Nonnen im Kloster Santa Rosa in Puebla hätten die Sauce für einen hohen Gast erfunden; sicher ist, dass sie aus der Verbindung von indigenen Zutaten (Chili, Kakao, Kürbiskerne) mit eingeführten Gewürzen und Mandeln entstand. Jede Familie hat ein eigenes Rezept mit 20 bis 30 Zutaten, und der Aufwand ist Teil der Feier. Klassisch kommt Truthahn (guajolote) in die Sauce, heute meist Hähnchen. Der Chef Enrique Olvera pflegt im Pujol einen „Mole madre“, der seit Jahren ununterbrochen reift – ein Zeichen, wie lebendig die Tradition ist.","portionen":6,"zeit":{"vorbereitung":75,"garen":180,"ruhen":0},"schwierigkeit":3,"zutaten":[{"gruppe":"Hähnchen","liste":[{"menge":1.8,"einheit":"kg","name":"Hähnchenschenkel oder Putenkeule, mit Knochen und Haut","hinweis":"Pute ist klassisch; Keulen bleiben saftig"},{"menge":1,"einheit":"Stück","name":"Zwiebel, halbiert","hinweis":""},{"menge":4,"einheit":"Zehe","name":"Knoblauch","hinweis":""},{"menge":2,"einheit":"TL","name":"Salz","hinweis":""}]},{"gruppe":"Chilis","liste":[{"menge":5,"einheit":"Stück","name":"getrocknete Mulato-Chilis","hinweis":"Mexiko-Laden oder online; Ersatz: weitere Ancho"},{"menge":5,"einheit":"Stück","name":"getrocknete Ancho-Chilis","hinweis":"Rosinen-ähnliche, süßliche Basis"},{"menge":4,"einheit":"Stück","name":"getrocknete Pasilla-Chilis","hinweis":"bringen Bitterkeit und Tiefe"}]},{"gruppe":"Nüsse, Samen und Früchte","liste":[{"menge":50,"einheit":"g","name":"Mandeln, ungeschält","hinweis":""},{"menge":50,"einheit":"g","name":"geschälte Erdnüsse, ungesalzen","hinweis":""},{"menge":3,"einheit":"EL","name":"Sesamsamen","hinweis":"plus 1 EL zum Garnieren"},{"menge":40,"einheit":"g","name":"Rosinen","hinweis":""},{"menge":1,"einheit":"Stück","name":"reife Kochbanane (Plátano macho)","hinweis":"Ersatz: sehr reife normale Banane"},{"menge":2,"einheit":"Stück","name":"Tomaten","hinweis":""},{"menge":4,"einheit":"Stück","name":"Tomatillos (Physalis-ähnlich)","hinweis":"aus der Dose oder durch weitere Tomaten + Limettensaft ersetzbar"},{"menge":1,"einheit":"Scheibe","name":"Weißbrot oder Brötchen vom Vortag","hinweis":""},{"menge":1,"einheit":"Stück","name":"Maistortilla","hinweis":""}]},{"gruppe":"Gewürze und Schokolade","liste":[{"menge":1,"einheit":"Stück","name":"Zimtstange (Ceylon, ca. 3 cm)","hinweis":"Ceylonzimt ist milder und passender"},{"menge":4,"einheit":"Stück","name":"Gewürznelken","hinweis":""},{"menge":8,"einheit":"Stück","name":"schwarze Pfefferkörner","hinweis":""},{"menge":1,"einheit":"TL","name":"Koriandersamen","hinweis":""},{"menge":1,"einheit":"TL","name":"Anissamen","hinweis":""},{"menge":60,"einheit":"g","name":"mexikanische Schokolade (z. B. Ibarra)","hinweis":"Ersatz: 50 g Zartbitterschokolade + 1 Msp. Zimt"},{"menge":1,"einheit":"l","name":"Hühnerbrühe","hinweis":"aus dem Garsud der Hähnchenschenkel"},{"menge":4,"einheit":"EL","name":"Schweineschmalz oder Pflanzenöl","hinweis":""},{"menge":null,"einheit":"","name":"Zucker und Salz","hinweis":"zum Abschmecken"}]}],"ausruestung":["großer Topf oder Bräter","Standmixer (leistungsstark)","Pfanne","Sieb","Holzlöffel","Küchentuch zum Abdecken"],"schritte":[{"titel":"Mise en place","aktion":"vorbereiten","text":"Wiege alle Zutaten ab und stelle sie in Gruppen nebeneinander: Chilis, Nüsse und Samen, Gewürze, Gemüse und Brot. Mole ist ein Gericht mit vielen Schritten, und wenn alles bereitsteht, behältst du den Überblick und vermeidest, dass etwas anbrennt. Schneide die Banane in dicke Scheiben, halbiere die Tomaten und Tomatillos, würfle die Zwiebel und zerbrich Tortilla und Brot in grobe Stücke. Lege außerdem eine große Schüssel für die gerösteten Zutaten bereit, in die du später alles gemeinsam gibst.","dauer":15,"tipp":""},{"titel":"Hähnchen garen und Brühe gewinnen","aktion":"kochen","text":"Gib das Fleisch mit der halbierten Zwiebel, dem Knoblauch und dem Salz in einen großen Topf und bedecke es mit etwa 1,5 Litern kaltem Wasser. Bringe alles langsam zum Kochen, schöpfe den grauen Schaum ab und lass es bei kleiner Hitze 40 Minuten sanft simmern. Das Fleisch ist gar, wenn sich die Keulen am Knochen leicht lösen lassen. Nimm das Fleisch heraus, hebe die Brühe auf und lass das Fleisch zugedeckt beiseite; es wird später in der Sauce erwärmt.","dauer":40,"tipp":"Die Brühe nicht wegschütten – sie bildet später die Flüssigkeit der Mole."},{"titel":"Chilis entkernen, rösten und einweichen","aktion":"vorbereiten","text":"Entferne die Stiele der Chilis, schlitze sie auf und löse Kerne und Adern. Röste die Chilihälften in einer trockenen Pfanne bei mittlerer Hitze pro Seite 10 bis 15 Sekunden, bis sie duften und sich leicht dunkler färben; sie dürfen nicht rauchen. Gib sie in eine Schüssel, übergieße sie mit heißem Wasser und lass sie 30 Minuten einweichen, bis sie weich und dunkel sind. Die Mole soll tief und fruchtig schmecken, nicht bitter – deshalb lieber zu kurz als zu lange rösten.","dauer":35,"tipp":"Bitteres Einweichwasser verwerfen; ein paar Löffel Hühnerbrühe sind der bessere Mixerzusatz."},{"titel":"Nüsse, Samen, Brot und Banane rösten","aktion":"braten","text":"Erhitze zwei Esslöffel Schmalz in einer großen Pfanne und röste zuerst die Mandeln 2 bis 3 Minuten goldbraun, dann die Erdnüsse, den Sesam (nur 30 Sekunden, er verbrennt schnell) und die Rosinen, bis sie aufgebläht sind. Brate anschließend Brot und Tortilla dunkelgolden an und zuletzt die Bananenscheiben, bis sie weich und braun karamellisiert sind. Alles kommt nacheinander in eine große Schüssel. Es soll nussig und leicht süß duften – ein Hinweis, dass die Aromen aufgegangen sind.","dauer":15,"tipp":""},{"titel":"Gewürze rösten","aktion":"braten","text":"Röste Zimt, Nelken, Pfeffer, Koriander und Anis in einer trockenen kleinen Pfanne bei niedriger Hitze etwa 1 Minute, bis sie duften. Schwenke die Pfanne ständig, damit nichts verbrennt; Gewürze werden binnen Sekunden bitter. Gib sie zu den gerösteten Nüssen in die Schüssel. Ganz gemahlen werden sie erst im Mixer, wo sie sich mit Nüssen und Chilis zu einer gleichmäßigen Paste verbinden.","dauer":3,"tipp":""},{"titel":"Tomaten und Zwiebel anbraten","aktion":"braten","text":"Gib in dieselbe Pfanne die Zwiebel, Tomaten und Tomatillos und brate sie 8 bis 10 Minuten bei mittlerer bis hoher Hitze, bis sie weich zerfallen und an einigen Stellen dunkle Röstflecken haben. Das gibt Süße und leichte Säure, die später die Schwere von Nüssen und Schokolade ausgleicht. Gib die Mischung zu den anderen gerösteten Zutaten in die Schüssel.","dauer":10,"tipp":""},{"titel":"Alles pürieren","aktion":"puerieren","text":"Gib die abgetropften Chilis mit einem Teil der gerösteten Zutaten und etwa 200 Millilitern Hühnerbrühe in den Standmixer und püriere in mehreren Durchgängen 2 bis 3 Minuten, bis eine glatte, dunkle Paste entsteht. Streiche sie bei Bedarf durch ein Sieb, damit keine Häutchen oder Nussstückchen bleiben; die Textur der fertigen Mole soll seidig sein. Wenn der Mixer stockt, gib löffelweise Brühe dazu. Die Paste soll sehr dunkel, fast schokoladig aussehen und intensiv duften.","dauer":10,"tipp":""},{"titel":"Mole in Schmalz braten (sazonar)","aktion":"braten","text":"Erhitze 2 Esslöffel Schmalz in einem breiten Topf bei mittlerer Hitze und gib die Paste auf einmal hinein. Sie spritzt kräftig; rühre deshalb ständig und schütze den Arm. Brate 10 bis 15 Minuten, bis die Paste dunkler wird, sich vom Topfboden löst und das Fett an den Rändern austritt. Dieser Schritt, sazonar, röstet die rohen Aromen weg und bindet das Fett; ohne ihn schmeckt die Mole flach und mehlig.","dauer":15,"tipp":"Wer den Topf nicht ständig rührt, riskiert, dass die Paste am Boden anbrennt und bitter wird."},{"titel":"Köcheln lassen und Schokolade einrühren","aktion":"koecheln","text":"Gieße nach und nach etwa 700 Millilitern heißer Brühe an, rühre glatt und lass die Sauce 45 bis 60 Minuten bei sehr kleiner Hitze blubbern, bis sie dick wie Sahne ist und den Löffel überzieht. Rühre alle 5 Minuten, damit nichts ansetzt. Gib nach 30 Minuten die zerkleinerte Schokolade dazu und rühre, bis sie geschmolzen ist. Schmecke mit Salz und, falls nötig, einer Prise Zucker ab: Die Mole soll tief, leicht süßlich, fruchtig und mit warmer Schärfe schmecken.","dauer":60,"tipp":"Wenn die Sauce zu dick wird, mit Brühe verdünnen; ist sie zu dünn, ohne Deckel weiter einkochen."},{"titel":"Fleisch einlegen und anrichten","aktion":"anrichten","text":"Gib das Fleisch in die Sauce und lass es bei kleiner Hitze 15 Minuten ziehen, damit es die Aromen aufnimmt und durch und durch heiß wird. Serviere je ein Stück mit reichlich Sauce, bestreue es mit Sesam und reiche Reis und warme Tortillas dazu. Mole schmeckt am nächsten Tag noch besser; viele Köchinnen kochen sie bewusst einen Tag vorher. Reste lassen sich portionsweise einfrieren.","dauer":15,"tipp":""}],"profitipps":["Chilis nur kurz anrösten und das Einweichwasser verwerfen – Bitterkeit entsteht hier.","Nüsse und Samen getrennt und nacheinander rösten, weil sie unterschiedlich schnell bräunen.","Die Paste unbedingt in heißem Fett braten (sazonar); das ist der Moment, in dem die Mole ihren Charakter bekommt.","Die Sauce muss lange und sanft köcheln – mindestens 45 Minuten, besser eine Stunde.","Am Vortag kochen: Die Aromen verbinden sich über Nacht erheblich.","Fertige Mole lässt sich portionsweise einfrieren; vor dem Servieren langsam erwärmen und mit Brühe auf die gewünschte Dicke bringen."],"varianten":["Mole negro (Oaxaca): mit Chilhuacle-Chilis und verbranntem Chiliduft","Mole verde mit Kürbiskernen und Tomatillos","Enmoladas: Tortillas in Mole getaucht, gerollt und überbacken"],"beilagen":["Mexikanischer Reis","Frijoles refritos","Maistortillas"],"getraenk":"Kräftiger Rotwein (Tempranillo) oder ein dunkles Bier; traditionell auch Agua de Horchata","koeche":[{"name":"Rick Bayless","bezug":"Seine Rezeptsammlung in Saveur zeigt unter anderem Truthahn in Mole Poblano.","quelle":"https://www.saveur.com/article/Kitchen/SAVEURs-Favorite-Rick-Bayless-Recipes"},{"name":"Enrique Olvera","bezug":"Pflegt im Pujol den Mole madre, der seit über zehn Jahren ununterbrochen reift und alle paar Tage mit frischem Mole gemischt wird.","quelle":"https://guide.michelin.com/us/en/article/features/mexico-city-two-star-pujol-mole"},{"name":"Diana Kennedy","bezug":"Ein Mole-Rezept von ihr diente einem Koch als Grundlage für ein Brunch zu ihren Ehren.","quelle":"https://www.wusf.org/2016-12-08/at-93-diana-kennedy-still-reigns-as-mexicos-feistiest-food-expert"}],"quellen":[{"titel":"Pujol und der Mole Madre (Michelin Guide)","url":"https://guide.michelin.com/us/en/article/features/mexico-city-two-star-pujol-mole"},{"titel":"Our Favorite Rick Bayless Recipes (Saveur)","url":"https://www.saveur.com/article/Kitchen/SAVEURs-Favorite-Rick-Bayless-Recipes"},{"titel":"At 93, Diana Kennedy still reigns as Mexico's feistiest food expert (WUSF/NPR)","url":"https://www.wusf.org/2016-12-08/at-93-diana-kennedy-still-reigns-as-mexicos-feistiest-food-expert"}],"bild":"eintopf","farben":["#4a2616","#7a3b1d","#c9a36a"],"schlagworte":["Festgericht","Mole","Puebla","aufwendig"],"vegetarisch_moeglich":false},{"id":"mexiko-enchiladas-rojas-y-verdes","name":"Enchiladas Rojas und Verdes","originalname":"Enchiladas rojas y verdes","kueche":"mexiko","region":"Zentralmexiko","beliebtheit":91,"hauptkategorie":"fleisch","fleischsorte":"huhn","gang":"hauptgericht","kurz":"Maistortillas, gefüllt mit zartem Hühnchen und in rote Chilisauce und grüne Tomatillosauce getaucht – zweimal Mexiko auf einem Teller.","hintergrund":"Das Wort enchilada bedeutet wörtlich ‚in Chili getaucht‘. Schon vor der spanischen Eroberung bestrichen Azteken Tortillas mit Chilisauce, heute sind Enchiladas in ganz Mexiko Alltagsessen. Die roten Enchiladas (rojas) bekommen ihre Sauce aus Guajillo- und Ancho-Chilis, die grünen (verdes) aus gekochten Tomatillos mit Serrano und Koriander. TasteAtlas nennt Enchiladas als zweithöchstbewertetes mexikanisches Gericht. Wichtig ist der Moment, in dem die Tortilla kurz durch heißes Fett gezogen wird, damit sie in der Sauce nicht zerfällt.","portionen":4,"zeit":{"vorbereitung":45,"garen":60,"ruhen":0},"schwierigkeit":2,"zutaten":[{"gruppe":"Hähnchenfüllung","liste":[{"menge":600,"einheit":"g","name":"Hähnchenbrust oder -schenkel, ohne Haut","hinweis":""},{"menge":0.5,"einheit":"Stück","name":"Zwiebel","hinweis":""},{"menge":2,"einheit":"Zehe","name":"Knoblauch","hinweis":""},{"menge":1,"einheit":"TL","name":"Salz","hinweis":""}]},{"gruppe":"Rote Sauce","liste":[{"menge":4,"einheit":"Stück","name":"getrocknete Guajillo-Chilis","hinweis":""},{"menge":2,"einheit":"Stück","name":"getrocknete Ancho-Chilis","hinweis":""},{"menge":2,"einheit":"Stück","name":"reife Tomaten","hinweis":""},{"menge":0.25,"einheit":"Stück","name":"Zwiebel","hinweis":""},{"menge":2,"einheit":"Zehe","name":"Knoblauch","hinweis":""},{"menge":250,"einheit":"ml","name":"Hühnerbrühe","hinweis":"aus dem Garsud"},{"menge":1,"einheit":"EL","name":"Pflanzenöl","hinweis":"zum Braten der Sauce"}]},{"gruppe":"Grüne Sauce","liste":[{"menge":500,"einheit":"g","name":"Tomatillos, frisch oder aus der Dose","hinweis":"aus der Dose gut abtropfen; Ersatz: unreife grüne Tomaten + Limettensaft"},{"menge":2,"einheit":"Stück","name":"Serrano- oder Jalapeño-Chilis","hinweis":""},{"menge":0.5,"einheit":"Bund","name":"Koriandergrün","hinweis":""},{"menge":0.25,"einheit":"Stück","name":"Zwiebel","hinweis":""},{"menge":1,"einheit":"Zehe","name":"Knoblauch","hinweis":""}]},{"gruppe":"Zum Füllen und Überbacken","liste":[{"menge":12,"einheit":"Stück","name":"Maistortillas (ca. 15 cm)","hinweis":"Maistortillas aus dem Laden oder selbst gemacht"},{"menge":150,"einheit":"ml","name":"Pflanzenöl","hinweis":"zum Durchziehen der Tortillas"},{"menge":100,"einheit":"g","name":"Queso fresco oder milder Feta","hinweis":"zerbröselt"},{"menge":100,"einheit":"g","name":"Crema oder Schmand","hinweis":""},{"menge":1,"einheit":"Stück","name":"weiße Zwiebel","hinweis":"in dünnen Ringen"},{"menge":null,"einheit":"","name":"Salz","hinweis":"nach Geschmack"}]}],"ausruestung":["Topf","Standmixer","Pfanne für Tortillas","Auflaufform (ca. 20 x 30 cm)","Küchenzange"],"schritte":[{"titel":"Mise en place","aktion":"vorbereiten","text":"Schneide die Zwiebelhälfte grob, schäle den Knoblauch, stelle Chilis, Tomaten und Tomatillos bereit und lege Zange, Auflaufform, Pfanne und Mixer griffbereit. Zerreiße den Queso fresco in kleine Brocken, schneide die weiße Zwiebel in dünne Ringe und lasse den Schmand glatt rühren, damit er später fließt. Heize noch nichts vor: Der Backofen wird erst vor dem Überbacken gebraucht. Wenn die Zutaten bereitstehen, laufen die Schritte flüssig ineinander.","dauer":10,"tipp":""},{"titel":"Hähnchen garen","aktion":"kochen","text":"Lege das Fleisch mit Zwiebel, Knoblauch und Salz in einen Topf, bedecke es mit kaltem Wasser und bringe es langsam zum Kochen. Reduziere die Hitze, schöpfe Schaum ab und lass es etwa 20 Minuten leise simmern, bis das Fleisch innen weiß und fest ist (Kerntemperatur 74 °C). Nimm es heraus, lass es 10 Minuten abkühlen und zupfe es mit zwei Gabeln in feine Fasern. Die Brühe hebst du für die rote Sauce und die Befeuchtung der Füllung auf; sie ist deutlich besser als gekaufte Brühe.","dauer":30,"tipp":""},{"titel":"Rote Chilis rösten und einweichen","aktion":"vorbereiten","text":"Entferne bei den Guajillo- und Ancho-Chilis Stiel und Kerne und röste die Hälften in einer trockenen Pfanne pro Seite 10 bis 15 Sekunden, bis sie nach Rauch duften. Übergieße sie mit heißem Wasser und lass sie 20 Minuten quellen, bis sie weich sind. Röste in der Pfanne auch Tomate, Zwiebel und Knoblauch an, bis sie braune Stellen haben; das gibt der roten Sauce Rauchigkeit. Lieber zu kurz als zu lange rösten – verbrannte Chilis machen die Sauce bitter.","dauer":25,"tipp":""},{"titel":"Rote Sauce pürieren und einkochen","aktion":"puerieren","text":"Gib Chilis, geröstetes Gemüse und etwa 150 Millilitern Brühe in den Mixer und püriere sehr fein; streiche die Sauce durch ein Sieb. Erhitze einen Esslöffel Öl in einem Topf bei mittlerer Hitze, gib die Sauce hinein (sie spritzt) und lass sie 8 bis 10 Minuten köcheln, bis sie dicker, glänzend und dunkler ist. Schmecke mit Salz ab; sie soll fruchtig, mild-rauchig und leicht süß schmecken. Rick Bayless kocht seine Chilisaucen in Öl ein, bis sie sämig sind – dieser Schritt vertieft das Aroma.","dauer":15,"tipp":""},{"titel":"Grüne Sauce kochen und pürieren","aktion":"kochen","text":"Koche die Tomatillos mit den Chilis in einem Topf mit knapp Wasser 5 bis 8 Minuten, bis sie ihre leuchtend grüne Farbe zu einem matten Olivgrün verändern und weich werden. Gieße ab und püriere sie mit Zwiebel, Knoblauch, Koriander und etwas Salz zu einer cremigen Sauce. Sie schmeckt frisch, säuerlich und leicht scharf. Wenn sie sehr sauer ist, hilft eine Prise Zucker; wenn sie zu dünn ist, kurz einkochen.","dauer":12,"tipp":""},{"titel":"Tortillas durchziehen","aktion":"frittieren","text":"Erhitze das Pflanzenöl in einer Pfanne bei mittlerer Hitze auf etwa 160 Grad, bis ein Stück Tortilla leise brutzelt. Ziehe jede Tortilla mit der Zange 5 bis 10 Sekunden pro Seite durchs Öl; sie soll weich und biegsam werden, aber nicht knusprig. Lege sie auf Küchenpapier. Dieser Schritt dichtet die Tortilla ab, damit sie in der Sauce nicht zerfällt und nicht matschig wird. Arbeite zügig, denn kalte Tortillas reißen beim Rollen.","dauer":10,"tipp":"Die Tortillas sollen aussehen wie leicht glänzende Stoffbahnen, nicht wie Chips."},{"titel":"Füllen und aufrollen","aktion":"rollen","text":"Tauche jede Tortilla kurz in die rote oder grüne Sauce, lege sie in die Auflaufform, gib etwa zwei Esslöffel Hähnchen darauf und rolle sie fest. Fülle die Form so, dass die Rollen nah aneinander liegen; so bleiben sie in Form. Die Hälfte der Form füllst du mit roter, die andere Hälfte mit grüner Sauce – oder machst zwei kleine Formen, je nach Lust. Gieße die restliche Sauce über die Rollen und achte darauf, dass die Enden bedeckt sind, damit sie nicht austrocknen.","dauer":10,"tipp":""},{"titel":"Überbacken","aktion":"ueberbacken","text":"Heize den Backofen auf 200 Grad Ober-/Unterhitze (180 Grad Umluft) vor und backe die Enchiladas 12 bis 15 Minuten, bis die Sauce an den Rändern Blasen wirft und die Rollen durch und durch heiß sind. Streue Queso fresco darüber und lass ihn noch eine Minute anschmelzen. Der Käse soll weich werden, aber nicht braun; wer eine Kruste mag, schaltet für 2 Minuten den Grill dazu. Lass die Form 3 Minuten ruhen, bevor du servierst, damit die Rollen sich setzen.","dauer":15,"tipp":""},{"titel":"Anrichten","aktion":"anrichten","text":"Serviere zwei bis drei Enchiladas pro Person, streue Zwiebelringe und Koriander darüber und gib einen Klecks Crema oder Schmand dazu. Gieße bei Bedarf noch ein wenig heiße Sauce an. Iss sie sofort, solange die Tortillas noch weich und die Sauce heiß ist; nach 15 Minuten saugen sich die Tortillas voll und zerfallen. Dazu passen Reis und Frijoles refritos.","dauer":0,"tipp":"Halb rot, halb grün sieht auf dem Tisch hübsch aus und lässt jeden seine Lieblingssauce wählen."}],"profitipps":["Tortillas kurz durch heißes Öl ziehen – das verhindert, dass sie in der Sauce zerfallen.","Chilis nur kurz rösten und nicht verbrennen.","Rote Sauce in Öl einkochen, bis sie sämig ist; das konzentriert das Aroma.","Grüne Sauce nur kurz garen, damit sie frisch bleibt.","Enchiladas sofort essen; aufgewärmt werden sie matschig."],"varianten":["Enchiladas suizas mit Sahnesauce und Käse überbacken","Enmoladas mit Mole poblano statt Chilisauce","Vegetarisch mit Bohnen, Pilzen oder Spinat gefüllt"],"beilagen":["Mexikanischer Reis","Frijoles refritos","Salat mit Limettendressing"],"getraenk":"Helles Bier mit Limette oder Agua de Jamaica","koeche":[{"name":"Rick Bayless","bezug":"Seine Mole-Coloradito-Enchiladas zeigen die klassische Technik: Chilipüree in Öl dick einkochen, Tortillas leicht erwärmen und durch die Sauce ziehen.","quelle":"https://www.rickbayless.com/recipe/mole-coloradito-enchiladas/"}],"quellen":[{"titel":"Mole Coloradito Enchiladas (rickbayless.com)","url":"https://www.rickbayless.com/recipe/mole-coloradito-enchiladas/"},{"titel":"Tacos al Pastor Named The World's Tastiest Dish (Journey Mexico)","url":"https://www.journeymexico.com/?p=32652"}],"bild":"auflauf","farben":["#a1311f","#6f9a2f","#f4e6c0"],"schlagworte":["Alltagsessen","zwei Saucen","Tortilla"],"vegetarisch_moeglich":true},{"id":"mexiko-tacos-de-pescado-baja","name":"Tacos de pescado im Baja-Stil","originalname":"Tacos de pescado estilo Baja","kueche":"mexiko","region":"Baja California","beliebtheit":90,"hauptkategorie":"fisch","fischsorte":"fisch","gang":"hauptgericht","kurz":"Knusprig frittierter Fisch im Bierteig, kalter Kohl, spritzige Crema und frische Pico de gallo in warmen Maistortillas – der Strandklassiker von der Pazifikküste.","hintergrund":"Fischtacos stammen aus Baja California, dem schmalen Küstenstreifen im Nordwesten Mexikos, und werden dort an Straßenständen und Strandbuden verkauft. Der Fisch wird frittiert oder gegrillt und kommt mit Kohl oder Salat, Pico de gallo und einer säuerlichen Sauce auf eine warme Tortilla. In den USA wurden sie vor allem durch die Fastfood-Kette Rubio's bekannt und sind heute besonders an der Westküste Alltag. Die Kombination aus heißem, knusprigem Fisch und eiskaltem, knackigem Kohl ist das Herzstück: Der Temperaturkontrast macht den Taco aus. Dazu gehören immer Limette und eine scharfe Salsa zum Selbstwürzen.","portionen":4,"zeit":{"vorbereitung":40,"garen":20,"ruhen":20},"schwierigkeit":2,"zutaten":[{"gruppe":"Für den Fisch","liste":[{"menge":600,"einheit":"g","name":"festes, weißes Fischfilet ohne Haut und Gräten","hinweis":"gut geeignet sind Seehecht, Schellfisch, Seelachs oder Kabeljau aus MSC-Fang, auch Tiefkühlware (vollständig aufgetaut und trocken getupft)"},{"menge":2,"einheit":"Stück","name":"Limetten","hinweis":"für die Marinade und zum Servieren"},{"menge":1,"einheit":"TL","name":"Salz","hinweis":""},{"menge":0.5,"einheit":"TL","name":"Knoblauchpulver","hinweis":""},{"menge":0.5,"einheit":"TL","name":"Kreuzkümmel, gemahlen","hinweis":""}]},{"gruppe":"Für den Bierteig und zum Frittieren","liste":[{"menge":150,"einheit":"g","name":"Weizenmehl Type 405","hinweis":"plus 3 EL zum Wenden des Fischs"},{"menge":1,"einheit":"TL","name":"Backpulver","hinweis":""},{"menge":1,"einheit":"TL","name":"Salz","hinweis":""},{"menge":0.5,"einheit":"TL","name":"Paprikapulver, edelsüß","hinweis":""},{"menge":250,"einheit":"ml","name":"helles Bier (Pils oder Lager), eiskalt","hinweis":"alkoholfreies Bier funktioniert ebenso; wichtig ist die Kälte und die Kohlensäure"},{"menge":1,"einheit":"l","name":"Pflanzenöl zum Frittieren","hinweis":"Raps- oder Erdnussöl, hoch erhitzbar"}]},{"gruppe":"Für die Crema","liste":[{"menge":100,"einheit":"g","name":"Mayonnaise","hinweis":""},{"menge":100,"einheit":"g","name":"Crème fraîche oder saure Sahne","hinweis":"Mexikanische Crema ist milder; Crème fraîche kommt am nächsten"},{"menge":1,"einheit":"Stück","name":"Limette, Saft und Abrieb","hinweis":""},{"menge":1,"einheit":"TL","name":"Chipotle in Adobo, fein gehackt","hinweis":"optional; ersatzweise etwas scharfe Sauce (Tabasco, Valentina)"}]},{"gruppe":"Zum Belegen","liste":[{"menge":0.25,"einheit":"Stück","name":"Weißkohl","hinweis":"sehr fein geschnitten oder gehobelt"},{"menge":3,"einheit":"Stück","name":"reife Tomaten","hinweis":""},{"menge":0.5,"einheit":"Stück","name":"weiße Zwiebel","hinweis":"ersatzweise rote Zwiebel"},{"menge":1,"einheit":"Stück","name":"Jalapeño","hinweis":"entkernt für weniger Schärfe"},{"menge":0.5,"einheit":"Bund","name":"Koriandergrün","hinweis":""},{"menge":12,"einheit":"Stück","name":"Maistortillas (ca. 12–15 cm)","hinweis":"im Supermarkt oder Latino-Laden; Weizentortillas gehen zur Not auch"}]}],"ausruestung":["Schwerer Topf oder Fritteuse","Küchenthermometer","Schaumkelle","Gitterrost mit Küchenpapier","Trockene Pfanne oder Grillpfanne zum Erwärmen der Tortillas"],"schritte":[{"titel":"Mise en place: alles bereitstellen","aktion":"vorbereiten","text":"Tupfe die Fischfilets mit Küchenpapier gründlich trocken und schneide sie schräg in fingerdicke Streifen von etwa 2 cm Breite und 8 cm Länge. Gleich große Stücke garen gleichmäßig und passen später gut in die Tortilla. Presse die Limetten aus, schneide den Kohl in hauchdünne Streifen und stelle ihn kalt. Wiege Mehl, Backpulver und Gewürze ab, hole das Bier erst im letzten Moment aus dem Kühlschrank. Lege Küchenpapier auf ein Blech, damit der frittierte Fisch später sofort abtropfen kann.","dauer":0,"tipp":"Je trockener der Fisch, desto besser haftet der Teig und desto weniger spritzt das Öl."},{"titel":"Fisch würzen und kurz ziehen lassen","aktion":"marinieren","text":"Gib die Fischstreifen in eine Schüssel und beträufele sie mit dem Saft von einer Limette. Bestreue sie mit Salz, Knoblauchpulver und Kreuzkümmel und wende alles vorsichtig mit den Händen, bis jedes Stück gleichmäßig überzogen ist. Lass den Fisch 15 bis 20 Minuten im Kühlschrank ruhen. Die Säure festigt das Eiweiß an der Oberfläche leicht und gibt Frische; länger als 30 Minuten solltest du nicht marinieren, sonst wird das Fleisch an der Oberfläche trüb und fest. Tupfe den Fisch vor dem Panieren noch einmal trocken.","dauer":20,"tipp":"Mariniere nie über 30 Minuten – die Limettensäure „gart“ den Fisch sonst schon an."},{"titel":"Pico de gallo hacken","aktion":"hacken","text":"Halbiere die Tomaten, entferne die Kerne mit einem Teelöffel und schneide das feste Fruchtfleisch in 5-mm-Würfel; so wird die Salsa nicht wässrig. Hacke die Zwiebel ähnlich fein, entkerne die Jalapeño und schneide sie in winzige Würfel. Hacke den Koriander grob. Vermische alles mit dem Saft einer halben Limette und einer guten Prise Salz und lasse die Salsa mindestens 10 Minuten durchziehen. Sie sollte frisch, leicht scharf und knackig riechen und schmecken; probiere und gib bei Bedarf noch Salz oder Limette hinzu.","dauer":10,"tipp":""},{"titel":"Crema anrühren und Kohl vorbereiten","aktion":"mischen","text":"Verrühre Mayonnaise und Crème fraîche in einer kleinen Schüssel mit dem restlichen Limettensaft, etwas Abrieb und dem fein gehackten Chipotle. Schmecke mit einer Prise Salz ab: Die Sauce soll cremig, deutlich säuerlich und nur leicht rauchig-scharf sein. Fülle sie in eine Flasche oder einen Gefrierbeutel mit abgeschnittener Ecke, dann kannst du sie später sauber auf die Tacos streifen. Salze den geschnittenen Kohl nur ganz leicht und stelle ihn bis zum Anrichten kalt, damit er knackig bleibt und der heiße Fisch den Temperaturkontrast liefert.","dauer":5,"tipp":"Kohl erst kurz vor dem Servieren salzen – Salz zieht Wasser und macht ihn weich."},{"titel":"Bierteig rühren","aktion":"mischen","text":"Vermenge in einer Schüssel Mehl, Backpulver, Salz und Paprikapulver. Gieße das eiskalte Bier auf einmal dazu und rühre mit einem Schneebesen nur so lange, bis ein glatter, dickflüssiger Teig entsteht – er soll wie flüssige Sahne vom Löffel laufen und eine Schicht auf dem Löffelrücken hinterlassen. Ein paar kleine Klümpchen sind in Ordnung, zu langes Rühren aktiviert das Gluten und macht die Hülle zäh statt knusprig. Der Teig sollte kalt bleiben und leise schäumen; rühre ihn erst direkt vor dem Frittieren an, damit die Kohlensäure nicht entweicht.","dauer":0,"tipp":"Eiskaltes Bier und nicht zu viel Rühren sind das ganze Geheimnis der luftigen Teighülle."},{"titel":"Öl auf 180 °C erhitzen","aktion":"vorbereiten","text":"Erhitze das Öl in einem schweren Topf, der höchstens zu einem Drittel gefüllt ist, auf genau 180 °C; prüfe die Temperatur mit einem Küchenthermometer. Ohne Thermometer kannst du den Stiel eines Holzlöffels hineinhalten: Steigen sofort feine Bläschen auf, ist das Öl bereit. Ist das Öl zu kühl, saugt der Teig Fett auf und wird schwer; ist es zu heiß, wird er außen dunkel, während der Fisch innen noch roh bleibt. Halte einen Deckel in Reichweite für den Notfall bei Fettbrand und gieße niemals Wasser ins heiße Öl.","dauer":10,"tipp":"Halte die Temperatur zwischen den Portionen bei 175–180 °C; sie sinkt beim Einlegen ab."},{"titel":"Fisch backen: in kleinen Portionen frittieren","aktion":"frittieren","text":"Wende die trocken getupften Fischstreifen kurz in dem zusätzlichen Mehl, schüttele überschüssiges ab und ziehe sie dann durch den Bierteig. Lass den Teig kurz abtropfen und lege die Stücke einzeln und weg von dir ins heiße Öl. Frittiere höchstens 4 bis 5 Stücke gleichzeitig, sonst fällt die Temperatur ab. Nach etwa 3 bis 4 Minuten ist die Hülle goldbraun, blasig und knusprig, und der Fisch schwimmt oben. Er ist gar, wenn er sich im Kern leicht mit der Gabel teilen lässt, weiß und saftig ist und die Mitte etwa 62 °C erreicht hat.","dauer":12,"tipp":"Wende die Stücke einmal zwischendurch mit der Schaumkelle, damit beide Seiten gleichmäßig bräunen."},{"titel":"Abtropfen und kurz halten","aktion":"abseihen","text":"Hebe den fertigen Fisch mit der Schaumkelle aus dem Öl, lasse ihn kurz abtropfen und lege ihn auf das mit Küchenpapier ausgelegte Blech oder noch besser auf einen Gitterrost. So bleibt die Unterseite knusprig, statt im eigenen Dampf weich zu werden. Streue sofort eine Prise Salz darüber, solange die Oberfläche noch glänzt. Halte die erste Portion im Ofen bei 80 °C warm, während die nächsten backen. Zwischen den Portionen schöpfst du lose Teigreste aus dem Öl, damit sie nicht verbrennen und bitter schmecken.","dauer":0,"tipp":""},{"titel":"Tortillas erwärmen","aktion":"braten","text":"Erhitze eine trockene Pfanne oder Grillpfanne bei mittlerer bis hoher Hitze und lege die Tortillas einzeln für etwa 30 Sekunden pro Seite hinein. Sie sind richtig, wenn sie weich, biegsam und leicht gefleckt sind und nach geröstetem Mais duften. Wickle die fertigen Tortillas sofort in ein sauberes Küchentuch, in dem sie über den Dampf warm und geschmeidig bleiben. Kalte oder trocken gewordene Maistortillas brechen beim Falten; deshalb erwärmst du sie erst, wenn der Fisch fast fertig ist.","dauer":5,"tipp":"Zwei Tortillas übereinander ergeben den klassischen Straßen-Taco, der auch saftigen Fisch trägt."},{"titel":"Tacos zusammensetzen und servieren","aktion":"anrichten","text":"Lege auf jede warme Tortilla zuerst eine kleine Handvoll Kohl, dann zwei Stücke heißen Fisch, darauf einen Löffel Pico de gallo und zuletzt einen Streifen Crema. Falte die Tortilla zusammen und serviere die Tacos sofort mit Limettenspalten und zusätzlicher scharfer Salsa. Der Fisch muss noch knistern, der Kohl kalt und knackig sein. Wartest du zu lange, weicht die Tortilla durch und der Teig verliert seine Kruste, also baue die Tacos erst direkt am Tisch oder wenige Minuten vor dem Essen zusammen.","dauer":0,"tipp":"Ein Spritzer Limette über den fertigen Taco hebt die Frittiernote und gleicht die Cremigkeit aus."}],"profitipps":["Bier und Mehl bleiben eiskalt, der Teig wird erst unmittelbar vor dem Backen angerührt – so bildet die Kohlensäure eine luftige, knusprige Hülle.","Fisch immer sehr gut trocken tupfen und leicht mehlieren, sonst rutscht der Teig ab.","Das Öl bei 175–180 °C halten und nur wenige Stücke gleichzeitig einlegen; sinkt die Temperatur, wird der Fisch fettig.","Den Temperaturkontrast nicht vergessen: heißer Fisch auf kaltem Kohl mit kühler Crema.","Statt zu frittieren kannst du den Fisch auch grillen (Baja bietet beides); dann einfach in Öl und Gewürzen marinieren und 2–3 Minuten pro Seite auf sehr heißer Rillenpfanne garen."],"varianten":["Gegrillte Fischtacos: Fischstreifen in Öl, Limette, Kreuzkümmel und Chili marinieren und auf der Grillpfanne garen.","Garnelentacos (tacos de camarón) im gleichen Bierteig.","Mit Avocado-Salsa oder Guacamole statt Crema.","Kalifornische Version mit Coleslaw und Chipotle-Mayonnaise."],"beilagen":["Mexikanischer Reis","Schwarze Bohnen","Mais-Salsa","Limetten- und Chili-Spalten"],"getraenk":"Eiskaltes helles Bier (Lager) mit Limettenspalte, alternativ Agua fresca de jamaica oder Margarita.","koeche":[],"quellen":[{"titel":"Fish taco – Wikipedia","url":"https://en.wikipedia.org/wiki/Fish_taco"},{"titel":"Coastal Mexican food: classic Mexican seafood","url":"https://www.amexessentials.com/coastal-mexican-food-classic-mexican-seafood/"}],"bild":"taco","farben":["#e3b04b","#7fa64b","#f3e9d2"],"schlagworte":["Streetfood","Baja California","Strandküche","Frittiert"],"vegetarisch_moeglich":false},{"id":"mexiko-carnitas","name":"Carnitas","originalname":"Carnitas michoacanas","kueche":"mexiko","region":"Michoacán","beliebtheit":90,"hauptkategorie":"fleisch","fleischsorte":"schwein","gang":"hauptgericht","kurz":"Schweinefleisch, im eigenen Fett butterweich geschmort und am Ende goldbraun und knusprig gebraten – Streetfood-Ikone aus Michoacán.","hintergrund":"Carnitas bedeutet ‚kleine Fleischstücke‘ und stammt aus Michoacán, wo das Fleisch traditionell in großen Kupferkesseln (cazos) in Schmalz gegart wird. Dabei werden verschiedene Teile vom Schwein gemischt, von mageren Stücken bis zu fettem Bauch, damit jeder Bissen anders ist. Am Straßenstand wird das Fleisch nach Gewicht verkauft, gehackt und in Tortillas mit Zwiebel, Koriander und Salsa gegessen. TasteAtlas führt sowohl Tacos de carnitas (Platz 19) als auch Carnitas (Platz 36) in der Liste der 100 besten Gerichte der Welt. Zu Hause gelingt das Gericht im Bräter im Ofen erstaunlich nah am Original.","portionen":6,"zeit":{"vorbereitung":25,"garen":210,"ruhen":0},"schwierigkeit":2,"zutaten":[{"gruppe":"Fleisch und Garflüssigkeit","liste":[{"menge":2,"einheit":"kg","name":"Schweinenacken (Schulter), mit etwas Fettrand","hinweis":"in 5 cm große Stücke geschnitten"},{"menge":200,"einheit":"g","name":"Schweineschmalz","hinweis":"ersatzweise Gänseschmalz oder neutrales Öl; Schmalz gibt den echten Geschmack"},{"menge":2,"einheit":"Stück","name":"Orangen","hinweis":"Saft und die ausgedrückten Hälften"},{"menge":1,"einheit":"Stück","name":"Zwiebel, halbiert","hinweis":""},{"menge":6,"einheit":"Zehe","name":"Knoblauch","hinweis":""},{"menge":2,"einheit":"Stück","name":"Lorbeerblätter","hinweis":""},{"menge":1,"einheit":"Stange","name":"Zimt","hinweis":""},{"menge":1,"einheit":"TL","name":"getrockneter Oregano","hinweis":""},{"menge":2,"einheit":"TL","name":"Salz","hinweis":""},{"menge":200,"einheit":"ml","name":"Milch","hinweis":"optional; sorgt für gleichmäßige Bräunung durch Milchzucker"}]},{"gruppe":"Zum Servieren","liste":[{"menge":18,"einheit":"Stück","name":"Maistortillas","hinweis":""},{"menge":1,"einheit":"Stück","name":"weiße Zwiebel","hinweis":"fein gehackt"},{"menge":1,"einheit":"Bund","name":"Koriandergrün","hinweis":""},{"menge":2,"einheit":"Stück","name":"Limetten","hinweis":"in Spalten"},{"menge":null,"einheit":"","name":"Salsa verde oder Salsa roja","hinweis":"siehe Rezept Salsa Roja und Salsa Verde"}]}],"ausruestung":["Schmortopf oder Bräter mit Deckel (Gusseisen)","große Pfanne","Fleischzange","Fettsieb"],"schritte":[{"titel":"Mise en place","aktion":"vorbereiten","text":"Schneide den Schweinenacken in Stücke von etwa 5 Zentimetern Kantenlänge, lasse dabei Fettränder dran, denn das Fett macht die Carnitas saftig. Salze die Fleischstücke mit zwei Teelöffeln Salz und lass sie 15 Minuten bei Raumtemperatur ruhen. Presse die Orangen aus und halte die ausgedrückten Hälften bereit, schäle den Knoblauch und halbiere die Zwiebel. Heize den Backofen auf 160 Grad Ober-/Unterhitze (140 Grad Umluft) vor.","dauer":15,"tipp":""},{"titel":"Fleisch und Fett im Bräter erhitzen","aktion":"anbraten","text":"Gib das Schmalz in den Bräter und erhitze es bei mittlerer Hitze, bis es geschmolzen ist und leicht schimmert. Lege die Fleischstücke in einer Schicht hinein; sie sollen eng liegen, aber nicht übereinander. Es soll sanft blubbern, nicht wild spritzen. Das Fleisch muss nicht gebräunt werden, denn das Braten kommt später; jetzt geht es darum, es im Fett langsam zu garen, wie im Kupferkessel (cazo) in Michoacán.","dauer":5,"tipp":""},{"titel":"Aromen zugeben","aktion":"schmoren","text":"Gib Orangensaft, die ausgedrückten Orangenhälften, Zwiebel, Knoblauch, Lorbeer, Zimt, Oregano und, falls gewünscht, die Milch zum Fleisch. Die Flüssigkeit soll das Fleisch nur zu etwa zwei Dritteln bedecken; das Fleisch gart gleichzeitig im Fett und im Dampf. Bringe alles zum Köcheln, decke den Bräter ab und stelle ihn in den vorgeheizten Ofen. Orangen geben dezente Säure und Farbe, die Milch bräunt später gleichmäßig.","dauer":5,"tipp":""},{"titel":"Langsam garen","aktion":"schmoren","text":"Lass das Fleisch 2 bis 2,5 Stunden bei 160 Grad schmoren. Wende die Stücke nach der Hälfte der Zeit einmal. Es ist fertig, wenn sich ein Stück mit der Gabel ohne Widerstand zerteilen lässt und der Bräter leise blubbert. Die Flüssigkeit sollte weitgehend verdampft sein und das Fleisch im klaren Fett liegen. Die Gewürze schmecken jetzt weich und gleichmäßig im Fleisch.","dauer":150,"tipp":""},{"titel":"Deckel ab und Flüssigkeit einkochen","aktion":"reduzieren","text":"Nimm den Deckel ab, erhöhe die Hitze auf 200 Grad Ober-/Unterhitze und lass das Fleisch weitere 30 Minuten offen garen. Die Flüssigkeit verdampft, das Fett bleibt zurück, und die Oberfläche beginnt zu bräunen. Wende die Stücke einmal und achte darauf, dass nichts am Rand verbrennt. Das Fleisch soll jetzt schimmernd goldbraun sein und glänzen, aber noch weich bleiben.","dauer":30,"tipp":""},{"titel":"Fett abschöpfen und Fleisch knusprig braten","aktion":"braten","text":"Hebe die Fleischstücke mit der Zange auf ein Blech und zupfe sie mit zwei Gabeln in grobe, daumengroße Stücke. Erhitze eine große Pfanne bei hoher Hitze mit zwei Esslöffeln des abgeschöpften Garfetts und brate das Fleisch portionsweise 3 bis 4 Minuten, bis die Ränder dunkelbraun und knusprig sind. Es soll knistern und nach Röstaromen duften. Gieße zwischendurch einen Schuss Orangensaft an, damit die Kruste glänzt.","dauer":12,"tipp":"Die Pfanne nicht überfüllen, sonst dünstet das Fleisch und wird nicht knusprig."},{"titel":"Salsa und Tortillas bereitstellen","aktion":"vorbereiten","text":"Erwärme die Tortillas in einer trockenen Pfanne 30 Sekunden pro Seite, bis sie weich und biegsam sind, und halte sie in einem Tuch warm. Hacke Zwiebel und Koriander und schneide die Limetten in Spalten. Bereite die Salsa vor und stelle alles auf den Tisch, damit jeder sich seine Tacos selbst belegen kann. Das Fleisch soll heiß aus der Pfanne kommen, nicht warm gehalten werden, damit die Kruste bleibt.","dauer":5,"tipp":""},{"titel":"Anrichten","aktion":"anrichten","text":"Gib jeweils zwei Esslöffel Carnitas in eine warme Tortilla, streue Zwiebel und Koriander darüber, träufle Salsa darauf und drücke einen Spritzer Limette aus. Serviere sofort; die Mischung aus saftig-weichem Inneren und knuspriger Kruste macht das Gericht aus. Reste lassen sich im eigenen Fett im Kühlschrank 5 Tage aufbewahren und in der Pfanne wieder knusprig braten.","dauer":0,"tipp":""}],"profitipps":["Nacken oder Schulter mit Fettanteil nehmen; mageres Fleisch wird trocken.","Das Fleisch langsam im Fett garen und erst am Ende kräftig anbraten.","Orangen und optional Milch sorgen für Farbe und Bräunung.","Zum Knusprigmachen eine sehr heiße Pfanne und kleine Portionen verwenden.","Reste im Fett aufbewahren – so bleiben sie saftig."],"varianten":["Mit Cola oder Bier statt Orangen (im Norden verbreitet)","Carnitas-Torta im Brötchen mit Avocado","Mit Schweinebauch und Innereien (Buche, Cueritos) wie in Michoacán"],"beilagen":["Frijoles refritos","Guacamole","Salsa verde","eingelegte Zwiebeln"],"getraenk":"Kaltes Lagerbier, Mezcal oder Agua de Tamarindo","koeche":[],"quellen":[{"titel":"Uncomplicated Mexican dishes rate among world's best (Guadalajara Reporter)","url":"https://theguadalajarareporter.net/index.php/featured/61332-uncomplicated-mexican-dishes-rate-among-world-s-best"},{"titel":"TasteAtlas: mejor platillo de Mexico, Cochinita pibil (Emprendedor)","url":"https://emprendedor.com/tasteatlas-mejor-platillo-mexico-cochinita-pibil-ranking-2025/"}],"bild":"braten-scheiben","farben":["#9c5b24","#d49a48","#f3dca4"],"schlagworte":["Streetfood","Michoacán","Schmorgericht"],"vegetarisch_moeglich":false},{"id":"mexiko-cochinita-pibil","name":"Cochinita Pibil","originalname":"Cochinita pibil","kueche":"mexiko","region":"Yucatán","beliebtheit":90,"hauptkategorie":"fleisch","fleischsorte":"schwein","gang":"hauptgericht","kurz":"Schweinefleisch in leuchtend roter Achiote-Zitrus-Marinade, in Bananenblättern stundenlang gegart, bis es fast zerfällt – mit säuerlich-scharfen roten Zwiebeln ein Gedicht aus Yucatán.","hintergrund":"Cochinita pibil kommt aus Yucatán und geht auf die Maya zurück: Pib bezeichnet den Erdofen, in dem das Fleisch in Bananenblättern über Stunden gart. Statt Wildtier kam nach der Eroberung das Schwein (cochinita = Ferkel) in die Grube. Die Marinade besteht aus Achiote-Samen, saurer Orange (naranja agria), Knoblauch und Gewürzen und färbt das Fleisch leuchtend orangerot. Serviert wird es in Tacos, Tortas oder Panuchos, immer mit eingelegten roten Zwiebeln und scharfer Habanero-Salsa. In TasteAtlas-Listen erscheint Cochinita pibil unter den bestplatzierten mexikanischen Gerichten.","portionen":6,"zeit":{"vorbereitung":30,"garen":240,"ruhen":720},"schwierigkeit":2,"zutaten":[{"gruppe":"Fleisch und Marinade","liste":[{"menge":1.5,"einheit":"kg","name":"Schweinenacken oder Schulter, ohne Knochen","hinweis":"in 6–8 cm große Stücke geschnitten"},{"menge":50,"einheit":"g","name":"Achiote-Paste","hinweis":"Lateinamerika-Laden oder online; erdig-pfeffrig, färbt kräftig orange"},{"menge":120,"einheit":"ml","name":"frisch gepresster Orangensaft","hinweis":""},{"menge":60,"einheit":"ml","name":"Limettensaft","hinweis":""},{"menge":2,"einheit":"EL","name":"Weißweinessig","hinweis":"Orange + Limette + Essig ersetzen die schwer erhältliche Bitterorange (naranja agria)"},{"menge":6,"einheit":"Zehe","name":"Knoblauch","hinweis":""},{"menge":1,"einheit":"TL","name":"Kreuzkümmel","hinweis":""},{"menge":1,"einheit":"TL","name":"getrockneter Oregano","hinweis":""},{"menge":0.5,"einheit":"TL","name":"gemahlener Piment","hinweis":""},{"menge":0.5,"einheit":"TL","name":"schwarzer Pfeffer","hinweis":""},{"menge":2,"einheit":"TL","name":"Salz","hinweis":""},{"menge":3,"einheit":"Stück","name":"Bananenblätter","hinweis":"TK-Ware aus dem Asia- oder Lateinamerika-Laden; ersatzweise Backpapier und Alufolie"}]},{"gruppe":"Eingelegte Zwiebeln","liste":[{"menge":2,"einheit":"Stück","name":"rote Zwiebeln","hinweis":"in dünne Ringe geschnitten"},{"menge":120,"einheit":"ml","name":"Limettensaft","hinweis":""},{"menge":1,"einheit":"Stück","name":"Habanero (oder Chili)","hinweis":"sehr scharf; Ersatz: 1 rote Chili ohne Kerne"},{"menge":0.5,"einheit":"TL","name":"Salz","hinweis":""},{"menge":0.5,"einheit":"TL","name":"Oregano","hinweis":""}]}],"ausruestung":["Schmortopf mit Deckel oder Bräter","Alufolie","Standmixer","Küchenschere"],"schritte":[{"titel":"Mise en place","aktion":"vorbereiten","text":"Schneide den Schweinenacken in etwa 6 bis 8 Zentimeter große Stücke; sie bleiben beim langen Garen saftiger als kleine Würfel. Wiege Marinade und Gewürze ab, presse Orangen und Limetten aus und schäle den Knoblauch. Taue die Bananenblätter bei Bedarf auf, wasche sie ab und schneide die harte Mittelrippe heraus; so lassen sie sich später falten. Heize den Backofen noch nicht vor, denn das Fleisch muss erst mariniert werden.","dauer":15,"tipp":""},{"titel":"Marinade pürieren","aktion":"mischen","text":"Gib Achiote-Paste, Orangensaft, Limettensaft, Essig, Knoblauch, Kreuzkümmel, Oregano, Piment, Pfeffer und Salz in den Mixer und püriere 1 bis 2 Minuten zu einer glatten, kräftig orange-roten Marinade. Sie soll dickflüssig wie Sahne sein und intensiv nach Zitrus, Gewürz und Erde duften. Probiere einen Tropfen: Sie soll sehr kräftig, sauer, salzig und würzig schmecken, denn das Fleisch verdünnt sie stark. Falls sie zu fest ist, gib einen Schuss Orangensaft dazu.","dauer":5,"tipp":"Ein guter Achiote-Block braucht etwas Zeit zum Auflösen; im Mixer geht das schneller als von Hand."},{"titel":"Fleisch marinieren","aktion":"marinieren","text":"Gib die Fleischstücke in eine Schüssel und reibe sie rundum mit der Marinade ein, bis alle Flächen bedeckt sind. Decke die Schüssel ab und stelle sie für mindestens 8, besser 12 bis 24 Stunden in den Kühlschrank. In dieser Zeit dringen Säure und Gewürze tief ein und lockern das Eiweiß; das ist die Grundlage für Aroma und Zartheit. Wende das Fleisch ein- bis zweimal, damit alle Seiten gleichmäßig durchziehen.","dauer":720,"tipp":"Nicht länger als 24 Stunden marinieren, sonst wird das Fleisch durch die Säure mehlig."},{"titel":"Zwiebeln einlegen","aktion":"einlegen","text":"Schneide die roten Zwiebeln in feine Ringe, gib sie in eine Schüssel und übergieße sie mit kochendem Wasser. Nach 30 Sekunden abgießen und abtropfen lassen; das nimmt die Schärfe. Mische sie mit Limettensaft, Salz, Oregano und fein geschnittener Habanero. Lass sie mindestens 1 Stunde ziehen: Sie färben sich pink, werden mild-säuerlich und behalten einen leichten Biss. Im Kühlschrank halten sie sich mehrere Tage.","dauer":60,"tipp":""},{"titel":"Bananenblätter vorbereiten","aktion":"vorbereiten","text":"Halte die Bananenblätter kurz über eine heiße Herdplatte oder tauche sie in kochendes Wasser, bis sie geschmeidig und glänzend sind und nicht mehr reißen. Lege den Boden des Bräters mit zwei Lagen Blättern aus, sodass sie an den Seiten überstehen. So entsteht ein Paket, in dem das Fleisch im eigenen Saft dämpft. Ohne Bananenblätter nimmst du Backpapier und darüber Alufolie.","dauer":5,"tipp":""},{"titel":"Fleisch einpacken","aktion":"vorbereiten","text":"Verteile die marinierten Fleischstücke samt Marinade auf den Blättern und schlage sie darüber zu einem dichten Paket zusammen. Lege ein weiteres Blatt über die Öffnung und decke alles mit Alufolie fest ab. Es darf kein Dampf entweichen, damit das Fleisch beim Garen nicht austrocknet. Der Duft von Bananenblatt und Achiote begleitet das Garen und ist ein typisches Merkmal des Gerichts.","dauer":5,"tipp":""},{"titel":"Langsam garen","aktion":"schmoren","text":"Heize den Ofen auf 160 Grad Ober-/Unterhitze (140 Grad Umluft) vor, stelle den abgedeckten Bräter auf die mittlere Schiene und lass das Fleisch 3,5 bis 4 Stunden garen. Es ist fertig, wenn es sich mit der Gabel leicht zerfasern lässt und der Saft im Bräter glänzt. Öffne das Paket vorsichtig; es dampft stark. Der Saft sollte orangerot und aromatisch sein und nach Orange, Gewürz und Blatt duften.","dauer":240,"tipp":""},{"titel":"Fleisch zerzupfen","aktion":"schneiden","text":"Hebe das Fleisch aus dem Saft und zupfe es mit zwei Gabeln in feine Fasern. Vermische es mit etwa der Hälfte des Garsafts, sodass es saftig glänzt, aber nicht schwimmt. Schmecke mit Salz und etwas Limettensaft ab. Das Fleisch ist jetzt butterweich, würzig und leicht säuerlich. Halte es abgedeckt warm, am besten in einer Schüssel mit etwas Saft, damit es nicht austrocknet. Der übrige Garsaft lässt sich einfrieren und gibt Reis oder Bohnen später ein feines Aroma.","dauer":10,"tipp":""},{"titel":"Tortillas wärmen und anrichten","aktion":"anrichten","text":"Wärme Maistortillas in einer trockenen Pfanne 30 Sekunden pro Seite und halte sie im Tuch warm. Gib zwei Esslöffel Fleisch in jede Tortilla, lege eine Handvoll eingelegte Zwiebeln darauf und serviere Habanero-Salsa separat. Wer es traditionell mag, isst Cochinita pibil auch in einem Brötchen (Torta) mit Avocado. Reste halten sich im Saft 3 Tage im Kühlschrank.","dauer":0,"tipp":""}],"profitipps":["Bitterorange ersetzt du durch Orange, Limette und etwas Essig im Verhältnis von etwa 2:1:1.","Das Fleisch gut abdichten – Dampf ist der Schlüssel zu Zartheit.","Zwiebeln erst 30 Sekunden blanchieren, dann einlegen: milder und knackiger.","Achiote immer im Mixer auflösen, nicht nur verrühren.","Am Vortag marinieren und am nächsten Tag garen – das Ergebnis ist deutlich aromatischer."],"varianten":["Pollo pibil mit Hähnchenschenkeln","Im Grill-Kugelgrill bei indirekter Hitze statt im Ofen","Panuchos mit Cochinita pibil und Avocado"],"beilagen":["eingelegte rote Zwiebeln","Habanero-Salsa","Frijoles refritos","Mexikanischer Reis"],"getraenk":"Kaltes Lagerbier oder Agua de Jamaica","koeche":[],"quellen":[{"titel":"TasteAtlas: mejor platillo de Mexico, Cochinita pibil (Emprendedor)","url":"https://emprendedor.com/tasteatlas-mejor-platillo-mexico-cochinita-pibil-ranking-2025/"},{"titel":"Uncomplicated Mexican dishes rate among world's best (Guadalajara Reporter)","url":"https://theguadalajarareporter.net/index.php/featured/61332-uncomplicated-mexican-dishes-rate-among-world-s-best"}],"bild":"braten-scheiben","farben":["#c4481c","#e9873a","#f4d28a"],"schlagworte":["Yucatán","Maya-Küche","Achiote","Langzeitgaren"],"vegetarisch_moeglich":false},{"id":"mexiko-birria-de-res","name":"Birria de Res mit Consomé","originalname":"Birria de res con consomé","kueche":"mexiko","region":"Jalisco","beliebtheit":89,"hauptkategorie":"fleisch","fleischsorte":"rind","gang":"hauptgericht","kurz":"Rindfleisch, in einer Sauce aus getrockneten Chilis und Gewürzen weichgeschmort, dazu die würzige Brühe zum Eintauchen – als Quesabirria mit geschmolzenem Käse ein weltweiter Hit.","hintergrund":"Birria stammt aus Jalisco und wurde dort ursprünglich mit Ziege zubereitet; später kamen Lamm und Rind dazu. In Tijuana und später in Los Angeles entstand daraus der Quesabirria-Taco: Tortillas werden durch das rote Fett der Brühe gezogen, mit Käse und Fleisch gefüllt und kross gebraten. Die Brühe (Consomé) wird als Dip serviert oder separat getrunken. Quesabirria erreicht in TasteAtlas-Bewertungen Spitzenwerte. Das Gericht braucht Geduld, belohnt aber mit Tiefe und Würze, die an Festessen erinnern.","portionen":6,"zeit":{"vorbereitung":45,"garen":210,"ruhen":120},"schwierigkeit":2,"zutaten":[{"gruppe":"Fleisch","liste":[{"menge":1.5,"einheit":"kg","name":"Rinderbeinscheibe, Querrippe oder Schulter mit Knochen","hinweis":"gemischte Stücke mit Knochen und Fett für den Consomé"},{"menge":2,"einheit":"TL","name":"Salz","hinweis":""},{"menge":2,"einheit":"EL","name":"Pflanzenöl","hinweis":""}]},{"gruppe":"Chilisauce","liste":[{"menge":6,"einheit":"Stück","name":"getrocknete Guajillo-Chilis","hinweis":""},{"menge":3,"einheit":"Stück","name":"getrocknete Ancho-Chilis","hinweis":""},{"menge":2,"einheit":"Stück","name":"Chiles de árbol","hinweis":"optional für Schärfe"},{"menge":3,"einheit":"Stück","name":"Tomaten","hinweis":""},{"menge":1,"einheit":"Stück","name":"Zwiebel","hinweis":""},{"menge":6,"einheit":"Zehe","name":"Knoblauch","hinweis":""},{"menge":60,"einheit":"ml","name":"Apfelessig","hinweis":""},{"menge":1,"einheit":"TL","name":"Kreuzkümmel","hinweis":""},{"menge":1,"einheit":"TL","name":"getrockneter Oregano","hinweis":""},{"menge":0.5,"einheit":"TL","name":"Thymian","hinweis":""},{"menge":4,"einheit":"Stück","name":"Gewürznelken","hinweis":""},{"menge":1,"einheit":"Stück","name":"Zimtstange","hinweis":""},{"menge":2,"einheit":"Stück","name":"Lorbeerblätter","hinweis":""},{"menge":1,"einheit":"Stück","name":"Stück Ingwer (2 cm)","hinweis":""}]},{"gruppe":"Zum Servieren (Quesabirria)","liste":[{"menge":18,"einheit":"Stück","name":"Maistortillas","hinweis":""},{"menge":300,"einheit":"g","name":"Oaxaca-Käse oder Mozzarella","hinweis":"Oaxaca ist im Lateinamerika-Laden; Mozzarella schmilzt ähnlich"},{"menge":1,"einheit":"Stück","name":"weiße Zwiebel, fein gewürfelt","hinweis":""},{"menge":1,"einheit":"Bund","name":"Koriander","hinweis":""},{"menge":3,"einheit":"Stück","name":"Limetten","hinweis":""}]}],"ausruestung":["Schmortopf mit Deckel (4–5 l)","Standmixer","Sieb","Pfanne für Tortillas","Fettsieb oder Schöpfkelle"],"schritte":[{"titel":"Mise en place","aktion":"vorbereiten","text":"Schneide das Fleisch in 6 bis 8 Zentimeter große Stücke und tupfe es trocken. Würze es rundum mit Salz. Entferne bei den Chilis Stiele und Kerne, halbiere Tomaten und Zwiebel und schäle den Knoblauch. Stelle Gewürze und Kräuter bereit und lege Topf, Mixer und Sieb in Reichweite. Gut vorbereitet vermeidest du, dass etwas anbrennt, während du noch Zutaten suchst.","dauer":15,"tipp":""},{"titel":"Fleisch anbraten","aktion":"anbraten","text":"Erhitze das Öl im Topf bei hoher Hitze und brate die Fleischstücke portionsweise 3 bis 4 Minuten pro Seite, bis sie tiefbraun sind. Die Röststoffe liefern Aroma für Sauce und Consomé. Nimm das Fleisch heraus, sobald es gebräunt ist, und lege es auf einen Teller. Der Bratensatz am Topfboden darf bleiben; er wird später mit der Sauce gelöst.","dauer":12,"tipp":""},{"titel":"Chilis rösten und einweichen","aktion":"vorbereiten","text":"Röste die Chilis in einer trockenen Pfanne bei mittlerer Hitze pro Seite 10 bis 15 Sekunden, bis sie duften und biegsam sind. Übergieße sie mit 500 Millilitern kochendem Wasser und lass sie 20 Minuten einweichen, bis sie weich sind. Das Einweichwasser kannst du mitverwenden, wenn die Chilis frisch und nicht bitter sind; sonst wegschütten. Brate in der Pfanne Tomaten, Zwiebel und Knoblauch an, bis sie braune Stellen haben.","dauer":25,"tipp":""},{"titel":"Sauce pürieren","aktion":"puerieren","text":"Gib Chilis, geröstetes Gemüse, Essig, Kreuzkümmel, Oregano, Thymian, Nelken und Ingwer mit etwa 250 Millilitern Brühe oder Wasser in den Mixer und püriere 2 Minuten sehr fein. Streiche die Sauce durch ein Sieb, damit sie samtig wird. Die Farbe soll tief rotbraun sein und die Sauce intensiv nach Chili, Gewürz und Essig duften. Schmecke: Sie soll kräftig und leicht säuerlich sein; die Fleischflüssigkeit mildert das später.","dauer":10,"tipp":""},{"titel":"Schmoren","aktion":"schmoren","text":"Gib das Fleisch zurück in den Topf, gieße die Sauce darüber, füge Lorbeerblätter und Zimt hinzu und gieße so viel Wasser an, dass das Fleisch zu etwa zwei Dritteln bedeckt ist. Bringe alles zum Kochen, decke den Topf ab und lass es bei 160 Grad im Ofen oder bei kleinster Hitze auf dem Herd 3 bis 3,5 Stunden schmoren. Es ist fertig, wenn sich das Fleisch an den Knochen löst und mit der Gabel zerfasert.","dauer":200,"tipp":""},{"titel":"Fett abschöpfen und Consomé bereiten","aktion":"abseihen","text":"Hebe das Fleisch heraus und zupfe es in Fasern. Schöpfe das rote Fett von der Brühe ab und hebe es in einer Schale auf; es dient später zum Anbraten der Tortillas. Schmecke den Consomé mit Salz und Limette ab: Er soll sehr würzig, leicht säuerlich und kräftig im Geschmack sein. Halte ihn heiß, am besten in einem kleinen Topf auf niedriger Stufe, denn er soll beim Servieren dampfen. Wer mag, gibt einen Spritzer Limettensaft oder etwas Chili dazu.","dauer":10,"tipp":"Das rote Fett ist der Schlüssel zu knusprigen, leuchtend roten Quesabirria-Tacos."},{"titel":"Quesabirria-Tacos braten","aktion":"braten","text":"Erhitze eine Pfanne bei mittlerer bis hoher Hitze. Tauche eine Tortilla kurz ins rote Fett, lege sie in die Pfanne, belege eine Hälfte mit Käse und Fleisch und klappe sie zusammen. Brate den Taco 1 bis 2 Minuten pro Seite, bis er knusprig, tiefrot und der Käse geschmolzen ist. Wiederhole mit den übrigen Tortillas und halte fertige Tacos im Ofen bei 80 Grad warm.","dauer":20,"tipp":""},{"titel":"Anrichten","aktion":"anrichten","text":"Serviere die Tacos mit Zwiebel, Koriander und Limettenspalten. Fülle den Consomé in Tassen oder kleine Schalen, damit jeder seine Tacos eintauchen kann. Das Fleisch kannst du auch als Eintopf mit etwas Brühe und Zwiebelwürfeln essen, so wie es in Jalisco zum Frühstück üblich ist. Reste halten sich im Consomé gut 4 Tage im Kühlschrank und schmecken aufgewärmt noch intensiver.","dauer":0,"tipp":""}],"profitipps":["Fleisch mit Knochen und Fett wählen; sie geben dem Consomé Körper.","Chilis nur kurz rösten, damit die Sauce nicht bitter wird.","Rotes Fett abschöpfen und zum Braten der Tortillas verwenden.","Sauce durch ein Sieb streichen für eine samtige Textur.","Zum Dippen den Consomé sehr heiß servieren."],"varianten":["Birria de chivo mit Ziege (klassisch in Jalisco)","Birria de borrego mit Lamm","Ramen-Style: Consomé mit Nudeln"],"beilagen":["Zwiebel-Koriander-Salat","Limetten","Salsa roja"],"getraenk":"Kräftiges Lagerbier, Tepache oder Mezcal","koeche":[{"name":"Rick Bayless","bezug":"Unter seinen von Saveur gesammelten Rezepten wird eine zarte Birria erwähnt.","quelle":"https://www.saveur.com/article/Kitchen/SAVEURs-Favorite-Rick-Bayless-Recipes"}],"quellen":[{"titel":"Birria (CIA Foodies)","url":"https://www.ciafoodies.com/birria/"},{"titel":"Birria de res (Table Journey)","url":"https://tablejourney.com/dish/birria-de-res/"},{"titel":"TasteAtlas: mejor platillo de Mexico, Cochinita pibil (Emprendedor)","url":"https://emprendedor.com/tasteatlas-mejor-platillo-mexico-cochinita-pibil-ranking-2025/"}],"bild":"eintopf","farben":["#9a2a14","#c9622a","#f0c68a"],"schlagworte":["Jalisco","Quesabirria","Trend","Schmorgericht"],"vegetarisch_moeglich":false},{"id":"mexiko-tamales-de-cerdo","name":"Tamales mit Schweinefleisch in roter Salsa","originalname":"Tamales de cerdo en salsa roja","kueche":"mexiko","region":"ganz Mexiko","beliebtheit":88,"hauptkategorie":"fleisch","fleischsorte":"schwein","gang":"hauptgericht","kurz":"Luftig-weicher Maisteig mit einer Füllung aus Schweinefleisch in roter Chilisauce, in Maishüllen gedämpft – Festgericht und Frühstück zugleich.","hintergrund":"Tamales gehören zu den ältesten Speisen Mesoamerikas: Maisteig wird in Maishüllen oder Bananenblätter gewickelt und gedämpft. Schon die Azteken und Maya aßen sie zu Festen, und noch heute gehören sie zu Weihnachten, zum Día de la Candelaria (2. Februar) und zum Día de Muertos. Jede Region hat eigene Varianten, von süßen Tamales mit Rosinen bis zu Oaxaca-Tamales mit Mole in Bananenblättern. Beim Tamalada, dem gemeinsamen Tamale-Machen, arbeitet die ganze Familie zusammen. Wichtig ist ein sehr luftiger, gut aufgeschlagener Teig, der beim Dämpfen aufgeht.","portionen":6,"zeit":{"vorbereitung":90,"garen":150,"ruhen":30},"schwierigkeit":3,"zutaten":[{"gruppe":"Füllung","liste":[{"menge":800,"einheit":"g","name":"Schweinenacken","hinweis":"in 4 cm große Würfel"},{"menge":0.5,"einheit":"Stück","name":"Zwiebel","hinweis":""},{"menge":4,"einheit":"Zehe","name":"Knoblauch","hinweis":""},{"menge":6,"einheit":"Stück","name":"getrocknete Guajillo-Chilis","hinweis":""},{"menge":2,"einheit":"Stück","name":"getrocknete Ancho-Chilis","hinweis":""},{"menge":1,"einheit":"TL","name":"Kreuzkümmel","hinweis":""},{"menge":1,"einheit":"TL","name":"Oregano","hinweis":""},{"menge":1,"einheit":"TL","name":"Salz","hinweis":""}]},{"gruppe":"Teig","liste":[{"menge":500,"einheit":"g","name":"Masa harina für Tamales","hinweis":"Instant-Maismehl z. B. Maseca; nicht Polenta oder Maisstärke"},{"menge":200,"einheit":"g","name":"Schweineschmalz","hinweis":"ersatzweise weiche Butter oder pflanzliches Fett; Schmalz gibt Geschmack und Luftigkeit"},{"menge":700,"einheit":"ml","name":"warme Brühe","hinweis":"vom Fleisch"},{"menge":1.5,"einheit":"TL","name":"Backpulver","hinweis":""},{"menge":2,"einheit":"TL","name":"Salz","hinweis":""}]},{"gruppe":"Zum Wickeln","liste":[{"menge":30,"einheit":"Stück","name":"getrocknete Maishüllen (hojas de maíz)","hinweis":"Lateinamerika-Laden oder online; Ersatz: Pergamentpapier-Rechtecke und Alufolie"},{"menge":1,"einheit":"Stück","name":"Streifen aus Maishülle zum Binden","hinweis":""}]}],"ausruestung":["großer Dämpftopf mit Siebeinsatz","Standmixer","Handrührgerät oder Küchenmaschine","große Schüssel zum Einweichen der Hüllen"],"schritte":[{"titel":"Mise en place","aktion":"vorbereiten","text":"Lege die getrockneten Maishüllen in eine große Schüssel mit warmem Wasser und beschwere sie mit einem Teller, damit sie ganz untertauchen; sie müssen mindestens eine halbe Stunde einweichen, bis sie weich und biegsam sind. Würfle in der Zwischenzeit das Fleisch, schäle den Knoblauch und halbiere die Zwiebel. Wiege Masa harina, Fett und Gewürze ab. Das Wickeln geht schnell, wenn alle Zutaten griffbereit sind.","dauer":30,"tipp":""},{"titel":"Fleisch kochen","aktion":"kochen","text":"Gib das Fleisch mit Zwiebel, Knoblauch und einem Teelöffel Salz in einen Topf und bedecke es knapp mit Wasser. Bringe es zum Kochen, schäume ab und lass es bei kleiner Hitze 60 bis 75 Minuten simmern, bis es sich mit der Gabel zerfasern lässt. Hebe das Fleisch heraus und bewahre die Brühe auf; du brauchst sie für Teig und Sauce. Zupfe das Fleisch in feine Fasern.","dauer":75,"tipp":""},{"titel":"Rote Salsa zubereiten","aktion":"puerieren","text":"Röste die Chilis kurz in einer trockenen Pfanne (10 bis 15 Sekunden pro Seite), entferne Stiele und Kerne und weiche sie 20 Minuten in heißem Wasser ein. Püriere sie mit Knoblauch, Kreuzkümmel, Oregano und etwa 150 Millilitern Brühe zu einer glatten Sauce und streiche sie durch ein Sieb. Erhitze etwas Öl in einem Topf, gib die Sauce hinein und lass sie 8 Minuten einkochen, bis sie dick ist. Vermische die Hälfte mit dem Fleisch; es soll saftig, aber nicht flüssig sein.","dauer":35,"tipp":""},{"titel":"Teig aufschlagen","aktion":"aufschlagen","text":"Schlage das Schmalz in der Küchenmaschine oder mit dem Handrührgerät 3 bis 4 Minuten, bis es weiß und luftig ist. Mische Masa harina, Backpulver und Salz und gib sie abwechselnd mit der warmen Brühe löffelweise zum Fett. Schlage weitere 5 Minuten, bis der Teig leicht und fluffig ist wie Frosting. Mache die Schwimmprobe: Ein Teelöffel Teig, der auf kaltem Wasser schwimmt, ist ausreichend aufgeschlagen. Sinkt er, schlage weiter.","dauer":15,"tipp":"Die Schwimmprobe ist ein Mythos mit wahrem Kern: Sie zeigt, ob genug Luft im Teig ist."},{"titel":"Maishüllen abtropfen und vorbereiten","aktion":"vorbereiten","text":"Nimm die Maishüllen aus dem Wasser, schüttle sie ab und tupfe sie mit einem Tuch trocken. Die breiteste Seite wird später mit Teig bestrichen. Reiße zwei oder drei Hüllen der Länge nach in schmale Streifen zum Binden. Schneide bei zu langen Hüllen die oberen, schmalen Spitzen ab. Eine Hülle soll etwa handtellergroß und leicht überlappend sein.","dauer":5,"tipp":""},{"titel":"Tamales füllen","aktion":"fuellen","text":"Lege eine Hülle mit der glatten Seite nach oben in die Hand und streiche zwei Esslöffel Teig in einem 10 mal 8 Zentimeter großen Rechteck auf die untere Hälfte. Gib einen Esslöffel Fleisch in die Mitte. Klappe die seitlichen Ränder über die Füllung, sodass der Teig sich schließt und die Füllung umhüllt. Falte das schmale Ende nach oben und binde das Paket bei Bedarf mit einem Streifen aus Maishülle zu. Der Teig soll dünn und gleichmäßig verteilt sein, nicht dick und klumpig.","dauer":30,"tipp":""},{"titel":"Dämpfer vorbereiten","aktion":"vorbereiten","text":"Fülle den Topf mit etwa 3 Zentimetern Wasser und lege einen Siebeinsatz hinein, sodass das Wasser den Boden nicht berührt. Lege einige Maishüllen auf den Siebboden, damit nichts anbrennt. Stelle die Tamales senkrecht mit der offenen Seite nach oben eng aneinander in den Topf; sie halten sich gegenseitig fest. Decke sie mit weiteren Hüllen und einem feuchten Tuch ab und setze den Deckel fest auf.","dauer":5,"tipp":""},{"titel":"Dämpfen","aktion":"daempfen","text":"Bringe das Wasser zum Kochen, reduziere dann auf mittlere Hitze und dämpfe die Tamales 60 bis 75 Minuten. Fülle bei Bedarf kochendes Wasser nach; das Wasser darf nie ausgehen. Teste die Garung, indem du einen Tamale herausnimmst und die Hülle öffnest: Der Teig soll fest sein, sich sauber von der Hülle lösen und nicht klebrig sein. Ist er noch weich, dämpfe 10 bis 15 Minuten weiter.","dauer":70,"tipp":""},{"titel":"Ruhen lassen und servieren","aktion":"ruhen","text":"Lass die Tamales nach dem Dämpfen 10 bis 15 Minuten im Topf ruhen; dabei festigt sich der Teig. Serviere sie noch in den Hüllen (die Hülle isst man nicht), dazu rote Salsa, Crema und Käse. Reste lassen sich im Kühlschrank 4 Tage lagern oder bis zu 3 Monate einfrieren und im Dämpfer wieder erwärmen. In der Mikrowelle werden sie schnell gummiartig.","dauer":15,"tipp":""}],"profitipps":["Den Teig mindestens 8 Minuten aufschlagen – er muss luftig sein.","Das Fett in den Teig einarbeiten, bis es hell und cremig ist; sonst werden Tamales schwer.","Hüllen gründlich einweichen und abtropfen lassen.","Die Tamales senkrecht dicht in den Dämpfer stellen, damit sie nicht umfallen.","Zwischendurch Wasser prüfen: Ein leerer Topf verbrennt den Boden."],"varianten":["Tamales de rajas con queso (vegetarisch mit Poblano-Streifen und Käse)","Tamales dulces mit Rosinen und Zimt","Oaxaca-Tamales mit Mole in Bananenblättern"],"beilagen":["Crema oder Schmand","Salsa roja","Atole oder heiße Schokolade"],"getraenk":"Atole, Café de olla oder Champurrado","koeche":[{"name":"Rick Bayless","bezug":"Auf seiner Webseite gibt es eine eigene Rezeptkategorie Tamales mit zahlreichen Varianten.","quelle":"https://www.rickbayless.com/recipe-category/tamales/"}],"quellen":[{"titel":"Tamales-Rezepte (rickbayless.com)","url":"https://www.rickbayless.com/recipe-category/tamales/"},{"titel":"Uncomplicated Mexican dishes rate among world's best (Guadalajara Reporter)","url":"https://theguadalajarareporter.net/index.php/featured/61332-uncomplicated-mexican-dishes-rate-among-world-s-best"}],"bild":"teller","farben":["#c9a45a","#9a2a14","#f0e0b0"],"schlagworte":["Weihnachtsessen","Maisteig","Gemeinschaftsküche"],"vegetarisch_moeglich":true},{"id":"mexiko-pozole-rojo","name":"Pozole Rojo","originalname":"Pozole rojo","kueche":"mexiko","region":"Guerrero / Jalisco","beliebtheit":86,"hauptkategorie":"fleisch","fleischsorte":"schwein","gang":"suppe","kurz":"Kräftige rote Chilibrühe mit Schweinefleisch und Hominy, bei Tisch mit Rettich, Salat, Zwiebel, Limette und Oregano individuell garniert.","hintergrund":"Pozole ist eine der ältesten mexikanischen Suppen: Hominy – mit Kalk behandelte Maiskörner – kocht stundenlang mit Fleisch in einer würzigen Brühe. Er gilt als Fest- und Familiengericht, besonders am 15. September, dem Vorabend des Unabhängigkeitstags, und zu Silvester. Pozole gibt es in drei Farben: rojo (rot, mit Chilis), verde (grün, mit Tomatillos, Guerrero) und blanco (weiß, Jalisco). Das Spannende ist die Garnitur: Salat, Rettich, Zwiebel, Chili und Limette stehen in Schälchen auf dem Tisch, damit jeder seine Suppe individuell gestaltet.","portionen":6,"zeit":{"vorbereitung":40,"garen":150,"ruhen":0},"schwierigkeit":2,"zutaten":[{"gruppe":"Suppe","liste":[{"menge":1,"einheit":"kg","name":"Schweineschulter mit Knochen","hinweis":"in große Stücke"},{"menge":500,"einheit":"g","name":"Hähnchenschenkel","hinweis":"optional, für milderen Geschmack"},{"menge":3,"einheit":"Dose","name":"Hominy (Pozole-Mais, 425 g)","hinweis":"Dosen im Lateinamerika-Laden oder online; Ersatz: Maiskörner aus der Dose (weniger authentisch)"},{"menge":1,"einheit":"Stück","name":"Knoblauchknolle, halbiert","hinweis":""},{"menge":1,"einheit":"Stück","name":"Zwiebel, halbiert","hinweis":""},{"menge":2,"einheit":"TL","name":"Salz","hinweis":""}]},{"gruppe":"Chilisauce","liste":[{"menge":6,"einheit":"Stück","name":"getrocknete Guajillo-Chilis","hinweis":""},{"menge":3,"einheit":"Stück","name":"getrocknete Ancho-Chilis","hinweis":""},{"menge":2,"einheit":"Zehe","name":"Knoblauch","hinweis":""},{"menge":0.5,"einheit":"TL","name":"Kreuzkümmel","hinweis":""},{"menge":2,"einheit":"Stück","name":"Gewürznelken","hinweis":""},{"menge":1,"einheit":"TL","name":"Oregano","hinweis":""},{"menge":3,"einheit":"EL","name":"Pflanzenöl","hinweis":""}]},{"gruppe":"Garnitur","liste":[{"menge":0.5,"einheit":"Stück","name":"Eisbergsalat oder Weißkohl","hinweis":"fein gehobelt"},{"menge":6,"einheit":"Stück","name":"Radieschen","hinweis":""},{"menge":1,"einheit":"Stück","name":"weiße Zwiebel","hinweis":""},{"menge":3,"einheit":"Stück","name":"Limetten","hinweis":""},{"menge":2,"einheit":"TL","name":"getrocknetes Chilipulver oder Chili-Flocken","hinweis":""},{"menge":2,"einheit":"TL","name":"Oregano","hinweis":""},{"menge":null,"einheit":"","name":"Tostadas oder knusprige Tortilla-Chips","hinweis":"zum Dazu-Essen"}]}],"ausruestung":["großer Topf (5–6 l)","Standmixer","Sieb","Pfanne"],"schritte":[{"titel":"Mise en place","aktion":"vorbereiten","text":"Schneide das Schweinefleisch in handtellergroße Stücke, lasse den Knochen und etwas Fett dran, denn sie geben der Brühe Körper. Halbiere die Knoblauchknolle quer und die Zwiebel. Bereite die Garnitur vor: Hoble Salat, schneide Radieschen in dünne Scheiben und würfle die Zwiebel. Stelle alles in Schälchen bereit; sie müssen später nur noch auf den Tisch.","dauer":15,"tipp":""},{"titel":"Fleisch garen","aktion":"kochen","text":"Gib das Fleisch mit Knoblauchknolle, Zwiebel und Salz in einen großen Topf und bedecke es mit etwa 3 Litern kaltem Wasser. Bringe es zum Kochen, schöpfe den Schaum ab und lass es zugedeckt bei kleiner Hitze 90 Minuten leise simmern. Das Fleisch ist gar, wenn es sich vom Knochen löst und mit der Gabel zerfällt. Hebe es heraus, entferne Knochen und Fett und zupfe es in grobe Stücke; die Brühe wird abgeseiht und behalten.","dauer":100,"tipp":""},{"titel":"Hominy vorbereiten","aktion":"abseihen","text":"Gieße den Hominy aus der Dose in ein Sieb und spüle ihn unter kaltem Wasser ab. Der Hominy aus der Dose ist schon gegart und muss nur kurz in der Suppe ziehen. Getrockneter Hominy braucht dagegen 4 bis 5 Stunden Kochzeit, bis die Körner aufplatzen (‚blühen‘). Gesalzen wird erst später, weil Salz die Körner hart machen kann.","dauer":5,"tipp":""},{"titel":"Chilis rösten und einweichen","aktion":"vorbereiten","text":"Entferne bei den Chilis Stiele und Kerne und röste sie in einer trockenen Pfanne bei mittlerer Hitze pro Seite 10 bis 15 Sekunden, bis sie duften. Übergieße sie mit kochendem Wasser und lass sie 10 bis 20 Minuten ziehen, bis sie weich sind. Wer sie zu lange röstet, bekommt bittere Sauce; lieber kurz anwärmen. Die Haut soll sich nur leicht vom Fruchtfleisch lösen.","dauer":20,"tipp":""},{"titel":"Chilisauce pürieren","aktion":"puerieren","text":"Gib die abgetropften Chilis mit Knoblauch, Kreuzkümmel, Nelken, Oregano und 200 Millilitern Brühe in den Mixer und püriere 2 Minuten sehr fein. Streiche die Sauce durch ein Sieb, damit keine Häutchen bleiben; das macht die Suppe seidig. Die Sauce soll leuchtend rot sein und kräftig nach Chili, Kreuzkümmel und Nelke duften. Sie wirkt jetzt noch roh und leicht herb; das ändert sich erst im nächsten Schritt, wenn sie im heißen Öl gebraten wird.","dauer":5,"tipp":""},{"titel":"Sauce braten","aktion":"braten","text":"Erhitze das Öl in einem breiten Topf bei mittlerer bis hoher Hitze, gib die Sauce hinein und brate sie 6 bis 8 Minuten unter ständigem Rühren, bis sie dicker, dunkler und glänzend ist. Es spritzt; rühre vorsichtig. Das Anbraten nimmt der Sauce die rohe Schärfe und vertieft das Aroma. Wie von Pati Jinich empfohlen, ist dieser Schritt der Schlüssel zu rundem Geschmack.","dauer":8,"tipp":""},{"titel":"Zusammenführen und köcheln","aktion":"koecheln","text":"Gib die gebratene Sauce, das Fleisch, den Hominy und die restliche Brühe in den Topf und lass alles 25 bis 30 Minuten bei kleiner Hitze köcheln. Schmecke mit Salz ab. Die Suppe soll sämig, rot und würzig sein und leicht nach Chili und Fleisch duften. Wenn sie zu dick ist, gib Brühe oder Wasser dazu; ist sie zu dünn, lass sie ohne Deckel ein paar Minuten weiter köcheln. Der Hominy sollte weich, aber nicht matschig sein und leicht nach Mais schmecken.","dauer":30,"tipp":""},{"titel":"Anrichten","aktion":"anrichten","text":"Schöpfe die Suppe in tiefe Schalen und serviere sie mit Schälchen voller Salat, Radieschen, Zwiebel, Limettenspalten, Oregano und Chiliflocken. Jeder garniert seine Suppe selbst: Der Salat bleibt knackig, die Limette bringt Frische, Oregano und Chili geben Aroma. Dazu passen Tostadas oder Tortilla-Chips. Reste schmecken am nächsten Tag noch besser.","dauer":0,"tipp":""}],"profitipps":["Hominy aus der Dose spart Stunden; getrockneter Hominy braucht 4–5 Stunden.","Chilis nur kurz rösten; zu langes Rösten macht bitter.","Sauce durch ein Sieb streichen und in Öl braten.","Salz erst spät zugeben, damit Hominy weich bleibt.","Die Garnitur ist Teil des Gerichts – nicht weglassen."],"varianten":["Pozole verde mit Tomatillos und Kürbiskernen","Pozole blanco ohne Chili (Jalisco)","Vegetarisch mit Pilzen und Bohnen"],"beilagen":["Tostadas","Frijoles refritos","Limetten"],"getraenk":"Kaltes Bier, Agua de Jamaica oder Mezcal","koeche":[{"name":"Pati Jinich","bezug":"Liefert beim KCRW ein rotes Pozole-Rezept, bei dem die Chilipaste durchgesiebt und kurz in Öl gebraten wird.","quelle":"https://www.kcrw.com/shows/good-food/stories/recipes-pozole-two-ways"}],"quellen":[{"titel":"Recipes: Pozole two ways (KCRW Good Food)","url":"https://www.kcrw.com/shows/good-food/stories/recipes-pozole-two-ways"},{"titel":"Uncomplicated Mexican dishes rate among world's best (Guadalajara Reporter)","url":"https://theguadalajarareporter.net/index.php/featured/61332-uncomplicated-mexican-dishes-rate-among-world-s-best"}],"bild":"suppe","farben":["#a4261a","#d8553a","#f2e6c0"],"schlagworte":["Festessen","Suppe","Garnitur","Hominy"],"vegetarisch_moeglich":true},{"id":"mexiko-salsa-roja-und-verde","name":"Salsa Roja und Salsa Verde","originalname":"Salsa roja y salsa verde","kueche":"mexiko","region":"ganz Mexiko","beliebtheit":86,"hauptkategorie":"vegan","fleischsorte":"","gang":"sauce","kurz":"Zwei Grundsaucen jeder mexikanischen Küche: röstig-tomatige Salsa roja und frisch-saure Salsa verde aus Tomatillos.","hintergrund":"Salsa bedeutet einfach Sauce, und in Mexiko ist sie so selbstverständlich wie Salz auf dem Tisch. Die Salsa roja besteht aus Tomaten und Chilis, die Salsa verde aus Tomatillos, grünen Chilis und Koriander. Beide gibt es gekocht (cocida), gebraten oder roh (cruda). Diana Kennedy, die große Kennerin der mexikanischen Küche, definiert Salsa streng als Mischung aus Chilis, Zwiebel, Koriander und Tomate und lehnt Zutaten wie Mango ab. Gabriela Cámara serviert in ihrem Restaurant Contramar eine rohe Salsa verde mit Avocado, Koriander und Salat.","portionen":6,"zeit":{"vorbereitung":15,"garen":20,"ruhen":0},"schwierigkeit":1,"zutaten":[{"gruppe":"Salsa roja","liste":[{"menge":500,"einheit":"g","name":"reife Tomaten","hinweis":""},{"menge":2,"einheit":"Stück","name":"Serrano- oder Jalapeño-Chilis","hinweis":"Ersatz: rote Chilis"},{"menge":0.25,"einheit":"Stück","name":"weiße Zwiebel","hinweis":""},{"menge":2,"einheit":"Zehe","name":"Knoblauch","hinweis":""},{"menge":1,"einheit":"TL","name":"Salz","hinweis":""},{"menge":1,"einheit":"Prise","name":"Zucker","hinweis":"falls Tomaten sauer"}]},{"gruppe":"Salsa verde","liste":[{"menge":500,"einheit":"g","name":"Tomatillos","hinweis":"frisch oder aus der Dose; Ersatz: grüne Tomaten + 1 EL Limettensaft"},{"menge":2,"einheit":"Stück","name":"Serrano- oder Jalapeño-Chilis","hinweis":""},{"menge":0.5,"einheit":"Bund","name":"Koriandergrün","hinweis":""},{"menge":0.25,"einheit":"Stück","name":"weiße Zwiebel","hinweis":""},{"menge":1,"einheit":"Zehe","name":"Knoblauch","hinweis":""},{"menge":1,"einheit":"TL","name":"Salz","hinweis":""}]}],"ausruestung":["Pfanne oder Grillblech","Standmixer oder Molcajete","Topf"],"schritte":[{"titel":"Mise en place","aktion":"vorbereiten","text":"Wasche Tomaten, Tomatillos und Chilis; bei frischen Tomatillos die klebrige Hülle entfernen und die Früchte abwaschen. Halbiere die Tomaten, den Knoblauch schälst du. Stelle die beiden Saucen nacheinander her, damit sich die Aromen nicht vermischen, und heize einen Grill oder eine Pfanne vor. Lege Mixer und Schüsseln bereit.","dauer":10,"tipp":""},{"titel":"Zutaten für die Salsa roja rösten","aktion":"braten","text":"Lege Tomaten, Chilis, Zwiebelstücke und ungeschälten Knoblauch in eine trockene, heiße Pfanne oder unter den Backofengrill. Röste sie 8 bis 10 Minuten unter gelegentlichem Wenden, bis die Haut aufplatzt und an einigen Stellen schwarz wird. Der Geruch wird süßlich-rauchig. Diese Röststellen geben der Salsa Tiefe; sie sollen aber nicht flächig verkohlen.","dauer":10,"tipp":""},{"titel":"Salsa roja pürieren","aktion":"puerieren","text":"Schäle den gerösteten Knoblauch und gib alle gerösteten Zutaten mit Salz in den Mixer. Püriere kurz, 10 bis 15 Sekunden, damit die Salsa grob und leicht stückig bleibt; so schmeckt sie lebendiger als eine glatte Creme. Probiere und ergänze Salz oder eine Prise Zucker, falls die Tomaten sauer sind. Sie soll kräftig, rauchig und frisch schmecken.","dauer":5,"tipp":""},{"titel":"Tomatillos kochen","aktion":"kochen","text":"Koche Tomatillos und Chilis in einem Topf mit wenig Wasser 5 bis 8 Minuten, bis die Früchte ihre kräftig grüne Farbe zu einem matten Olivgrün verändern und weich sind. Gieße ab und lasse sie kurz abkühlen. Alternativ kannst du sie wie die Tomaten rösten; das gibt eine rauchigere Salsa. Vermeide zu langes Kochen, sonst verlieren sie Frische und Säure.","dauer":10,"tipp":""},{"titel":"Salsa verde pürieren","aktion":"puerieren","text":"Gib Tomatillos, Chilis, Zwiebel, Knoblauch, Koriander und Salz in den Mixer. Püriere 15 bis 20 Sekunden zu einer leicht körnigen, hellgrünen Sauce. Schmecke ab: Sie soll säuerlich, frisch und leicht scharf sein; bei zu viel Säure hilft eine Prise Zucker, bei zu wenig Biss ein Spritzer Limettensaft. Beachte, dass die Schärfe nach einigen Minuten noch zunimmt – lieber vorsichtig dosieren und später nachwürzen.","dauer":5,"tipp":""},{"titel":"Abschmecken und ziehen lassen","aktion":"abschmecken","text":"Lass beide Saucen 15 Minuten ziehen und schmecke noch einmal ab; die Aromen verbinden sich. Serviere sie zu Tacos, Chips, Eiern oder gegrilltem Fleisch. Im Kühlschrank halten sie sich 4 bis 5 Tage, die Salsa verde verliert mit der Zeit Farbe. Einfrieren lässt sich die gekochte Salsa roja gut, die verde schmeckt danach etwas flacher.","dauer":15,"tipp":"Wer es roh mag: Gabriela Cámara mixt Tomatillos, Chili, Avocado, Koriander und Salat roh zu einer cremigen Salsa verde cruda."}],"profitipps":["Zutaten rösten statt kochen, wenn du mehr Tiefe willst.","Nicht zu fein pürieren; Struktur macht die Salsa lebendig.","Tomatillos nicht zu lange kochen.","Salz in Etappen zugeben – Chili und Zwiebel wirken gesalzen stärker.","Frische Chilis variieren in der Schärfe: erst kosten, dann nachwürzen."],"varianten":["Salsa verde cruda mit Avocado (Contramar-Stil)","Salsa roja mit getrockneten Chilis (Salsa de árbol)","Pico de gallo roh aus gewürfelten Tomaten"],"beilagen":["Tacos","Tortilla-Chips","Eier","gegrilltes Fleisch"],"getraenk":"Kaltes Bier oder Limonade","koeche":[{"name":"Gabriela Cámara","bezug":"Ihre Salsa verde cruda aus Tomatillos, grünen Chilis, Avocado, Koriander und Salat gehört zu ihren bekanntesten Rezepten.","quelle":"https://www.masterclass.com/articles/gabriela-camara-top-recipes"},{"name":"Diana Kennedy","bezug":"Definiert Salsa streng als Mischung aus Chilis, Zwiebel, Koriander und Tomate und lehnt Zutaten wie Mango ab.","quelle":"https://www.wusf.org/2016-12-08/at-93-diana-kennedy-still-reigns-as-mexicos-feistiest-food-expert"}],"quellen":[{"titel":"Gabriela Camara – Top Recipes (MasterClass)","url":"https://www.masterclass.com/articles/gabriela-camara-top-recipes"},{"titel":"At 93, Diana Kennedy still reigns as Mexico's feistiest food expert (WUSF/NPR)","url":"https://www.wusf.org/2016-12-08/at-93-diana-kennedy-still-reigns-as-mexicos-feistiest-food-expert"}],"bild":"dip","farben":["#b3301d","#6d9a2f","#f2e1b0"],"schlagworte":["Grundrezept","Saucen","vegan"],"vegetarisch_moeglich":true},{"id":"mexiko-esquites","name":"Esquites – Mais im Becher","originalname":"Esquites / Elote en vaso","kueche":"mexiko","region":"Mexiko-Stadt","beliebtheit":86,"hauptkategorie":"vegetarisch","fleischsorte":"","gang":"snack","themen":["streetfood"],"kurz":"Geröstete Maiskörner mit Limette, Chili, Mayonnaise und salzigem Käse, heiß im Becher gelöffelt. Der Straßensnack, der in Mexiko an jeder zweiten Ecke dampft.","hintergrund":"Esquites leitet sich vom Nahuatl-Wort ízquitl ab, das „geröstetes Mais“ bedeutet. Händler verkaufen den Mais in Mexiko aus großen Töpfen, oft mit Epazote, einem würzigen Kraut, im Kochwasser und geben dann Limette, Chilipulver, Mayonnaise und Cotija-Käse dazu. Während Elote den ganzen Kolben meint, sind Esquites die abgelösten Körner im Becher („elote en vaso“) – leichter zu essen und perfekt für unterwegs. Im TasteAtlas-Ranking der Street-Food-Gerichte belegt Esquites Rang 12.","portionen":4,"zeit":{"vorbereitung":20,"garen":20,"ruhen":0},"schwierigkeit":1,"zutaten":[{"gruppe":"Mais","liste":[{"menge":5,"einheit":"Stück","name":"frische Maiskolben","hinweis":"oder 600 g Tiefkühlmais, aufgetaut und gut abgetropft"},{"menge":2,"einheit":"EL","name":"Butter","hinweis":"oder Pflanzenöl"},{"menge":1,"einheit":"Stück","name":"kleine weiße Zwiebel","hinweis":"fein gewürfelt"},{"menge":1,"einheit":"Zehe","name":"Knoblauch","hinweis":"fein gehackt"},{"menge":1,"einheit":"Stück","name":"Jalapeño oder Serrano-Chili","hinweis":"fein gehackt; Kerne entfernen für weniger Schärfe"},{"menge":1,"einheit":"Zweig","name":"Epazote","hinweis":"optional, im Gewürzfachhandel oder online; sonst weglassen oder Koriander nutzen"},{"menge":250,"einheit":"ml","name":"Wasser","hinweis":"oder leichte Gemüsebrühe"},{"menge":null,"einheit":"","name":"Salz","hinweis":"nach Geschmack"}]},{"gruppe":"Toppings","liste":[{"menge":3,"einheit":"EL","name":"Mayonnaise","hinweis":""},{"menge":3,"einheit":"EL","name":"Crema oder saure Sahne","hinweis":""},{"menge":80,"einheit":"g","name":"Cotija-Käse","hinweis":"Ersatz: Feta oder fein geriebener Parmesan"},{"menge":2,"einheit":"Stück","name":"Limetten","hinweis":""},{"menge":2,"einheit":"TL","name":"Chilipulver","hinweis":"Tajín oder Piment d'Espelette"},{"menge":1,"einheit":"Bund","name":"Koriander","hinweis":"grob gehackt"}]}],"ausruestung":["großer Topf zum Kochen","große Pfanne oder Gusseisenpfanne","scharfes Messer","Becher oder kleine Schalen"],"schritte":[{"titel":"Mise en place","aktion":"vorbereiten","text":"Wasche die Maiskolben und entferne Blätter und Fäden vollständig. Würfle die Zwiebel fein (3 mm), hacke Knoblauch und Chili und hacke den Koriander grob. Reibe oder zerbrösele den Käse fein und lege ihn in eine Schale, die Limetten schneidest du in Spalten. In einer zweiten Schale verrührst du Mayonnaise und Crema zu einer glatten Sauce; Chilipulver und Salz stehen daneben bereit. So kannst du später alles in schneller Folge anrichten, solange der Mais noch richtig heiß ist.","dauer":0,"tipp":"Tiefkühlmais unbedingt vollständig auftauen und trockentupfen, sonst dämpft er in der Pfanne statt zu rösten."},{"titel":"Körner vom Kolben schneiden","aktion":"schneiden","text":"Stelle jeden Kolben aufrecht auf ein Schneidebrett in eine tiefe Schüssel und halte ihn oben fest. Mit einem scharfen Messer schneidest du die Körner in langen Zügen von oben nach unten ab, möglichst dicht am Kolben, aber ohne die harte Spindel zu erwischen. Streiche mit dem Messerrücken über den Kolben, damit die Maismilch und der letzte Rest der Körner in die Schüssel fließen – sie bindet später den Sud und macht ihn leicht sämig. Rechne mit etwa 600 g Körnern aus fünf mittelgroßen Kolben.","dauer":0,"tipp":""},{"titel":"Aromaten anschwitzen","aktion":"anbraten","text":"Erhitze Butter oder Öl in einer großen, schweren Pfanne bei mittlerer Hitze, bis die Butter schäumt und nussig riecht. Gib Zwiebel, Knoblauch und Chili dazu und brate sie unter Rühren zwei bis drei Minuten, bis die Zwiebel glasig und leicht gebräunt ist und die Küche nach geröstetem Knoblauch duftet. Verbrenne den Knoblauch nicht, er würde bitter. So legst du die Aromabasis, auf der der Mais später aufbaut.","dauer":3,"tipp":""},{"titel":"Mais rösten","aktion":"braten","text":"Erhöhe die Hitze auf hohe Stufe und gib die Maiskörner in die Pfanne. Lass sie ohne ständiges Rühren zwei bis drei Minuten liegen, damit sie Röststellen bekommen, und wende sie dann; wiederhole das noch zweimal, bis viele Körner goldbraun gefleckt sind und leise knacken oder platzen wie Popcorn. Dieser Röstschritt macht den Unterschied zu gekochtem Mais: Er karamellisiert den natürlichen Zucker und bringt eine leicht rauchige Süße. Arbeite gegebenenfalls in zwei Durchgängen, damit die Körner nicht übereinanderliegen und dämpfen.","dauer":8,"tipp":"Eine gusseiserne Pfanne hält die Hitze am besten und gibt die schönsten Röstaromen."},{"titel":"Mit Sud köcheln lassen","aktion":"koecheln","text":"Gieße Wasser oder Brühe an, gib den Epazote-Zweig dazu und salze mäßig. Bring alles kurz zum Kochen, reduziere die Hitze und lass den Mais ohne Deckel etwa zehn Minuten sanft köcheln, bis die Körner zart, aber noch bissfest sind und die Flüssigkeit zur Hälfte eingekocht ist. Der Sud soll nicht verschwinden, sondern als aromatische, leicht sämige Brühe im Becher bleiben, in der der Mais badet. Entferne den Epazote-Zweig vor dem Servieren.","dauer":10,"tipp":"Wird die Flüssigkeit zu schnell weniger, gieße einen Schuss Wasser nach."},{"titel":"Sauce und Käse bereitstellen","aktion":"mischen","text":"Verrühre die Mayonnaise mit der Crema und dem Saft einer halben Limette zu einer cremigen, gießfähigen Sauce. Schmecke mit einer Prise Salz ab, sie darf ruhig leicht säuerlich sein, weil der Mais süß ist. Der Cotija-Käse ist salzig und krümelig, daher brauchst du später kaum Extra-Salz. Auf Wunsch stellst du mehrere Sorten Chili – Tajín, Cayennepulver, scharfe Sauce – bereit, damit jeder seine Schärfe selbst wählt.","dauer":2,"tipp":""},{"titel":"Abschmecken","aktion":"abschmecken","text":"Probiere den Mais im Sud und schmecke mit Salz und einem kräftigen Spritzer Limettensaft ab. Er sollte süßlich, leicht salzig, rauchig und frisch schmecken; fehlt etwas, gib mehr Limette dazu. Nimm die Pfanne vom Herd, sobald die Konsistenz stimmt – der Mais soll noch glänzen und nicht trocken sein. Fülle ihn heiß in Becher oder kleine Schalen, damit der Käse später ein wenig anschmilzt.","dauer":1,"tipp":""},{"titel":"Im Becher anrichten","aktion":"anrichten","text":"Löffle den heißen Mais mit etwas Sud in Becher, träufle Mayonnaise-Sauce darüber und streue großzügig Cotija-Käse darauf. Bestäube alles mit Chilipulver und frisch gehacktem Koriander und stelle eine Limettenspalte an den Rand. Gegessen wird sofort mit Löffel, solange der Mais dampft. Wer es wie in Mexiko-Stadt mag, kann noch einen Schuss scharfe Sauce, Salz und mehr Limette dazugeben.","dauer":0,"tipp":"Esquites wird nicht gerührt, sondern geschichtet gegessen – am Ende rührt jeder selbst seine Mischung."}],"profitipps":["Röste den Mais wirklich bei hoher Hitze – das ist der Unterschied zwischen gutem und fadem Esquites.","Epazote ist authentisch, aber nicht zwingend; ein Zweig Koriander oder etwas Kreuzkümmel können als Ersatz dienen.","Limette erst am Ende hinzugeben, damit sie frisch bleibt.","Cotija ist salzig – spare am Salz, bevor du den Käse zugefügt hast."],"varianten":["Elote: ganzer gegrillter Kolben mit denselben Toppings (steht als eigenes Rezept im Kochbuch).","Esquites mit Hot-Cheetos-Crunch, wie es in manchen Städten verkauft wird.","Mit gerösteten Poblano-Streifen (Rajas) und Mais gemischt."],"beilagen":["Tortilla-Chips","Limettenspalten","scharfe Salsa"],"getraenk":"Eiskaltes mexikanisches Lagerbier, Agua fresca oder Limonade","koeche":[],"quellen":[{"titel":"Esquites – Wikipedia","url":"https://en.wikipedia.org/wiki/Esquites"},{"titel":"TasteAtlas Top 100 Street Foods (Liste)","url":"https://www.listchallenges.com/top-100-street-foods-in-the-world-by-tasteatlas"}],"bild":"teller","farben":["#f2c94c","#fff3d6","#c0392b"],"schlagworte":["Mais","Straßensnack","Mexiko-Stadt","TasteAtlas"],"vegetarisch_moeglich":true},{"id":"mexiko-quesadillas-con-rajas","name":"Quesadillas mit Rajas und Käse","originalname":"Quesadillas de maíz con rajas y queso","kueche":"mexiko","region":"Mexiko-Stadt","beliebtheit":85,"hauptkategorie":"vegetarisch","fleischsorte":"","gang":"snack","kurz":"Heiße Maistortillas mit schmelzendem Käse und weich geschmorten Poblano-Streifen in Sahne – knusprig gebraten und aus der Hand gegessen.","hintergrund":"In Mexiko-Stadt gehört zu einer Quesadilla nicht automatisch Käse; ohne Zusatz bekommt man sie dort oft nur mit Füllung und fragt extra nach Käse. Klassisch ist die Quesadilla aus Maisteig oder aus einer Maistortilla, gefüllt mit Oaxaca-Käse, Rajas (Streifen gerösteter Poblano-Chilis), Pilzen, Zucchiniblüten oder Huitlacoche, dem Maispilz. Gabriela Cámara serviert in ihrem Restaurant Contramar frittierte Quesadillas mit Huitlacoche. Sie schmeckt am besten frisch aus der Pfanne, wenn die Tortilla knusprig und der Käse gerade geschmolzen ist.","portionen":4,"zeit":{"vorbereitung":20,"garen":25,"ruhen":0},"schwierigkeit":1,"zutaten":[{"gruppe":"Rajas","liste":[{"menge":4,"einheit":"Stück","name":"Poblano-Chilis","hinweis":"Ersatz: 3 grüne Spitzpaprika + 1 Jalapeño"},{"menge":1,"einheit":"Stück","name":"Zwiebel","hinweis":"in dünne Streifen"},{"menge":1,"einheit":"Zehe","name":"Knoblauch","hinweis":""},{"menge":2,"einheit":"EL","name":"Pflanzenöl","hinweis":""},{"menge":100,"einheit":"ml","name":"Crema oder Schmand","hinweis":""},{"menge":1,"einheit":"TL","name":"Salz","hinweis":""}]},{"gruppe":"Quesadillas","liste":[{"menge":12,"einheit":"Stück","name":"frische Maistortillas (ca. 15 cm)","hinweis":"siehe Rezept Tortillas de maíz"},{"menge":300,"einheit":"g","name":"Oaxaca-Käse oder Mozzarella","hinweis":"zerzupft; Mozzarella + etwas Butterkäse ersetzt Oaxaca"},{"menge":1,"einheit":"EL","name":"Öl oder Butter","hinweis":"für die Pfanne"},{"menge":null,"einheit":"","name":"Salsa verde","hinweis":"zum Servieren"}]}],"ausruestung":["Pfanne oder Comal","Küchenzange","Alufolie","scharfes Messer"],"schritte":[{"titel":"Mise en place","aktion":"vorbereiten","text":"Zerzupfe den Käse in dünne Fäden, damit er gleichmäßig schmilzt, und schneide die Zwiebel in dünne Streifen. Wasche die Poblano-Chilis, tupfe sie trocken und lege sie neben den Herd. Stelle Öl, Salz und Schmand bereit. Die Tortillas sollten Zimmertemperatur haben und frisch sein; kalte, trockene Tortillas reißen beim Falten.","dauer":10,"tipp":""},{"titel":"Poblanos rösten","aktion":"grillen","text":"Lege die Chilis auf die offene Gasflamme, unter den heißen Backofengrill oder in eine trockene gusseiserne Pfanne und röste sie 8 bis 10 Minuten, bis die Haut rundum schwarz und blasig ist. Wende sie regelmäßig mit der Zange. Gib sie sofort in eine Schüssel und decke sie ab oder wickle sie in Alufolie; im Dampf löst sich die verkohlte Haut. Es soll nach Rauch duften; das Fruchtfleisch darunter bleibt grün und weich.","dauer":15,"tipp":"Die Haut nicht unter Wasser abspülen – sie nimmt dabei Aroma mit."},{"titel":"Häuten und in Streifen schneiden","aktion":"schneiden","text":"Ziehe nach 10 Minuten die schwarze Haut mit den Fingern ab, entferne Stiel, Kerne und weiße Rippen und schneide das Fleisch in etwa 1 Zentimeter breite Streifen. Reste der Haut dürfen bleiben, wenn sie nicht stören. Die Streifen (rajas) sollen weich, glänzend und intensiv grün sein. Trage bei empfindlicher Haut Handschuhe, denn Chilis brennen noch Stunden später.","dauer":10,"tipp":""},{"titel":"Rajas schmoren","aktion":"braten","text":"Erhitze das Öl in einer Pfanne bei mittlerer Hitze und dünste die Zwiebelstreifen 5 Minuten, bis sie glasig und leicht golden sind. Gib den Knoblauch dazu und brate ihn 30 Sekunden, bis er duftet. Rühre die Chilistreifen unter und lass sie 3 Minuten mitdünsten. Gieße die Crema an, würze mit Salz und lass die Mischung 5 Minuten einköcheln, bis sie cremig und eingedickt ist. Schmecke ab; sie soll leicht rauchig, mild scharf und cremig sein.","dauer":15,"tipp":""},{"titel":"Tortillas vorbereiten","aktion":"vorbereiten","text":"Wärme jede Tortilla kurz in einer trockenen Pfanne etwa 20 Sekunden pro Seite, damit sie biegsam wird und beim Falten nicht reißt. Lege sie auf ein Brett, bereit zum Füllen. Wenn du frische Tortillas hast, ist dieser Schritt kaum nötig; bei gekauften, leicht trockenen hilft er enorm. Sie sind bereit, wenn sie sich warm und weich anfühlen und beim Biegen nicht knacken; wickle sie danach in ein Tuch, damit sie warm bleiben.","dauer":5,"tipp":""},{"titel":"Füllen","aktion":"fuellen","text":"Gib auf eine Tortillahälfte eine Handvoll Käse und einen Esslöffel Rajas, lasse am Rand etwa 1 Zentimeter frei. Klappe die andere Hälfte darüber und drücke den Rand leicht an. Nicht überfüllen: Zu viel Füllung quillt heraus, brennt an und verklebt die Pfanne. Der Käse soll gleichmäßig verteilt sein, damit er später in der Mitte zerfließt.","dauer":10,"tipp":""},{"titel":"Braten","aktion":"braten","text":"Erhitze eine Pfanne bei mittlerer Hitze mit wenig Öl und brate die Quesadillas 2 bis 3 Minuten pro Seite, bis die Tortilla goldbraun und stellenweise knusprig ist und der Käse an den Rändern herausquillt. Drücke sie dabei mit dem Pfannenwender leicht an. Wende sie nur einmal; häufiges Wenden macht sie trocken. Der Käse soll vollständig geschmolzen sein.","dauer":10,"tipp":""},{"titel":"Anrichten","aktion":"anrichten","text":"Schneide die Quesadillas in Dreiecke oder serviere sie ganz. Reiche Salsa verde, Crema und Limette dazu. Sie sind am besten sofort, wenn der Käse noch heiß und fadenziehend ist; aufgewärmt werden sie zäh. Halte fertige Portionen im Ofen bei 80 Grad warm, wenn du für mehrere Personen kochst. Wer es kräftiger mag, streut zusätzlich gehackten Koriander oder Radieschenscheiben darüber.","dauer":0,"tipp":""}],"profitipps":["Poblanos vollständig schwarz rösten; sonst lässt sich die Haut nicht abziehen.","Oaxaca-Käse in Fäden zupfen – er schmilzt gleichmäßiger.","Nicht überfüllen, damit nichts austritt.","Mittlere Hitze: zu heiß verbrennt die Tortilla, bevor der Käse schmilzt.","Tortillas vorher kurz erwärmen, damit sie nicht reißen."],"varianten":["Mit Huitlacoche (Maispilz) und Epazote","Mit Pilzen, Zwiebel und Koriander","Mit Hähnchen-Tinga","Frittiert (Quesadillas fritas) aus Maisteig"],"beilagen":["Salsa verde","Guacamole","Frijoles refritos","Crema"],"getraenk":"Horchata oder kaltes Lager-Bier","koeche":[{"name":"Gabriela Cámara","bezug":"Zählt in ihrem MasterClass-Programm frittierte Quesadillas mit Huitlacoche zu ihren Signature-Rezepten.","quelle":"https://www.masterclass.com/articles/gabriela-camara-top-recipes"}],"quellen":[{"titel":"Gabriela Camara – Top Recipes (MasterClass)","url":"https://www.masterclass.com/articles/gabriela-camara-top-recipes"},{"titel":"Uncomplicated Mexican dishes rate among world's best (Guadalajara Reporter)","url":"https://theguadalajarareporter.net/index.php/featured/61332-uncomplicated-mexican-dishes-rate-among-world-s-best"}],"bild":"wrap","farben":["#c99a3a","#7f9a3a","#f4e3a8"],"schlagworte":["vegetarisch","Snack","schnell","Käse"],"vegetarisch_moeglich":true},{"id":"mexiko-tres-leches","name":"Tres Leches","originalname":"Pastel de tres leches","kueche":"mexiko","region":"ganz Mexiko","beliebtheit":84,"hauptkategorie":"suess","fleischsorte":"","gang":"kuchen","kurz":"Luftiger Biskuit, durchtränkt mit drei Sorten Milch und gekrönt von Sahne und Zimt – kühl, cremig und unverschämt saftig.","hintergrund":"Der Tres-leches-Kuchen ist ein Festtagsklassiker in ganz Lateinamerika und gilt in Mexiko als Geburtstagskuchen schlechthin. Der Name bezieht sich auf die drei Milchsorten: gezuckerte Kondensmilch, ungezuckerte Kondensmilch und Sahne. Der Kuchen wurde im 20. Jahrhundert populär, als Dosenmilch in die Haushalte kam. Wichtig ist ein sehr luftiger, stabiler Biskuit, der viel Flüssigkeit aufnehmen kann, ohne zu zerfallen. Serviert wird er eiskalt mit Schlagsahne, Zimt oder Früchten.","portionen":12,"zeit":{"vorbereitung":30,"garen":30,"ruhen":480},"schwierigkeit":2,"zutaten":[{"gruppe":"Biskuit","liste":[{"menge":5,"einheit":"Stück","name":"Eier (Größe M), getrennt","hinweis":"Zimmertemperatur"},{"menge":200,"einheit":"g","name":"Zucker","hinweis":""},{"menge":180,"einheit":"g","name":"Weizenmehl (Type 405)","hinweis":""},{"menge":2,"einheit":"TL","name":"Backpulver","hinweis":""},{"menge":0.5,"einheit":"TL","name":"Salz","hinweis":""},{"menge":80,"einheit":"ml","name":"Milch","hinweis":""},{"menge":2,"einheit":"TL","name":"Vanilleextrakt","hinweis":""}]},{"gruppe":"Milchmischung","liste":[{"menge":400,"einheit":"ml","name":"gezuckerte Kondensmilch","hinweis":"ca. 1 Dose (Milchmädchen)"},{"menge":400,"einheit":"ml","name":"ungezuckerte Kondensmilch (evaporated milk)","hinweis":"ca. 1 Dose, 7,5 % Fett"},{"menge":250,"einheit":"ml","name":"Sahne","hinweis":""},{"menge":1,"einheit":"TL","name":"Vanilleextrakt","hinweis":""}]},{"gruppe":"Topping","liste":[{"menge":400,"einheit":"ml","name":"Sahne","hinweis":"gut gekühlt"},{"menge":40,"einheit":"g","name":"Puderzucker","hinweis":""},{"menge":null,"einheit":"","name":"Zimt, gemahlen","hinweis":"zum Bestäuben"}]}],"ausruestung":["Auflaufform oder Backform (ca. 23 x 33 cm)","Handrührgerät","Gabel oder Zahnstocher zum Einstechen","Spritzbeutel (optional)"],"schritte":[{"titel":"Mise en place","aktion":"vorbereiten","text":"Heize den Backofen auf 175 Grad Ober-/Unterhitze (155 Grad Umluft) vor und fette die Form leicht ein oder lege sie mit Backpapier aus. Trenne die Eier sorgfältig, damit kein Eigelb ins Eiweiß gerät; Fett verhindert das Aufschlagen. Wiege Mehl, Backpulver und Salz ab und siebe sie zusammen. Stelle die Milchzutaten und die Sahne für später bereit.","dauer":10,"tipp":""},{"titel":"Eiweiß aufschlagen","aktion":"aufschlagen","text":"Schlage das Eiweiß in einer fettfreien Schüssel mit dem Handrührgerät auf mittlerer Stufe schaumig. Gib 100 Gramm Zucker esslöffelweise dazu und schlage 4 bis 5 Minuten, bis der Schnee glänzend und so fest ist, dass er in der umgedrehten Schüssel hält. Er soll steife Spitzen bilden, aber nicht trocken und krümelig werden. Ein stabiler Eischnee ist die Basis für die Luftigkeit.","dauer":6,"tipp":""},{"titel":"Eigelbmasse rühren","aktion":"aufschlagen","text":"Verrühre die Eigelbe mit den restlichen 100 Gramm Zucker in einer zweiten Schüssel 3 bis 4 Minuten, bis die Masse hell, cremig und etwa doppelt so voluminös ist. Rühre Milch und Vanille ein. Hebe dann die Mehlmischung in zwei Portionen vorsichtig unter, bis keine Mehlnester mehr sichtbar sind. Nicht zu lange rühren, sonst wird der Teig zäh.","dauer":8,"tipp":""},{"titel":"Eischnee unterheben","aktion":"mischen","text":"Gib ein Drittel des Eischnees in die Eigelbmasse und hebe ihn mit einem Teigschaber kräftig unter, um sie aufzulockern. Hebe den restlichen Schnee in zwei Portionen mit gleichmäßigen Bewegungen von unten nach oben unter, bis ein gleichmäßiger, luftiger Teig entsteht. Er soll glatt und fließend, aber nicht flüssig sein. Streiche ihn gleichmäßig in die Form.","dauer":5,"tipp":""},{"titel":"Backen","aktion":"backen","text":"Backe den Biskuit 25 bis 30 Minuten auf der mittleren Schiene, bis er goldbraun ist und beim Druck mit dem Finger zurückfedert. Ein Holzstäbchen soll sauber herauskommen. Öffne den Ofen in den ersten 20 Minuten nicht, sonst fällt der Kuchen zusammen. Lass den Biskuit in der Form 15 Minuten abkühlen; er soll noch lauwarm sein, wenn du ihn tränkst.","dauer":30,"tipp":""},{"titel":"Milchmischung anrühren","aktion":"mischen","text":"Verrühre gezuckerte Kondensmilch, ungezuckerte Kondensmilch, Sahne und Vanille in einem Krug, bis alles glatt ist. Die Mischung soll dünnflüssig und gleichmäßig cremefarben sein. Probiere: Sie schmeckt sehr süß, was später durch den Biskuit und die ungesüßte Sahne ausgeglichen wird. Wer es weniger süß mag, nimmt mehr ungezuckerte Kondensmilch und weniger gezuckerte; die Gesamtmenge von etwa 1 Liter sollte aber gleich bleiben.","dauer":3,"tipp":""},{"titel":"Kuchen tränken","aktion":"marinieren","text":"Steche den Biskuit mit einer Gabel oder einem Holzstäbchen überall dicht ein, so dass viele kleine Löcher entstehen. Gieße die Milchmischung langsam in mehreren Durchgängen darüber und warte jeweils, bis sie einsickert. Der Kuchen soll sichtbar nass und glänzend sein, aber nicht in der Flüssigkeit schwimmen; ein kleiner Rest in der Form ist in Ordnung. Decke die Form ab und stelle sie mindestens 6 Stunden, besser über Nacht, in den Kühlschrank.","dauer":480,"tipp":"Mindestens 6 Stunden ruhen lassen, damit die Flüssigkeit gleichmäßig verteilt wird."},{"titel":"Sahne schlagen und anrichten","aktion":"garnieren","text":"Schlage die gut gekühlte Sahne mit Puderzucker steif und verteile sie auf dem durchgezogenen Kuchen. Bestäube mit Zimt und garniere nach Wunsch mit frischen Früchten. Schneide den Kuchen in Stücke und serviere ihn eiskalt, denn bei Zimmertemperatur wird er zu weich. Er hält sich zugedeckt im Kühlschrank 3 Tage.","dauer":10,"tipp":""}],"profitipps":["Den Biskuit nur lauwarm tränken; heiß lässt er die Milch zu schnell einziehen.","Eischnee sehr vorsichtig unterheben, damit die Luft erhalten bleibt.","Milchmischung in mehreren Portionen eingießen.","Über Nacht ruhen lassen – am nächsten Tag ist der Kuchen am besten.","Sahne erst kurz vor dem Servieren aufstreichen."],"varianten":["Mit Kokosmilch und Kokosraspeln (Tres leches de coco)","Mit Rum oder Kaffeelikör in der Milchmischung","Schokoladen-Tres-leches mit Kakao im Biskuit"],"beilagen":["frische Beeren","Mango","Kaffee"],"getraenk":"Café de olla, Milchkaffee oder Süßwein","koeche":[],"quellen":[{"titel":"Uncomplicated Mexican dishes rate among world's best (Guadalajara Reporter)","url":"https://theguadalajarareporter.net/index.php/featured/61332-uncomplicated-mexican-dishes-rate-among-world-s-best"},{"titel":"Tacos al Pastor Named The World's Tastiest Dish (Journey Mexico)","url":"https://www.journeymexico.com/?p=32652"}],"bild":"kuchen","farben":["#f4ead2","#d9b27a","#a86a3a"],"schlagworte":["Geburtstag","Kuchen","kalt","süß"],"vegetarisch_moeglich":true},{"id":"mexiko-elotes","name":"Elotes (Mexikanische Straßenmaiskolben)","originalname":"Elotes callejeros","kueche":"mexiko","region":"ganz Mexiko","beliebtheit":83,"hauptkategorie":"vegetarisch","fleischsorte":"","gang":"beilage","kurz":"Gegrillter Maiskolben, dick bestrichen mit Mayo und Crema, bestreut mit Käse und Chilipulver und mit Limette beträufelt – Straßenessen in Perfektion.","hintergrund":"Elote (von náhuatl elotl) bedeutet Maiskolben. Auf Märkten und an Straßenständen in ganz Mexiko werden Kolben über Holzkohle gegrillt oder in Brühe gekocht und dann mit Mayonnaise, Crema, Käse und Chilipulver bestrichen. Die Mischung aus Rauch, Süße, Fett, Salz, Säure und Schärfe macht den Reiz aus. Gegessen wird direkt vom Spieß oder aus dem Becher (esquites, wenn die Körner abgeschnitten werden). Mais ist das Grundnahrungsmittel Mexikos und hat dort kulturelle Bedeutung seit Jahrtausenden.","portionen":4,"zeit":{"vorbereitung":15,"garen":15,"ruhen":0},"schwierigkeit":1,"zutaten":[{"gruppe":"Elotes","liste":[{"menge":4,"einheit":"Stück","name":"frische Maiskolben mit Hüllblättern","hinweis":"möglichst frisch, mit saftigen Körnern; Ersatz: vakuumierter Mais"},{"menge":4,"einheit":"EL","name":"Mayonnaise","hinweis":""},{"menge":4,"einheit":"EL","name":"Crema oder Schmand","hinweis":""},{"menge":80,"einheit":"g","name":"Cotija oder Feta oder Parmesan","hinweis":"fein gerieben oder zerbröselt"},{"menge":2,"einheit":"TL","name":"Chilipulver (Ancho oder Piment d'Espelette)","hinweis":"oder Paprikapulver + Cayenne"},{"menge":2,"einheit":"Stück","name":"Limetten","hinweis":""},{"menge":1,"einheit":"Bund","name":"Koriander","hinweis":"gehackt (optional)"},{"menge":4,"einheit":"Stück","name":"Holzspieße","hinweis":"optional als Griff"}]}],"ausruestung":["Grill oder Grillpfanne","Pinsel","große Schüssel","Küchenzange"],"schritte":[{"titel":"Mise en place","aktion":"vorbereiten","text":"Ziehe die Hüllblätter der Maiskolben vorsichtig zurück, entferne die Fäden (Maisseide) und lasse die Blätter am Stielansatz hängen, so dient die Hülle später als Griff. Weiche die Kolben bei Bedarf 15 Minuten in kaltem Wasser ein; das schützt vor Verbrennen. Heize den Grill auf mittlere bis hohe Hitze oder eine Grillpfanne auf starke Hitze vor. Vermische Mayonnaise und Crema in einer Schüssel und stelle Käse, Chilipulver und Limetten bereit.","dauer":10,"tipp":""},{"titel":"Mais grillen","aktion":"grillen","text":"Lege die Kolben auf den heißen Rost und grille sie 10 bis 15 Minuten, dabei alle 2 bis 3 Minuten wenden. Die Körner sollen an einigen Stellen goldbraun bis dunkel gebräunt und leicht gebräunt aufgesprungen sein; sie duften nach Popcorn und Rauch. Zu langes Grillen trocknet die Körner aus, zu kurzes lässt sie roh. Pieke mit einer Gabel in ein Korn: Es soll sich weich anfühlen und milchigen Saft abgeben.","dauer":15,"tipp":"Wer keinen Grill hat, kocht die Kolben 8 Minuten in Salzwasser und bräunt sie anschließend in der heißen Pfanne."},{"titel":"Sauce vorbereiten","aktion":"mischen","text":"Verrühre Mayonnaise und Crema zu einer glatten Mischung. Gib einen Spritzer Limettensaft dazu; die Säure schneidet das Fett. Die Mischung soll streichfähig, nicht flüssig sein. Probiere: Sie soll cremig, mild säuerlich und leicht salzig schmecken. Wer mag, gibt eine Prise Knoblauchpulver und etwas Limettenabrieb dazu. Lass die Mischung bis zum Bestreichen bei Raumtemperatur stehen, damit sie sich gut verstreichen lässt und nicht stockt.","dauer":3,"tipp":""},{"titel":"Bestreichen","aktion":"garnieren","text":"Nimm die Kolben vom Grill und bestreiche sie noch heiß rundum großzügig mit der Mayonnaise-Crema-Mischung. Die Hitze lässt die Sauce leicht anschmelzen, sodass sie gut haftet. Arbeite zügig; mit kaltem Mais haftet die Sauce schlechter. Ein Pinsel hilft, die Kolben gleichmäßig zu bedecken, aber auch ein Löffel funktioniert. Achte darauf, dass auch die Zwischenräume zwischen den Körnern mit Sauce gefüllt sind, denn dort sitzt später der Käse und die Schärfe.","dauer":3,"tipp":""},{"titel":"Käse und Chili","aktion":"garnieren","text":"Wälze die bestrichenen Kolben in zerbröseltem Käse, bis sie rundum bedeckt sind. Bestäube sie mit Chilipulver, je nach Schärfe-Vorliebe mehr oder weniger. Streue gehackten Koriander darüber, falls gewünscht. Die Kolben sollen cremig-weiß mit roten Chilitupfen aussehen und intensiv nach Käse, Rauch und Chili duften. Wer es schärfer mag, bestäubt zusätzlich mit etwas Cayennepfeffer; für die milde Variante reicht Paprikapulver.","dauer":3,"tipp":""},{"titel":"Servieren","aktion":"anrichten","text":"Schneide Limetten in Spalten und serviere sie dazu; jeder drückt sie direkt über seinen Kolben. Iss die Elotes sofort, solange der Mais noch warm und die Sauce cremig ist. Für Esquites schneidest du die Körner mit einem scharfen Messer vom Kolben und mischst sie in einer Schüssel mit der Sauce, Käse und Chili. Das ist eine bequemere Variante für Partys, die man mit dem Löffel isst.","dauer":0,"tipp":""}],"profitipps":["Frischen Mais verwenden; ältere Kolben werden stärkehaltig und trocken.","Beim Grillen oft wenden und Röstflecken zulassen – sie geben Geschmack.","Sauce auf den heißen Kolben streichen, damit sie haftet.","Cotija ist salzig und trocken; Feta ist ein guter Ersatz.","Limette erst am Tisch zugeben."],"varianten":["Esquites: Körner im Becher mit Sauce","Mit Hot-Cheetos-Staub (modern, Straßenvariante)","Vegan mit Cashew-Crema"],"beilagen":["Tacos","gegrilltes Fleisch","Salsa verde"],"getraenk":"Kaltes Bier oder Limonade","koeche":[],"quellen":[{"titel":"Uncomplicated Mexican dishes rate among world's best (Guadalajara Reporter)","url":"https://theguadalajarareporter.net/index.php/featured/61332-uncomplicated-mexican-dishes-rate-among-world-s-best"},{"titel":"Tacos al Pastor Named The World's Tastiest Dish (Journey Mexico)","url":"https://www.journeymexico.com/?p=32652"}],"bild":"teller","farben":["#e8c24a","#f4e8c8","#b3301d"],"schlagworte":["Straßenessen","Mais","Grillen"],"vegetarisch_moeglich":true},{"hauptkategorie":"fisch","fleischsorte":"","vegetarisch_moeglich":false,"id":"mexiko-camarones-a-la-diabla","name":"Camarones a la diabla – Garnelen in Teufelssauce","originalname":"Camarones a la diabla","kueche":"mexiko","region":"Pazifikküste (Sinaloa, Nayarit, Jalisco)","beliebtheit":82,"fischsorte":"meeresfruechte","gang":"hauptgericht","kurz":"Saftige Garnelen in einer feuerroten Sauce aus gerösteten Chilis, Tomaten und Knoblauch – scharf, rauchig, leicht säuerlich und perfekt zu Reis und Tortillas.","hintergrund":"Camarones a la diabla, Garnelen nach Teufelsart, gehören zu den beliebtesten Meeresfrüchte-Gerichten der mexikanischen Küste und stehen in fast jeder Strandküche auf der Karte. Die Sauce wird aus getrockneten Chilis wie Guajillo und Chile de árbol, frischen Tomaten, Zwiebel und Knoblauch püriert und in Öl gebraten, bis sie dunkel und konzentriert ist. Der Name verweist auf die Schärfe; viele Köche passen sie jedoch an: Guajillo gibt Fruchtigkeit und Farbe, Chile de árbol die Hitze. Die Garnelen garen nur wenige Minuten in der Sauce, damit sie saftig bleiben. Gegessen wird mit weißem Reis, Tortillas und einer Limette.","portionen":4,"zeit":{"vorbereitung":30,"garen":20,"ruhen":15},"schwierigkeit":2,"zutaten":[{"gruppe":"Garnelen","liste":[{"menge":800,"einheit":"g","name":"große rohe Garnelen mit Schale (Größe 16/20)","hinweis":"Tiefkühlware aus ASC-Zucht, vorher auftauen; Schwanz und Schale schützen das Fleisch"},{"menge":2,"einheit":"EL","name":"Limettensaft","hinweis":""},{"menge":0.5,"einheit":"TL","name":"Salz","hinweis":""}]},{"gruppe":"Teufelssauce","liste":[{"menge":6,"einheit":"Stück","name":"getrocknete Guajillo-Chilis","hinweis":"Entstielen und entkernen; Lateinamerika-Laden oder online"},{"menge":4,"einheit":"Stück","name":"getrocknete Chiles de árbol","hinweis":"für mehr oder weniger Schärfe variieren"},{"menge":2,"einheit":"Stück","name":"Tomaten","hinweis":"geviertelt"},{"menge":0.5,"einheit":"Stück","name":"Zwiebel","hinweis":"in Stücken"},{"menge":4,"einheit":"Zehe","name":"Knoblauch","hinweis":"geschält"},{"menge":1,"einheit":"TL","name":"getrockneter mexikanischer Oregano","hinweis":"ersatzweise normaler Oregano"},{"menge":0.5,"einheit":"TL","name":"Kreuzkümmel","hinweis":"gemahlen"},{"menge":2,"einheit":"EL","name":"Weißweinessig","hinweis":""},{"menge":250,"einheit":"ml","name":"Garnelen- oder Hühnerfond","hinweis":"ersatzweise Wasser"},{"menge":3,"einheit":"EL","name":"Olivenöl oder Butter","hinweis":""},{"menge":1,"einheit":"TL","name":"Salz","hinweis":""}]},{"gruppe":"Zum Servieren","liste":[{"menge":300,"einheit":"g","name":"Langkornreis","hinweis":"als Beilage"},{"menge":2,"einheit":"Stück","name":"Limetten","hinweis":"in Spalten"},{"menge":0.5,"einheit":"Bund","name":"Koriander","hinweis":"gehackt"},{"menge":1,"einheit":"Stück","name":"Avocado","hinweis":"optional"},{"menge":8,"einheit":"Stück","name":"Maistortillas","hinweis":"warm"}]}],"ausruestung":["Trockene Pfanne oder Comal","Standmixer","Feines Sieb","Große Pfanne oder Schmortopf","Topf für den Reis"],"schritte":[{"titel":"Mise en place","aktion":"vorbereiten","text":"Taue die Garnelen über Nacht im Kühlschrank auf oder 30 Minuten in kaltem Wasser. Entferne die Stiele der getrockneten Chilis, schneide sie auf, schüttle die Kerne heraus und entferne die helle Mittelrippe. Viele Kerne machen die Sauce bitter und sehr scharf. Viertle die Tomaten, schäle Zwiebel und Knoblauch. Trage Handschuhe, wenn du viele Chilis verarbeitest: Das Capsaicin brennt noch Stunden auf der Haut und in den Augen.","dauer":10,"tipp":"Kerne nicht komplett wegwerfen: Ein paar Kerne mitmixen, wenn du mehr Schärfe willst."},{"titel":"Garnelen vorbereiten","aktion":"vorbereiten","text":"Schneide die Schale der Garnelen mit einer Küchenschere am Rücken auf und löse sie bis zum Schwanz ab, lasse jedoch den Schwanz und, wenn du magst, die Schale an den Garnelen: Sie schützt das Fleisch und gibt Aroma. Ziehe den dunklen Darm mit einer Messerspitze heraus und spüle die Garnelen ab. Tupfe sie trocken, vermische sie mit Limettensaft und Salz und stelle sie 10 Minuten kalt. Die Säure festigt die Oberfläche leicht und würzt sie.","dauer":10,"tipp":"Garnelenschalen kurz mitkochen, wenn du Fond selbst machst: Sie geben der Sauce Tiefe."},{"titel":"Chilis rösten und einweichen","aktion":"anbraten","text":"Röste die Chilis in einer trockenen Pfanne bei mittlerer Hitze 15 bis 20 Sekunden pro Seite, bis sie duften und leicht blasig sind. Sie dürfen nie schwarz werden, sonst wird die Sauce bitter. Lege sie in eine Schüssel, übergieße sie mit kochendem Wasser und lasse sie 15 Minuten einweichen, bis sie weich und biegsam sind. Beim Rösten steigen scharfe Dämpfe auf: Öffne ein Fenster.","dauer":15,"tipp":"Guajillo schmeckt leicht fruchtig, Chile de árbol brennt: Mische nach Geschmack."},{"titel":"Sauce pürieren","aktion":"puerieren","text":"Gieße die Chilis ab, behalte 100 ml Einweichwasser. Püriere Chilis, Tomaten, Zwiebel, Knoblauch, Oregano, Kreuzkümmel, Essig und Fond in einem leistungsstarken Mixer 1 bis 2 Minuten sehr fein. Streiche die Sauce durch ein feines Sieb, damit Schalenreste zurückbleiben. Sie soll tiefrot, glatt und leicht dickflüssig sein, ähnlich einer Tomatensauce. Zu dünn wird sie beim Braten wässrig, zu dick klebt sie.","dauer":5,"tipp":"Einen Schluck Einweichwasser zugeben, wenn der Mixer nicht mehr rührt."},{"titel":"Sauce braten","aktion":"braten","text":"Erhitze Öl oder Butter in einer großen Pfanne bei mittlerer bis hoher Hitze. Gieße die Sauce vorsichtig hinein: Sie spritzt und zischt. Brate sie unter Rühren 8 bis 10 Minuten, bis sie dunkler wird, eindickt und das Öl an den Rändern austritt. Dieses Braten (sazonar) macht den Unterschied: Die rohe, grüne Note verschwindet und die Aromen werden tief und rauchig. Schmecke mit Salz ab.","dauer":10,"tipp":"Pfanne beim Eingießen teilweise abdecken: Die Sauce spritzt heftig."},{"titel":"Garnelen garen","aktion":"braten","text":"Lege die Garnelen in die brodelnde Sauce und wende sie nach 1,5 Minuten. Lasse sie weitere 1,5 Minuten garen, bis sie rosa, fest und zu einem lockeren C gekrümmt sind. Garnelen sind in 3 bis 4 Minuten fertig; wer sie länger kocht, bekommt zähes Gummi. Sie sollen mit der Sauce überzogen sein und nicht in einer Pfütze liegen. Zu flüssig? Nimm die Garnelen heraus und koche die Sauce 2 Minuten ein.","dauer":4,"tipp":"Ist die Sauce zu scharf, hilft ein Löffel Sahne oder ein Stich Butter."},{"titel":"Reis kochen","aktion":"kochen","text":"Spüle den Reis, bis das Wasser klar ist, und koche ihn in doppelter Menge gesalzenem Wasser 12 bis 14 Minuten zugedeckt auf kleiner Flamme. Der Reis soll körnig sein, nicht klebrig. Lasse ihn 5 Minuten zugedeckt ruhen und lockere ihn mit der Gabel auf. Weißer Reis dient als mildes Gegengewicht zur feurigen Sauce und nimmt sie auf.","dauer":15,"tipp":"Mit etwas Limettensaft und Koriander am Ende wird der Reis aromatischer."},{"titel":"Anrichten","aktion":"anrichten","text":"Häufe den Reis auf einen Teller, lege die Garnelen daneben und löffle reichlich Sauce darüber. Bestreue alles mit gehacktem Koriander und lege Limettenspalten dazu. Serviere warme Tortillas, Avocadoscheiben und eventuell Gurkenscheiben als kühlenden Kontrast. Man isst die Garnelen mit den Fingern, schält sie am Tisch und tunkt Tortillas in die Sauce. Ein Spritzer Limette vor dem ersten Bissen hebt die Schärfe und Säure.","dauer":0,"tipp":""}],"profitipps":["Chilis nur kurz rösten und nie schwarz werden lassen: Sonst wird die Sauce bitter.","Sauce durchsieben für Samtigkeit; sie wirkt wie Restaurantqualität.","Sauce braten, bevor die Garnelen hineinkommen: Das gibt Tiefe.","Garnelen mit Schale braten für mehr Aroma; ausgelöste Garnelen sind schneller zu essen.","Schärfe lässt sich mit der Chile-de-árbol-Menge steuern: für Kinder weglassen."],"varianten":["Mit Chipotle in Adobo für eine rauchigere Note.","Mit Tintenfischringen, Oktopus oder Muscheln als Mariscada a la diabla.","Mit Fischfilet statt Garnelen, ebenfalls beliebt an der Küste.","Mit etwas Kakao oder Zimt für eine dunklere, tiefe Sauce."],"beilagen":["Weißer Reis (Arroz blanco)","Warme Maistortillas","Avocado","Gurken-Limetten-Salat"],"getraenk":"Kaltes mexikanisches Lagerbier mit Limette, Margarita oder Agua fresca.","koeche":[],"quellen":[{"titel":"Mexican cuisine – Wikipedia (Meeresfrüchte an der Pazifikküste)","url":"https://en.wikipedia.org/wiki/Mexican_cuisine"}],"bild":"meeresfruechte","farben":["#b3261a","#e0592b","#f2dfc0"],"schlagworte":["Mexiko","Scharf","Garnelen","Chilis","Teufelssauce"]},{"id":"mexiko-huevos-rancheros","name":"Huevos Rancheros","originalname":"Huevos rancheros","kueche":"mexiko","region":"Ländliches Mexiko","beliebtheit":82,"hauptkategorie":"vegetarisch","fleischsorte":"","gang":"fruehstueck","kurz":"Spiegeleier auf warmen Maistortillas, übergossen mit würziger, gerösteter Tomatensalsa – das kräftige Frühstück der mexikanischen Ranch.","hintergrund":"Huevos rancheros bedeutet wörtlich Eier nach Art der Rancheros, also der Landarbeiter auf den Ranchos. Der Überlieferung nach servierte man sie als zweites, deftiges Frühstück nach den ersten Stunden Feldarbeit. Das Gericht besteht aus wenigen Elementen: Maistortillas als Unterlage, weich gebratene Spiegeleier und eine warme Salsa aus gerösteten Tomaten und Chilis. Beliebte Begleiter sind Frijoles refritos, Queso fresco und Koriander. Der amerikanische Koch Rick Bayless, der mexikanische Küche in den USA bekannt gemacht hat, beschreibt das Gericht auf seiner Seite als einfaches Rezept, bei dem die Salsa den Charakter bestimmt. Wichtig sind frische Tortillas, kräftige Röstaromen und ein flüssiges Eigelb, das mit der Sauce verschmilzt.","portionen":4,"zeit":{"vorbereitung":20,"garen":25,"ruhen":0},"schwierigkeit":2,"zutaten":[{"gruppe":"Geröstete Tomatensalsa","liste":[{"menge":600,"einheit":"g","name":"reife Tomaten","hinweis":"Flaschentomaten sind am aromatischsten"},{"menge":1,"einheit":"Stück","name":"Jalapeño oder 2 Serrano-Chilis","hinweis":"Schärfe nach Geschmack; Samen entfernen macht milder"},{"menge":2,"einheit":"Zehe","name":"Knoblauch","hinweis":"ungeschält"},{"menge":0.5,"einheit":"Stück","name":"weiße Zwiebel","hinweis":"in dicken Scheiben"},{"menge":1,"einheit":"EL","name":"Pflanzenöl","hinweis":""},{"menge":100,"einheit":"ml","name":"Wasser oder Brühe","hinweis":""},{"menge":null,"einheit":"","name":"Salz","hinweis":"nach Geschmack"}]},{"gruppe":"Für das Gericht","liste":[{"menge":8,"einheit":"Stück","name":"Maistortillas","hinweis":"möglichst frische aus dem Supermarkt oder der Tortillería; ersatzweise Weizentortillas"},{"menge":8,"einheit":"Stück","name":"Eier (Größe M)","hinweis":"frisch"},{"menge":3,"einheit":"EL","name":"Pflanzenöl","hinweis":"zum Braten"},{"menge":80,"einheit":"g","name":"Queso fresco oder Feta","hinweis":"zerbröckelt"},{"menge":1,"einheit":"Bund","name":"Koriander","hinweis":"grob gehackt"},{"menge":200,"einheit":"g","name":"gekochte schwarze Bohnen oder Frijoles refritos","hinweis":"optional als Beilage"}]}],"ausruestung":["große Pfanne","Backblech","Pürierstab oder Mixer","Pfannenwender"],"schritte":[{"titel":"Zutaten vorbereiten","aktion":"vorbereiten","text":"Wasche die Tomaten und halbiere sie. Entferne den Stielansatz der Chilis und schneide die Zwiebel in dicke Scheiben, die beim Rösten nicht auseinanderfallen. Lass den Knoblauch ungeschält, so verbrennt er nicht und wird weich und süß. Heize den Backofengrill auf höchste Stufe vor und stelle den Rost auf die oberste Schiene. Schneide Koriander grob und zerbrösele den Käse, damit du am Ende nur noch anrichten musst.","dauer":0,"tipp":"Wenn du keinen Backofengrill hast, röstest du die Zutaten in einer trockenen Gusspfanne."},{"titel":"Gemüse rösten","aktion":"grillen","text":"Verteile Tomaten, Chilis, Zwiebelscheiben und Knoblauch auf einem Blech und grille sie 6 bis 8 Minuten, bis die Haut schwarze Flecken bekommt und die Tomaten weich werden, wende alles einmal. Der Geruch von angekokeltem Gemüse ist erwünscht, denn diese Röstaromen geben der Salsa ihren rauchigen Charakter. Lass das Gemüse etwas abkühlen, ziehe die Haut vom Knoblauch und entferne die verkohlte Haut der Tomaten, wenn sie sich leicht lösen.","dauer":10,"tipp":"Schwarze Stellen sind Geschmack, nicht Fehler – aber ganz verkohlte Stücke schmecken bitter."},{"titel":"Salsa pürieren und einkochen","aktion":"puerieren","text":"Püriere das geröstete Gemüse mit einem Pürierstab oder im Mixer zu einer groben, leicht stückigen Sauce. Erhitze das Öl in einer großen Pfanne bei hoher Hitze, gib die Salsa auf einmal hinein, sie sollte laut zischen, und koche sie unter Rühren 5 bis 6 Minuten ein, bis sie dunkler und dicker wird. Rühre Wasser oder Brühe ein, schmecke mit Salz ab und halte sie warm. Die Salsa soll sämig sein, aber noch fließen.","dauer":8,"tipp":"Das kurze Einkochen im heißen Öl nimmt der Salsa die rohe Säure und macht den Geschmack tiefer."},{"titel":"Tortillas erwärmen","aktion":"braten","text":"Erhitze eine zweite Pfanne bei mittlerer Hitze mit etwas Öl und erwärme die Tortillas nacheinander etwa 20 bis 30 Sekunden pro Seite, bis sie weich, biegsam und leicht gefleckt sind. Sie sollen nicht knusprig werden. Staple sie auf einem Teller und halte sie mit einem Tuch oder im 80 °C warmen Ofen warm, so bleiben sie weich und brechen nicht. Kalte oder steife Tortillas würden beim Essen zerbrechen.","dauer":5,"tipp":""},{"titel":"Eier braten","aktion":"braten","text":"Erhitze Öl in einer weiten Pfanne bei mittlerer Hitze, ohne dass es raucht. Schlage die Eier einzeln in eine Tasse und lasse sie behutsam in die Pfanne gleiten; je frischer die Eier, desto kompakter bleibt das Eiweiß. Würze mit Salz und brate sie langsam 4 bis 6 Minuten, bis das Eiweiß vollständig weiß und fest ist, das Eigelb aber noch glänzt und flüssig bleibt. Brate bei Bedarf in zwei Durchgängen und halte die ersten Eier warm.","dauer":6,"tipp":"Nicht zu heiß braten, sonst wird das Eiweiß am Rand braun und gummiartig."},{"titel":"Anrichten","aktion":"anrichten","text":"Lege auf jeden Teller zwei Tortillas leicht überlappend, setze auf jede ein Spiegelei und gieße die heiße Salsa um die Eier herum, so dass die Eigelbe frei bleiben. Bestreue das Ganze mit zerbröckeltem Queso fresco und gehacktem Koriander. Serviere sofort mit schwarzen Bohnen. Beim Essen reißt du die Tortilla mit der Gabel ein und tunkst sie in Sauce und Eigelb. Wenn du es schärfer magst, stelle zusätzlich eingelegte Jalapeños dazu.","dauer":0,"tipp":""}],"profitipps":["Die Salsa wird im heißen Öl eingekocht – das macht den entscheidenden Unterschied zu roher Salsa.","Tortillas immer warm und weich servieren; kalte Tortillas brechen.","Eier bei mittlerer Hitze braten; das Eigelb soll flüssig bleiben.","Frijoles refritos selbst aus gekochten Bohnen mit Zwiebel und Schmalz oder Öl zerdrücken.","Frischer Koriander und Queso fresco bringen Frische zur kräftigen Sauce."],"varianten":["Mit Chorizo: Chorizo anbraten und über die Eier geben.","Huevos divorciados: ein Ei mit roter, eines mit grüner Salsa.","Huevos motuleños: Spezialität aus Yucatán mit Schinken, Erbsen und Bananen.","Mit Tomatillo-Salsa verde statt roter Tomatensalsa."],"beilagen":["Frijoles refritos","Avocado","Reis","Chorizo"],"getraenk":"Café de olla (Kaffee mit Zimt und Zucker) oder frischer Orangensaft","koeche":[{"name":"Rick Bayless","bezug":"Der amerikanische Koch und Mexiko-Spezialist veröffentlicht auf seiner Webseite ein Rezept für Huevos rancheros mit gerösteter Tomatensalsa, gebratenen Eiern und Maistortillas, das die Technik von der Salsa bis zum Anrichten erklärt.","quelle":"https://www.rickbayless.com/recipe/huevos-rancheros/"}],"quellen":[{"titel":"Rick Bayless: Huevos Rancheros","url":"https://www.rickbayless.com/recipe/huevos-rancheros/"},{"titel":"Rick Bayless: Chipotle Huevos Rancheros with Chorizo","url":"https://www.rickbayless.com/recipe/chipotle-huevos-rancheros-with-chorizo-goat-cheese-and-plantains/"},{"titel":"Rick Bayless: Huevos ahogados","url":"https://www.rickbayless.com/recipe/huevos-ahogados-aka-mexican-shakshuka/"}],"bild":"eier","farben":["#c4452a","#f2d27a","#4a6b2a"],"schlagworte":["Frühstück","Mexiko","Tortillas","Eier","scharf"],"vegetarisch_moeglich":true},{"id":"mexiko-sopa-de-tortilla","name":"Sopa de Tortilla","originalname":"Sopa de tortilla","kueche":"mexiko","region":"Mexiko-Stadt","beliebtheit":82,"hauptkategorie":"fleisch","fleischsorte":"huhn","gang":"suppe","kurz":"Aromatische Tomaten-Chili-Brühe mit knusprigen Tortillastreifen, Avocado, Käse und Crema.","hintergrund":"Sopa de tortilla, auch Sopa azteca genannt, ist eine mexikanische Standardsuppe aus Tomaten, Chilis und Brühe, über die frittierte Tortillastreifen gegeben werden. In der Schale landen dazu Avocadowürfel, Queso fresco, Crema und oft Chicharrón. Rick Bayless bietet auf seiner Webseite eine rustikale Version mit Hähnchen und Avocado an. Die Suppe nutzt altes Tortillabrot und ist deshalb ein typisches Resteessen.","portionen":4,"zeit":{"vorbereitung":25,"garen":35,"ruhen":0},"schwierigkeit":2,"zutaten":[{"gruppe":"Suppe","liste":[{"menge":1.2,"einheit":"l","name":"Hühnerbrühe","hinweis":"selbstgemacht oder gute Qualität"},{"menge":600,"einheit":"g","name":"Tomaten","hinweis":""},{"menge":2,"einheit":"Stück","name":"getrocknete Pasilla-Chilis","hinweis":"Ersatz: Ancho"},{"menge":0.5,"einheit":"Stück","name":"Zwiebel","hinweis":""},{"menge":3,"einheit":"Zehe","name":"Knoblauch","hinweis":""},{"menge":2,"einheit":"EL","name":"Pflanzenöl","hinweis":""},{"menge":1,"einheit":"Zweig","name":"Epazote","hinweis":"optional; sonst Oregano"},{"menge":1,"einheit":"TL","name":"Salz","hinweis":""}]},{"gruppe":"Zum Servieren","liste":[{"menge":8,"einheit":"Stück","name":"Maistortillas","hinweis":"am besten vom Vortag"},{"menge":200,"einheit":"ml","name":"Öl zum Frittieren","hinweis":""},{"menge":1,"einheit":"Stück","name":"reife Avocado","hinweis":""},{"menge":100,"einheit":"g","name":"Queso fresco oder Feta","hinweis":""},{"menge":100,"einheit":"ml","name":"Crema oder Schmand","hinweis":""},{"menge":1,"einheit":"Stück","name":"Limette","hinweis":""},{"menge":1,"einheit":"Stück","name":"Hähnchenbrust, gegart","hinweis":"zerzupft, optional"}]}],"ausruestung":["Topf","Standmixer","Pfanne zum Frittieren","Sieb","Küchenpapier"],"schritte":[{"titel":"Mise en place","aktion":"vorbereiten","text":"Schneide die Tortillas in 1 Zentimeter breite Streifen. Halbiere die Tomaten, schäle Zwiebel und Knoblauch und entferne bei den Chilis Stiele und Kerne. Würfle Avocado und Käse erst kurz vor dem Servieren, damit sie nicht braun oder trocken werden. Wärme die Brühe, damit sie später heiß in die Suppe kommt. Wenn du Hähnchen verwendest, zupfe das gegarte Fleisch jetzt in feine Fasern und halte es abgedeckt bereit. Lege Küchenpapier und eine Schaumkelle neben den Herd, denn das Frittieren geht schnell.","dauer":10,"tipp":""},{"titel":"Tortillastreifen frittieren","aktion":"frittieren","text":"Erhitze das Öl in einer Pfanne auf etwa 170 Grad, bis ein Streifen sofort leise zischt. Frittiere die Tortillastreifen in zwei Portionen 1 bis 2 Minuten, bis sie goldbraun und knusprig sind. Hebe sie mit einer Schaumkelle heraus und lege sie auf Küchenpapier. Salze sie leicht. Die Streifen sollen laut knacken, wenn du sie zerbrichst; werden sie weich, waren sie zu kurz im Öl.","dauer":6,"tipp":""},{"titel":"Chilis und Tomaten rösten","aktion":"braten","text":"Röste die Chilis in einer trockenen Pfanne bei mittlerer Hitze 10 bis 15 Sekunden pro Seite, bis sie duften; sie sollen nicht rauchen. Röste dann die Tomaten, Zwiebel und Knoblauch in der Pfanne, bis die Haut der Tomaten platzt und an einigen Stellen schwarze Flecken bekommt. Das dauert etwa 10 Minuten. Diese Röststellen geben der Suppe ihren rauchigen Geschmack.","dauer":12,"tipp":""},{"titel":"Pürieren","aktion":"puerieren","text":"Gib Chilis, Tomaten, Zwiebel, Knoblauch und einen Schuss Brühe in den Mixer und püriere sehr fein, etwa 1 bis 2 Minuten. Streiche die Mischung durch ein Sieb, um Häutchen und Kerne zu entfernen; die Suppe soll seidig sein. Die Farbe ist ein tiefes Orangerot, der Geruch rauchig und fruchtig. Wenn die Mischung zu dick für den Mixer ist, gib esslöffelweise Brühe dazu, bis die Messer gut durchlaufen.","dauer":5,"tipp":""},{"titel":"Sauce braten","aktion":"braten","text":"Erhitze 2 Esslöffel Öl in einem Topf bei mittlerer bis hoher Hitze und gib die pürierte Mischung hinein. Sie spritzt, also rühre vorsichtig. Brate sie 8 bis 10 Minuten, bis sie dunkler und dicker wird und das Öl an den Rändern sichtbar ist. Dieser Schritt kocht den rohen Geschmack weg und intensiviert das Aroma. Die Mischung ist fertig, wenn sie beim Rühren den Topfboden kurz freigibt und eine tiefere, fast ziegelrote Farbe hat.","dauer":10,"tipp":"Bayless-Stil: Sauce nicht roh in die Brühe geben, sondern erst in Öl einkochen."},{"titel":"Köcheln lassen","aktion":"koecheln","text":"Gieße die heiße Brühe an, gib Epazote oder Oregano dazu und lass die Suppe 20 Minuten bei kleiner Hitze köcheln. Schmecke mit Salz ab. Sie soll würzig, leicht säuerlich und mit milder Chilischärfe schmecken. Entferne Epazote vor dem Servieren. Wenn die Suppe zu dünn wirkt, lass sie noch 5 Minuten offen einkochen. Beim Probieren sollte die Brühe vollmundig sein und eine feine Süße aus den gerösteten Tomaten zeigen, die durch die Chilis ausgeglichen wird.","dauer":20,"tipp":""},{"titel":"Garnitur vorbereiten","aktion":"schneiden","text":"Halbiere die Avocado, entferne den Kern und würfle das Fruchtfleisch in 1-Zentimeter-Stücke; träufle etwas Limettensaft darüber, damit es nicht braun wird. Schneide den Queso fresco in kleine Würfel oder zerbrösle ihn, und rühre die Crema mit einem Schuss Milch glatt, damit sie sich später fein über die Suppe ziehen lässt. Das Hähnchenfleisch erwärmst du kurz in einem kleinen Schluck Suppe. Alle Garnituren sollen kühl und frisch bleiben, denn sie kontrastieren die heiße, würzige Brühe.","dauer":5,"tipp":""},{"titel":"Anrichten","aktion":"anrichten","text":"Verteile die Tortillastreifen, Avocadowürfel, Käse und, falls vorhanden, zerzupftes Hähnchen in vorgewärmten Schalen. Gieße die heiße Suppe darüber; so bleiben die Streifen kurz knusprig. Setze einen Löffel Crema darauf und serviere mit Limette. Iss sofort, denn die Tortilla weicht in der Brühe rasch auf, was aber auch dazugehört.","dauer":0,"tipp":""}],"profitipps":["Tortillas vom Vortag knuspern besser.","Sauce in Öl braten – das ist der Geschmacksschlüssel.","Suppe durchsieben für Seidigkeit.","Garnitur erst in der Schale zusammenführen.","Brühe selbst kochen, wenn möglich."],"varianten":["Mit Chicharrón statt Hähnchen","Vegetarisch mit Gemüsebrühe","Mit Chipotle für rauchige Schärfe"],"beilagen":["Quesadillas","Salat","frisches Brot"],"getraenk":"Kaltes Bier, Agua de Jamaica oder Weißwein","koeche":[{"name":"Rick Bayless","bezug":"Veröffentlicht auf seiner Webseite eine rustikale Tortilla-Suppe mit Hähnchen und Avocado.","quelle":"https://www.rickbayless.com/recipe/rustic-tortilla-soup-with-chicken-and-avocado/"}],"quellen":[{"titel":"Rustic Tortilla Soup with Chicken and Avocado (rickbayless.com)","url":"https://www.rickbayless.com/recipe/rustic-tortilla-soup-with-chicken-and-avocado/"},{"titel":"Uncomplicated Mexican dishes rate among world's best (Guadalajara Reporter)","url":"https://theguadalajarareporter.net/index.php/featured/61332-uncomplicated-mexican-dishes-rate-among-world-s-best"}],"bild":"suppe","farben":["#b8451f","#e0a050","#6f8a3a"],"schlagworte":["Suppe","Resteverwertung","Klassiker"],"vegetarisch_moeglich":true},{"id":"mexiko-rosca-de-reyes","name":"Rosca de Reyes – mexikanischer Dreikönigskranz","originalname":"Rosca de Reyes","kueche":"mexiko","region":"ganz Mexiko","beliebtheit":80,"hauptkategorie":"suess","gang":"gebaeck","themen":["fest"],"kurz":"Ein duftender Hefekranz mit Orangenschale und Orangenblüten, geschmückt mit kandierten Früchten und Zuckerstreifen – in dem eine kleine Figur versteckt ist, die Glück und Pflichten bringt.","hintergrund":"Am 6. Januar feiert Mexiko den Día de los Reyes Magos: Die Heiligen Drei Könige bringen den Kindern Geschenke, und die ganze Familie sitzt bei heißer Schokolade (chocolate caliente) oder Atole beisammen, um die Rosca de Reyes anzuschneiden. Der ovale Kranz symbolisiert die Krone der Könige, die kandierten Früchte stehen für Edelsteine. Im Teig ist eine kleine Figur versteckt, die das Jesuskind darstellt, ursprünglich eine Bohne, heute ein Plastik- oder Porzellanmännchen (muñequito). Wer beim Anschneiden die Figur findet, wird zum „Padrino“ oder zur „Madrina“ des Kindes und muss am 2. Februar, dem Día de la Candelaria, Tamales und Atole für alle ausrichten. So verbindet die Rosca das Dreikönigsfest mit einer lebendigen Gemeinschaftstradition.","portionen":10,"zeit":{"vorbereitung":50,"garen":30,"ruhen":180},"schwierigkeit":2,"zutaten":[{"gruppe":"Für den Hefeteig","liste":[{"menge":500,"einheit":"g","name":"Weizenmehl Type 550","hinweis":"plus etwas zum Bestäuben"},{"menge":100,"einheit":"g","name":"Zucker","hinweis":""},{"menge":1,"einheit":"Pck.","name":"Trockenhefe (7 g) oder 21 g frische Hefe","hinweis":""},{"menge":150,"einheit":"ml","name":"lauwarme Milch","hinweis":""},{"menge":3,"einheit":"Stück","name":"Eier, Größe M","hinweis":"plus 1 Eigelb zum Bestreichen"},{"menge":120,"einheit":"g","name":"weiche Butter","hinweis":""},{"menge":1,"einheit":"TL","name":"Salz","hinweis":""},{"menge":1,"einheit":"Stück","name":"Bio-Orange, abgeriebene Schale","hinweis":""},{"menge":1,"einheit":"Stück","name":"Bio-Zitrone, abgeriebene Schale","hinweis":""},{"menge":1,"einheit":"EL","name":"Orangenblütenwasser","hinweis":"gibt das typische Aroma; im Orient- oder Bioladen"},{"menge":1,"einheit":"TL","name":"Vanilleextrakt","hinweis":""},{"menge":1,"einheit":"Stück","name":"kleine Figur oder getrocknete Bohne","hinweis":"für das Verstecken im Teig; nur lebensmittelecht und nicht verschluckbar für kleine Kinder"}]},{"gruppe":"Für die Zuckerstreifen (Pasta)","liste":[{"menge":100,"einheit":"g","name":"Butter","hinweis":"weich"},{"menge":100,"einheit":"g","name":"Puderzucker","hinweis":""},{"menge":100,"einheit":"g","name":"Weizenmehl","hinweis":""},{"menge":1,"einheit":"Stück","name":"Ei","hinweis":""}]},{"gruppe":"Zum Dekorieren","liste":[{"menge":100,"einheit":"g","name":"kandierte Früchte (Feigen, Orangeat, Kirschen, Quitte)","hinweis":"in Streifen oder Stücken"},{"menge":3,"einheit":"EL","name":"grober Zucker","hinweis":"zum Bestreuen"},{"menge":2,"einheit":"EL","name":"Aprikosenmarmelade","hinweis":"erwärmt, zum Glasieren"}]}],"ausruestung":["Küchenmaschine oder Knetschüssel","Backblech mit Backpapier","Backpinsel","Spritzbeutel oder Gefrierbeutel mit Ecke","Küchenwaage"],"schritte":[{"titel":"Mise en place","aktion":"vorbereiten","text":"Hole Butter und Eier rechtzeitig aus dem Kühlschrank, damit sie Zimmertemperatur haben; kalte Zutaten verlangsamen die Hefe. Wiege alle Mengen ab, reibe Orangen- und Zitronenschale, schneide die kandierten Früchte in dekorative Streifen und halte die Figur bereit, die du später in den Teig drückst. Bereite ein Backblech mit Backpapier vor und stelle die Milch auf etwa 35 °C, sie soll sich lauwarm anfühlen, nicht heiß. Zu heiße Milch tötet die Hefe ab, zu kalte verlangsamt sie.","dauer":0,"tipp":""},{"titel":"Hefe aktivieren","aktion":"mischen","text":"Verrühre die Hefe mit der lauwarmen Milch, einem Esslöffel Zucker und 2 Esslöffeln Mehl zu einem dünnen Brei und lasse ihn 10 bis 15 Minuten abgedeckt an einem warmen Ort stehen. Er soll Blasen werfen, aufschäumen und sich leicht heben, dabei duftet er nach Hefe. Bleibt die Blasenbildung aus, ist die Hefe zu alt oder die Milch war falsch temperiert; beginne dann mit frischem Ansatz, bevor du das gesamte Mehl verbrauchst.","dauer":15,"tipp":""},{"titel":"Teig kneten","aktion":"kneten","text":"Gib das restliche Mehl, den Zucker, Salz, Eier, Schalenabrieb, Orangenblütenwasser und Vanille zum Vorteig und knete 8 Minuten mit der Küchenmaschine auf niedriger Stufe oder 12 Minuten von Hand, bis der Teig glatt und geschmeidig ist. Arbeite nun die weiche Butter in drei Portionen ein und knete jeweils, bis sie vollständig aufgenommen ist. Der Teig ist am Ende weich, leicht klebrig und löst sich als Ganzes vom Schüsselrand; er soll elastisch sein. Mach die Fensterprobe: Ein kleines Stück Teig muss sich dünn dehnen lassen, ohne zu reißen.","dauer":20,"tipp":""},{"titel":"Erste Gare","aktion":"gehen","text":"Forme den Teig zu einer Kugel, lege ihn in eine geölte Schüssel und decke ihn mit Folie oder einem feuchten Tuch ab. Lasse ihn an einem warmen Ort (ca. 26 °C) etwa 90 Minuten gehen, bis er sein Volumen verdoppelt hat und beim Drücken mit dem Finger eine Delle langsam zurückkehrt. Er duftet nun hefig, leicht nach Orange. Ein zu kühler Ort verlängert die Gare erheblich; ein Platz im ausgeschalteten Ofen mit Lampe oder neben der Heizung funktioniert gut.","dauer":90,"tipp":""},{"titel":"Kranz formen und Figur verstecken","aktion":"formen","text":"Drücke den Teig auf der leicht bemehlten Fläche kurz zusammen, rolle ihn zu einem etwa 70 cm langen Strang und lege ihn zu einem Oval oder Ring auf das Backblech; schließe die Enden zusammen, indem du sie etwas übereinanderschiebst und festdrückst. Drücke die Figur von unten in den Teig, sodass sie von außen nicht sichtbar ist, und forme die Stelle wieder glatt. So ahnt später niemand, wo sie steckt. Decke den Kranz locker ab und lasse ihn weitere 45 bis 60 Minuten gehen, bis er deutlich aufgegangen ist und weich wirkt.","dauer":60,"tipp":""},{"titel":"Zuckerstreifen vorbereiten","aktion":"mischen","text":"Verrühre Butter, Puderzucker und Mehl zu einer glatten Paste, schlage das Ei darunter und fülle die Masse in einen Spritzbeutel mit etwas größerer Öffnung oder in einen Gefrierbeutel, dessen Ecke du abschneidest. Die Paste soll dickflüssig sein, aber auf dem Teig stehen bleiben. Heize den Ofen währenddessen auf 180 °C Ober-/Unterhitze (160 °C Umluft) vor. Die Zuckerstreifen sind das typische Merkmal einer Rosca: Sie backen zu einer hellen, süßen Kruste, die die dunkle Teigoberfläche unterbricht.","dauer":10,"tipp":""},{"titel":"Verzieren","aktion":"garnieren","text":"Bestreiche den gegangenen Kranz dünn mit verquirltem Eigelb, damit er glänzt und eine schöne Farbe bekommt. Spritze in regelmäßigen Abständen Streifen der Zuckerpaste quer über den Kranz und verteile dazwischen die kandierten Früchte wie Edelsteine einer Krone. Bestreue die Streifen mit grobem Zucker, der beim Backen funkelt. Setze die Früchte nur leicht in den Teig, sie wandern sonst beim Backen. Das Ergebnis sieht festlich aus und duftet bereits nach Zitrus und Vanille.","dauer":10,"tipp":""},{"titel":"Backen","aktion":"backen","text":"Backe die Rosca auf der mittleren Schiene 25 bis 30 Minuten bei 180 °C Ober-/Unterhitze (160 °C Umluft), bis die Oberfläche tiefgolden ist und der Kranz beim Klopfen auf die Unterseite hohl klingt. Bräunt er zu schnell, decke ihn in den letzten 10 Minuten locker mit Alufolie ab. Hole ihn heraus, streiche die Früchte mit der erwärmten Aprikosenmarmelade ein, damit sie glänzen, und lasse ihn auf einem Gitter auskühlen. Der Kranz ist am besten, wenn er noch lauwarm angeschnitten wird.","dauer":30,"tipp":""},{"titel":"Servieren am Dreikönigstag","aktion":"anrichten","text":"Stelle die Rosca auf einen großen Teller in die Mitte der Tafel und lasse sie vom Familienältesten oder dem Gastgeber anschneiden; jeder sucht sich sein Stück aus. Dazu gibt es heiße Schokolade, am besten mit Zimt, oder Atole. Wer die Figur in seinem Stück findet, bekommt den Titel „Padrino“ oder „Madrina“ und lädt am 2. Februar zu Tamales und Atole ein – eine fröhliche Pflicht, die die Gemeinschaft stärkt. Gib kleinen Kindern die Stücke geschnitten und weise sie auf die versteckte Figur hin.","dauer":0,"tipp":"Die Rosca schmeckt am ersten Tag am besten; am zweiten wird sie als Pain-perdu-Variante noch einmal köstlich."}],"profitipps":["Lauwarme Milch (35 °C): Ist sie zu heiß, stirbt die Hefe; zu kalt, geht der Teig nicht.","Orangenblütenwasser sparsam dosieren – ein Esslöffel reicht für das Aroma.","Die Gare ist wichtig: Ein gut aufgegangener Kranz wird luftig, ein zu früh gebackener dicht.","Die Figur nur von unten eindrücken und Kinder im Voraus warnen.","Kandierte Früchte vorher kurz mit Mehl bestäuben, dann sinken sie nicht ein."],"varianten":["Mit Schokostücken oder Cremefüllung (Rosca rellena de crema oder Nata)","Als kleine Einzelkränze für jeden Gast","Mit Quittenpaste statt kandierten Früchten","Spanische Version Roscón de Reyes mit Sahnefüllung"],"beilagen":["Heiße Schokolade (Chocolate caliente)","Atole","Café de olla"],"getraenk":"Heiße Zimtschokolade, Atole oder Café de olla","koeche":[],"quellen":[{"titel":"Uno TV – Receta casera para preparar la tradicional Rosca de Reyes","url":"https://www.unotv.com/estilo-de-vida/gastronomia/receta-casera-para-preparar-la-tradicional-rosca-de-reyes/"},{"titel":"El Diario NY – La maravillosa historia de la Rosca de Reyes","url":"https://eldiariony.com/?p=2232370"},{"titel":"Ruptura 360 – La Rosca de Reyes, una tradición muy mexicana","url":"https://ruptura360.mx/el-pais/rosca-de-reyes-tradicion-mexicana/"}],"bild":"brot","farben":["#c9843a","#e9c377","#a8312c"],"schlagworte":["Dreikönigstag","Día de Reyes","Hefekranz","Mexiko","Candelaria"],"vegetarisch_moeglich":true},{"id":"mexiko-coctel-de-camaron","name":"Coctel de camarón","originalname":"Coctel de camarón","kueche":"mexiko","region":"Pazifik- und Golfküste (u. a. Acapulco, Veracruz)","beliebtheit":80,"hauptkategorie":"fisch","fischsorte":"meeresfruechte","gang":"vorspeise","kurz":"Zarte Garnelen in einer eiskalten, säuerlich-würzigen Tomaten-Limetten-Brühe mit Avocado, Gurke, Zwiebel und Koriander – der Erfrischer von Mexikos Küsten.","hintergrund":"Der mexikanische Garnelencocktail hat mit dem klassischen Prawn Cocktail europäischer Prägung nur den Namen gemeinsam. In Mexiko schwimmt er in einer dünnen, pikanten Sauce aus Tomatensaft, Limette und Ketchup, oft mit Orangensaft, Salsa Valentina oder Clamato, und enthält reichlich Zwiebel, Gurke, Avocado und Koriander. Er wird eiskalt im Glas oder Becher serviert, an der Küste und auf Märkten als Katerfrühstück und Snack, dazu Saltine-Cracker oder Tostadas. In Acapulco, Veracruz und an der ganzen Küste hat er eigene Spielarten – manche Köche, darunter Rick Bayless, führen gleich mehrere Varianten von grün bis geröstet-tomatig.","portionen":4,"zeit":{"vorbereitung":30,"garen":10,"ruhen":30},"schwierigkeit":1,"zutaten":[{"gruppe":"Garnelen und Sud","liste":[{"menge":500,"einheit":"g","name":"rohe Garnelen mit Schale (Vannamei)","hinweis":"Tiefkühlware mit ASC/MSC-Siegel, im Kühlschrank aufgetaut; mit Kopf geben sie mehr Fond"},{"menge":1,"einheit":"l","name":"Wasser","hinweis":""},{"menge":0.5,"einheit":"Stück","name":"Zwiebel","hinweis":"für den Sud"},{"menge":2,"einheit":"Blatt","name":"Lorbeer","hinweis":""},{"menge":1,"einheit":"TL","name":"Salz","hinweis":""}]},{"gruppe":"Cocktailsauce","liste":[{"menge":250,"einheit":"ml","name":"Tomatensaft oder Clamato","hinweis":"Clamato ist im Latino-Laden erhältlich; Tomatensaft plus 1 EL Muschelsud-Ersatz (Fischfond) geht ebenso"},{"menge":3,"einheit":"EL","name":"Ketchup","hinweis":""},{"menge":100,"einheit":"ml","name":"Limettensaft (ca. 3 Limetten)","hinweis":""},{"menge":100,"einheit":"ml","name":"Orangensaft","hinweis":""},{"menge":1,"einheit":"EL","name":"scharfe Sauce (Valentina oder Tabasco)","hinweis":"nach Geschmack"},{"menge":1,"einheit":"TL","name":"Worcestershiresauce","hinweis":""}]},{"gruppe":"Einlage und Garnitur","liste":[{"menge":0.5,"einheit":"Stück","name":"rote Zwiebel, fein gewürfelt","hinweis":""},{"menge":0.5,"einheit":"Stück","name":"Salatgurke, entkernt und gewürfelt","hinweis":""},{"menge":2,"einheit":"Stück","name":"Tomaten, entkernt und gewürfelt","hinweis":""},{"menge":0.5,"einheit":"Bund","name":"Koriandergrün","hinweis":""},{"menge":1,"einheit":"Stück","name":"reife Avocado","hinweis":"erst kurz vor dem Servieren würfeln"},{"menge":null,"einheit":"","name":"Saltine-Cracker oder Tostadas","hinweis":"zum Servieren"}]}],"ausruestung":["Topf","Schüssel mit Eiswasser","Große Schüssel","Gläser oder Becher"],"schritte":[{"titel":"Mise en place","aktion":"vorbereiten","text":"Lege die Garnelen zum Abtropfen in ein Sieb, falls sie aufgetaut sind, und bereite alles vor, was später kalt gestellt wird: Schneide die Gurke, die Tomaten und die Zwiebel in kleine Würfel von etwa 5 mm, halbiere die Gurke vorher und entferne die Kerne mit einem Löffel, damit die Sauce nicht verwässert. Hacke den Koriander grob. Presse die Limetten aus und stelle eine Schüssel mit Eiswasser bereit, in der du die Garnelen nach dem Garen abschreckst.","dauer":0,"tipp":"Schneide die Zwiebel gleich fein und wässere sie 5 Minuten in kaltem Wasser – das nimmt die scharfe Note."},{"titel":"Garnelen entschalen und entdarmen","aktion":"schneiden","text":"Löse die Köpfe, falls vorhanden, ab und ziehe die Schale vom Körper, lasse bei Wunsch den Schwanz dran. Mache mit der Messerspitze einen flachen Schnitt entlang des Rückens und ziehe den dunklen Darmfaden heraus; er schmeckt sandig und bitter. Spüle die Garnelen kurz kalt ab. Behalte die Schalen und Köpfe: Aus ihnen kochst du gleich einen aromatischen Sud, der später den Geschmack der Garnelen intensiviert.","dauer":10,"tipp":""},{"titel":"Würzigen Sud kochen","aktion":"kochen","text":"Gib Schalen und Köpfe mit Wasser, halber Zwiebel, Lorbeer und Salz in einen Topf und koche alles 10 Minuten leise sprudelnd. Der Sud wird rosa-orange und duftet intensiv nach Meer. Seihe ihn durch ein feines Sieb in einen sauberen Topf und drücke die Schalen dabei leicht aus. Dieser Fond ist die Garflüssigkeit für die Garnelen und liefert zusätzlich Aroma für die Sauce.","dauer":10,"tipp":"Ein Stück Zitrone im Sud macht den Geschmack heller."},{"titel":"Garnelen pochieren","aktion":"koecheln","text":"Bringe den abgeseihten Sud zum Sieden, nimm den Topf vom Herd und lege die Garnelen hinein. Lasse sie 1 bis 2 Minuten ziehen, bis sie kräftig rosa-orange sind und sich leicht zusammenrollen. Sie sollen innen gerade eben undurchsichtig und noch saftig sein. Hebe sie sofort mit der Schaumkelle in das Eiswasser, damit der Garprozess stoppt, denn Garnelen werden in Sekunden gummiartig. Nach 3 Minuten im Eiswasser abtropfen lassen und, falls sehr groß, halbieren.","dauer":3,"tipp":"Hebe die Garnelen auch nach 1 Minute zum Test heraus: Ein Probestück zeigt dir den perfekten Garpunkt."},{"titel":"Gemüse und Kräuter vorbereiten","aktion":"hacken","text":"Vermische die gewürfelte Zwiebel, Gurke und Tomaten in einer großen Schüssel und gib den gehackten Koriander dazu. Das Gemüse bringt Biss und Frische in das weiche Garnelenfleisch. Halte die Avocado noch zurück: Sie wird braun und matschig, wenn sie zu früh in die Sauce kommt. Schneide sie erst direkt vor dem Servieren auf und würfele sie in 1-cm-Stücke.","dauer":5,"tipp":""},{"titel":"Cocktailsauce anrühren","aktion":"mischen","text":"Verrühre in einem Krug den Tomatensaft oder Clamato, Ketchup, Limettensaft, Orangensaft, scharfe Sauce, Worcestershiresauce und etwa 100 ml des erkalteten Garnelensuds. Schmecke kräftig mit Salz ab: Die Sauce muss deutlich säuerlich, leicht süß, scharf und salzig sein, denn eiskalt verlieren Aromen an Intensität. Sie soll dünnflüssig wie eine kalte Suppe sein, nicht dickflüssig wie Ketchup. Passe Süße, Säure und Schärfe nach Geschmack an.","dauer":3,"tipp":""},{"titel":"Mischen und kühlen","aktion":"kuehlen","text":"Gib die Garnelen zum Gemüse in die Schüssel und gieße die Sauce darüber, sodass alles gut bedeckt ist. Stelle den Cocktail abgedeckt für 20 bis 30 Minuten in den Kühlschrank. In dieser Zeit ziehen die Aromen ein und alles wird eiskalt. Ein Coctel de camarón soll richtig kalt sein: Die Kälte macht ihn zur Erfrischung. Rühre zwischendurch einmal um, damit die Garnelen gleichmäßig durchziehen.","dauer":30,"tipp":"Stelle die Gläser vorher ins Gefrierfach, damit die Sauce noch länger kühl bleibt."},{"titel":"Avocado und Anrichten","aktion":"anrichten","text":"Würfele die Avocado erst jetzt, hebe sie vorsichtig unter oder verteile sie obenauf, damit sie nicht zerfällt. Fülle den Cocktail mit reichlich Sauce in gekühlte Gläser oder Becher und garniere mit Koriander und einer Limettenspalte. Serviere sofort mit Saltine-Crackern oder Tostadas und scharfer Sauce am Tisch. Die Garnelen sollen zart, die Gurke knackig, die Sauce spritzig und die Avocado cremig sein.","dauer":0,"tipp":""}],"profitipps":["Garnelen nur 1–2 Minuten ziehen lassen und sofort abschrecken, sonst werden sie gummiartig.","Sud aus Köpfen und Schalen bringt den authentischen Meeresgeschmack in die Sauce.","Der Cocktail muss eiskalt serviert werden; vorgekühlte Gläser helfen.","Die Sauce kräftig abschmecken, denn Kälte dämpft Geschmack.","Avocado erst ganz zum Schluss dazu, damit sie nicht braun und matschig wird."],"varianten":["Coctel campechano mit Austern, Krebsfleisch und Tintenfisch.","Mit gerösteten Tomaten für eine rauchige Note.","Grüne Version (Coctel verde) mit Tomatillos, Koriander und Serrano.","Oder mit Ketchup-Rotsauce, Limette und Chipotle."],"beilagen":["Saltine-Cracker","Tostadas","Limettenspalten","Salsa Valentina"],"getraenk":"Kaltes mexikanisches Lagerbier mit Limette (z. B. Pacífico), Michelada oder ein frischer Weißwein.","koeche":[{"name":"Rick Bayless","bezug":"Führt auf seiner Webseite eine ganze Reihe an Coctel-Rezepten (Acapulco-Style, Green, Herby, Roasted Tomato Shrimp Cocktail) und zeigt damit die Bandbreite des mexikanischen Garnelencocktails.","quelle":"https://www.rickbayless.com/recipe-category/ceviche-aguachiles-and-other-mariscos/"}],"quellen":[{"titel":"Ceviche, Aguachiles and Other Mariscos – Rick Bayless","url":"https://www.rickbayless.com/recipe-category/ceviche-aguachiles-and-other-mariscos/"},{"titel":"Acapulco-Style Shrimp Cocktail – Rick Bayless","url":"https://www.rickbayless.com/recipe/acapulco-style-shrimp-cocktail/"},{"titel":"Shrimp cocktail – Wikipedia","url":"https://en.wikipedia.org/wiki/Shrimp_cocktail"}],"bild":"meeresfruechte","farben":["#d9482b","#f2c48a","#7aa04a"],"schlagworte":["Küste","Eiskalt","Katerfrühstück","Garnelen"],"vegetarisch_moeglich":false},{"id":"mexiko-tortillas-de-maiz","name":"Tortillas de Maíz (selbst gemacht)","originalname":"Tortillas de maíz","kueche":"mexiko","region":"ganz Mexiko","beliebtheit":80,"hauptkategorie":"vegan","fleischsorte":"","gang":"brot","kurz":"Weiche, duftende Maistortillas aus nur drei Zutaten – frisch aus der Pfanne unschlagbar.","hintergrund":"Die Maistortilla ist das Grundbrot Mexikos und seit Jahrtausenden Teil der Ernährung. Traditionell wird Mais mit Kalk (nixtamalisiert) behandelt, gemahlen und zu Masa verarbeitet. Zu Hause nimmt man Masa harina, ein getrocknetes Nixtamal-Mehl, das mit Wasser zum Teig wird. Gebacken werden die Fladen auf einem Comal; wenn sie richtig gelingen, quellen sie wie kleine Kissen auf. Diana Kennedy hat der Tortilla ein eigenes Buch gewidmet (The Tortilla Book, 1975).","portionen":4,"zeit":{"vorbereitung":15,"garen":15,"ruhen":20},"schwierigkeit":1,"zutaten":[{"gruppe":"Teig","liste":[{"menge":250,"einheit":"g","name":"Masa harina","hinweis":"z. B. Maseca; nicht Maisgrieß oder Polenta"},{"menge":400,"einheit":"ml","name":"warmes Wasser","hinweis":"ca. 40 °C, nach Bedarf"},{"menge":0.5,"einheit":"TL","name":"Salz","hinweis":""}]}],"ausruestung":["Tortillapresse oder zwei flache Teller","Plastikfolie oder Gefrierbeutel","gusseiserne Pfanne oder Comal","Küchentuch"],"schritte":[{"titel":"Mise en place","aktion":"vorbereiten","text":"Wiege Masa harina und Salz ab, stelle warmes Wasser bereit und lege Plastikfolie zurecht, aus der du zwei Kreise von 15 Zentimetern schneidest. Heize die Pfanne noch nicht vor. Ein sauberes Küchentuch brauchst du später, um die fertigen Tortillas warm zu halten. Wenn du keine Presse hast, kannst du einen flachen Teller oder eine Pfanne benutzen.","dauer":5,"tipp":""},{"titel":"Teig kneten","aktion":"kneten","text":"Gib Masa harina und Salz in eine Schüssel und gieße nach und nach das warme Wasser dazu, während du mit der Hand knetest. Der Teig soll sich anfühlen wie weiche Knete: nicht klebrig und nicht trocken. Ein Test: Forme eine Kugel und drücke sie flach. Sind die Ränder rissig, fehlt Wasser, klebt der Teig an den Händen, brauchst du mehr Mehl. Knete etwa 3 Minuten, bis er glatt ist.","dauer":5,"tipp":""},{"titel":"Teig ruhen lassen","aktion":"ruhen","text":"Decke den Teig mit einem feuchten Tuch oder Plastikfolie ab und lass ihn 15 bis 20 Minuten ruhen. In dieser Zeit saugt das Mehl das Wasser vollständig auf und der Teig wird geschmeidiger. Probiere dann erneut: Er soll weich und formbar sein, ohne zu reißen. Wenn er trocken geworden ist, knete einen Schuss Wasser ein. Ein Zeichen für die richtige Konsistenz: Der Teig lässt sich ohne Risse flach drücken und klebt nicht an den Händen.","dauer":20,"tipp":"Der Teig trocknet schnell an der Luft aus; immer abgedeckt halten."},{"titel":"Kugeln formen","aktion":"formen","text":"Teile den Teig in 12 gleich große Portionen von etwa 40 Gramm und rolle sie zwischen den Handflächen zu glatten Kugeln. Halte sie unter einem feuchten Tuch, bis du sie presst. Die Kugeln sollen rissfrei und rund sein, denn Risse setzen sich beim Pressen fort. Hast du eine Waage, wiege jede Kugel ab, so werden alle Tortillas gleich groß.","dauer":10,"tipp":""},{"titel":"Pressen","aktion":"ausrollen","text":"Lege eine Kugel zwischen zwei Folienkreise in die Tortillapresse und drücke sanft, bis eine runde Scheibe von etwa 12 bis 14 Zentimetern und 2 Millimetern Dicke entsteht. Drehe sie ggf. um 180 Grad und presse noch einmal, wenn sie ungleichmäßig ist. Ohne Presse drückst du den Teig mit einem flachen Teller oder Topfboden zwischen den Folien. Ziehe vorsichtig die obere Folie ab, drehe die Tortilla auf die Hand und löse die zweite Folie.","dauer":10,"tipp":""},{"titel":"Backen","aktion":"braten","text":"Erhitze eine trockene Pfanne oder ein Comal bei mittlerer bis hoher Hitze, bis ein Tropfen Wasser sofort zischt. Lege eine Tortilla hinein und backe sie 30 bis 45 Sekunden, bis sich die Ränder leicht lösen. Wende sie, backe sie 45 bis 60 Sekunden, wende sie noch einmal und drücke sie leicht an; sie bläht sich oft zu einem Kissen auf, ein Zeichen für perfekte Garung. Fertige Tortillas wickelst du sofort in ein Tuch, damit sie im eigenen Dampf weich bleiben.","dauer":15,"tipp":"Die Pfanne muss wirklich heiß sein; bei zu wenig Hitze werden Tortillas trocken und hart."}],"profitipps":["Teigkonsistenz ist alles: weich wie Knete, nicht klebrig.","Teig ruhen lassen, damit das Mehl quillt.","Folie benutzen, damit die Tortilla nicht an der Presse klebt.","Pfanne sehr heiß halten; Tortillas sollen schnell gar werden.","Sofort in ein Tuch wickeln – sie bleiben so weich."],"varianten":["Blaue Tortillas aus blauem Maismehl","Mit Spinat oder Chili im Teig","Kleine Gorditas, dicker gebacken"],"beilagen":["Tacos","Quesadillas","Frijoles refritos"],"getraenk":"Beliebiges Getränk – dient als Basis für viele Gerichte","koeche":[],"quellen":[{"titel":"Uncomplicated Mexican dishes rate among world's best (Guadalajara Reporter)","url":"https://theguadalajarareporter.net/index.php/featured/61332-uncomplicated-mexican-dishes-rate-among-world-s-best"},{"titel":"Diana Kennedy (Wikipedia)","url":"https://en.wikipedia.org/wiki/Diana_Kennedy"}],"bild":"brot","farben":["#e8c97a","#c9a24a","#f4e6b8"],"schlagworte":["Grundrezept","Mais","vegan","glutenfrei"],"vegetarisch_moeglich":true},{"id":"mexiko-chiles-en-nogada","name":"Chiles en Nogada","originalname":"Chiles en nogada","kueche":"mexiko","region":"Puebla","beliebtheit":80,"hauptkategorie":"fleisch","fleischsorte":"gemischt","gang":"hauptgericht","kurz":"Gefüllte Poblano-Chilis mit fruchtigem Hackfleisch, überzogen von kalter Walnusssauce und bestreut mit Granatapfelkernen und Petersilie – in den Farben der mexikanischen Flagge.","hintergrund":"Chiles en nogada gelten als eines der aufwendigsten und patriotischsten Gerichte Mexikos. Der Überlieferung nach wurden sie 1821 in Puebla von Augustinerinnen zu Ehren von Agustín de Iturbide erfunden, der damals die Unabhängigkeit Mexikos besiegelte; Grün (Chili und Petersilie), Weiß (Walnusssauce) und Rot (Granatapfel) bilden die Nationalfarben. Gegessen werden sie in der Saison von August bis September, wenn Walnüsse und Granatäpfel frisch sind. Das Gericht ist 2021 200 Jahre alt geworden. Die Füllung, ein Picadillo aus Fleisch, Früchten und Nüssen, verbindet süß, salzig und würzig.","portionen":6,"zeit":{"vorbereitung":120,"garen":90,"ruhen":720},"schwierigkeit":3,"zutaten":[{"gruppe":"Chilis","liste":[{"menge":6,"einheit":"Stück","name":"große Poblano-Chilis","hinweis":"Ersatz: große grüne Spitzpaprika oder milde Paprika; Poblano gibt es in Mexiko-Läden, manchmal auch im Glas"},{"menge":null,"einheit":"","name":"Salz","hinweis":""}]},{"gruppe":"Picadillo-Füllung","liste":[{"menge":400,"einheit":"g","name":"Schweinehack","hinweis":""},{"menge":300,"einheit":"g","name":"Rinderhack","hinweis":""},{"menge":1,"einheit":"Stück","name":"Zwiebel, fein gewürfelt","hinweis":""},{"menge":3,"einheit":"Zehe","name":"Knoblauch","hinweis":""},{"menge":3,"einheit":"Stück","name":"Tomaten, gehäutet und gewürfelt","hinweis":""},{"menge":1,"einheit":"Stück","name":"Apfel, gewürfelt","hinweis":""},{"menge":1,"einheit":"Stück","name":"Birne, gewürfelt","hinweis":""},{"menge":1,"einheit":"Stück","name":"Pfirsich, gewürfelt","hinweis":"Dose ist erlaubt, gut abgetropft"},{"menge":1,"einheit":"Stück","name":"reife Kochbanane (Plátano macho)","hinweis":"optional; Ersatz: normale Banane"},{"menge":50,"einheit":"g","name":"Mandeln, gehackt","hinweis":""},{"menge":50,"einheit":"g","name":"Rosinen","hinweis":""},{"menge":1,"einheit":"TL","name":"Zimt","hinweis":""},{"menge":2,"einheit":"Stück","name":"Gewürznelken, gemahlen","hinweis":""},{"menge":2,"einheit":"EL","name":"Pflanzenöl","hinweis":""},{"menge":1,"einheit":"TL","name":"Salz","hinweis":""}]},{"gruppe":"Nogada (Walnusssauce)","liste":[{"menge":200,"einheit":"g","name":"frische Walnüsse, geschält","hinweis":"Walnüsse 12 Stunden in Milch einlegen und die braune Haut abziehen, sonst wird die Sauce bitter"},{"menge":200,"einheit":"g","name":"Frischkäse (Ziegenfrischkäse oder Queso fresco)","hinweis":""},{"menge":250,"einheit":"ml","name":"Sahne","hinweis":""},{"menge":100,"einheit":"ml","name":"Milch","hinweis":""},{"menge":1,"einheit":"EL","name":"trockener Sherry","hinweis":"optional"},{"menge":1,"einheit":"Prise","name":"Zimt","hinweis":""},{"menge":1,"einheit":"TL","name":"Salz","hinweis":""}]},{"gruppe":"Garnitur","liste":[{"menge":1,"einheit":"Stück","name":"Granatapfel","hinweis":"Kerne herauslösen"},{"menge":0.5,"einheit":"Bund","name":"glatte Petersilie","hinweis":""}]}],"ausruestung":["Gasflamme oder Backofengrill zum Rösten","Standmixer","große Pfanne","Sieb","Messer"],"schritte":[{"titel":"Walnüsse vorbereiten","aktion":"marinieren","text":"Schäle die frischen Walnüsse und lege sie in einer Schüssel in kalte Milch, so dass sie bedeckt sind. Nach 12 Stunden im Kühlschrank lässt sich die bittere braune Haut mit den Fingern oder einem Messer abziehen. Diese Haut zu entfernen ist wichtig, denn sie macht die Sauce herb und dunkel statt cremig-weiß. Die geschälten Nüsse sollen hell und glatt sein.","dauer":720,"tipp":"Wenn du frische Walnüsse nicht bekommst, geht es auch mit gekauften; sie müssen aber möglichst frisch und ohne ranzigen Geruch sein."},{"titel":"Mise en place","aktion":"vorbereiten","text":"Würfle alle Früchte und Gemüse für die Füllung in Stücke von etwa 5 Millimetern; kleine, gleichmäßige Würfel garen zügig und ergeben einen harmonischen Biss. Hacke Mandeln und Zwiebel, schäle Tomaten (kurz überbrühen und Haut abziehen) und löse die Granatapfelkerne aus der Frucht. Stelle Gewürze, Hack und Rosinen bereit. Eine gute Vorbereitung ist bei diesem Gericht die halbe Arbeit.","dauer":25,"tipp":""},{"titel":"Poblanos rösten","aktion":"grillen","text":"Röste die Chilis über offener Gasflamme, unter dem sehr heißen Backofengrill oder in der Pfanne 8 bis 10 Minuten, bis die Haut rundum schwarz und blasig ist. Gib sie sofort in eine Schüssel, decke sie ab und lass sie 10 Minuten schwitzen. Ziehe dann die Haut ab, ohne die Chili zu zerreißen, und spüle sie nicht unter Wasser. Schneide eine Längsseite vorsichtig auf, entferne Stiel, Kerne und Rippen und lasse den Stielansatz dran, damit die Chili Form behält.","dauer":25,"tipp":"Paprika als Ersatz brauchen nur 5 Minuten Rösten und lassen sich leicht häuten."},{"titel":"Fleisch anbraten","aktion":"anbraten","text":"Erhitze das Öl in einer großen Pfanne bei mittlerer bis hoher Hitze und brate Schweine- und Rinderhack 8 bis 10 Minuten, bis es krümelig und braun ist. Gib die Zwiebel dazu und brate sie 5 Minuten, bis sie glasig ist. Füge den Knoblauch hinzu und brate ihn 30 Sekunden. Es soll duften, nicht verbrennen. Zerdrücke große Klumpen mit dem Pfannenwender, damit das Hack gleichmäßig wird.","dauer":15,"tipp":""},{"titel":"Früchte und Gewürze zugeben","aktion":"schmoren","text":"Gib Tomaten, Apfel, Birne, Pfirsich, Banane, Mandeln, Rosinen, Zimt, Nelken und Salz in die Pfanne. Lass die Mischung 15 bis 20 Minuten bei mittlerer Hitze köcheln, bis die Früchte weich sind und die Flüssigkeit verdampft ist. Die Füllung soll glänzend, aber nicht nass sein und nach Zimt, Frucht und Fleisch duften. Schmecke ab: süß-salzig und leicht würzig, ohne dass eine Zutat dominiert.","dauer":20,"tipp":""},{"titel":"Nogada pürieren","aktion":"puerieren","text":"Gib die geschälten Walnüsse mit Frischkäse, Sahne, Milch, Sherry, Zimt und Salz in den Mixer und püriere 2 bis 3 Minuten, bis eine glatte, weiße Creme entsteht. Sie soll dickflüssig wie Sahne sein; wenn sie zu fest ist, gib esslöffelweise Milch dazu. Schmecke ab: leicht süß, nussig und mild-salzig. Stelle sie kalt, denn die Nogada wird traditionell kalt über die warmen oder zimmerwarmen Chilis gegossen.","dauer":5,"tipp":""},{"titel":"Chilis füllen","aktion":"fuellen","text":"Fülle jede Chili mit etwa 150 Gramm Picadillo und schließe sie vorsichtig, indem du die Ränder zusammendrückst. Lege sie nebeneinander auf einen Teller. Die Füllung soll prall, aber nicht überladen sein, damit die Chili nicht aufreißt. Halte sie zimmerwarm oder wärme sie bei 150 Grad im Ofen 10 Minuten. Achte darauf, dass die Naht nach oben zeigt, damit sie beim Überziehen mit der Sauce nicht aufgeht. Prüfe, ob die Chilis stabil auf dem Teller stehen, sonst legst du sie auf ein Salatbett.","dauer":15,"tipp":""},{"titel":"Anrichten","aktion":"garnieren","text":"Gieße die kalte Nogada großzügig über die gefüllten Chilis, sodass sie vollständig bedeckt sind, und bestreue sie mit Granatapfelkernen und gehackter Petersilie. Das Gericht soll leuchten: Grün, Weiß und Rot sind die Farben der Flagge. Serviere sie sofort, solange der Kontrast zwischen warmer Füllung und kalter Sauce besteht. Dazu passt ein frischer Salat.","dauer":0,"tipp":""}],"profitipps":["Die Walnusshaut unbedingt entfernen; sonst schmeckt die Sauce bitter.","Picadillo nicht zu nass werden lassen.","Nogada gut kühlen und erst kurz vor dem Servieren über die Chilis geben.","Granatapfel frisch auslösen; Saft färbt unschön.","Mit Paprika als Ersatz arbeiten, wenn Poblanos nicht erhältlich sind."],"varianten":["Chiles en nogada capeados: Chilis im Eierteig frittiert","Vegetarisch mit Gemüse-Nuss-Füllung","Mit Mandel-Nogada statt Walnuss"],"beilagen":["frischer grüner Salat","Tortillas"],"getraenk":"Trockener Weißwein, Sekt oder Cava","koeche":[],"quellen":[{"titel":"One of Mexico's iconic dishes turns 200 years old (WUNC)","url":"https://www.wunc.org/2021-09-15/one-of-mexicos-iconic-dishes-turns-200-years-old"},{"titel":"Tacos al Pastor Named The World's Tastiest Dish (Journey Mexico)","url":"https://www.journeymexico.com/?p=32652"}],"bild":"teller","farben":["#5f8a3a","#f4ecdc","#b3262e"],"schlagworte":["Nationalgericht","Puebla","Festtag","aufwendig"],"vegetarisch_moeglich":false},{"id":"mexiko-frijoles-refritos","name":"Frijoles Refritos","originalname":"Frijoles refritos","kueche":"mexiko","region":"ganz Mexiko","beliebtheit":78,"hauptkategorie":"vegan","fleischsorte":"","gang":"beilage","kurz":"Cremig gestampfte, in Fett gebratene Bohnen – die klassische Beilage zu fast jedem mexikanischen Gericht.","hintergrund":"Frijoles refritos bedeutet wörtlich ‚wiedergebratene Bohnen‘, obwohl sie nur einmal gebraten werden: Das Vorsilbe ‚re‘ bedeutet hier ‚gründlich‘. Zuerst werden Bohnen weich gekocht, dann in heißem Fett mit Zwiebel zerdrückt und gebraten, bis sie dick und cremig sind. In Nordmexiko nimmt man Pintobohnen, im Süden schwarze Bohnen. Sie begleiten Frühstück, Tacos, Enchiladas und Tostadas und sind eines der Grundrezepte der mexikanischen Küche. Traditionell wird mit Schmalz gebraten; modern nimmt man häufig Öl.","portionen":6,"zeit":{"vorbereitung":15,"garen":120,"ruhen":480},"schwierigkeit":1,"zutaten":[{"gruppe":"Bohnen","liste":[{"menge":300,"einheit":"g","name":"getrocknete Pintobohnen","hinweis":"Ersatz: braune oder schwarze Bohnen; über Nacht eingeweicht"},{"menge":1,"einheit":"Stück","name":"Zwiebel, halbiert","hinweis":""},{"menge":3,"einheit":"Zehe","name":"Knoblauch","hinweis":""},{"menge":1,"einheit":"Zweig","name":"Epazote","hinweis":"optional; Ersatz: etwas Oregano"},{"menge":2,"einheit":"TL","name":"Salz","hinweis":""}]},{"gruppe":"Braten","liste":[{"menge":4,"einheit":"EL","name":"Pflanzenöl oder Schweineschmalz","hinweis":"Schmalz gibt den traditionellen Geschmack"},{"menge":0.5,"einheit":"Stück","name":"Zwiebel, fein gewürfelt","hinweis":""},{"menge":1,"einheit":"Zehe","name":"Knoblauch","hinweis":""},{"menge":null,"einheit":"","name":"Salz","hinweis":"nach Geschmack"}]}],"ausruestung":["großer Topf","Kartoffelstampfer oder Pürierstab","große Pfanne","Sieb"],"schritte":[{"titel":"Bohnen einweichen","aktion":"vorbereiten","text":"Spüle die Bohnen in einem Sieb gründlich ab und verlese sie, damit keine kleinen Steine oder schlechte Bohnen darin sind. Lege sie in eine große Schüssel mit reichlich kaltem Wasser, mindestens das Dreifache des Volumens, und lass sie 8 bis 12 Stunden quellen. Gieße das Wasser danach ab. Die Bohnen sollen etwa doppelt so groß sein und beim Zerdrücken innen gleichmäßig hell aussehen.","dauer":480,"tipp":"Wer keine Zeit hat, kocht die Bohnen nach dem Spülen 2 Minuten und lässt sie eine Stunde im heißen Wasser ziehen."},{"titel":"Mise en place","aktion":"vorbereiten","text":"Halbiere die Zwiebel für den Kochtopf, schäle den Knoblauch und stelle Salz und Epazote bereit. Würfle die zweite Zwiebelhälfte fein für das Braten. Lege Stampfer und Pfanne bereit. Die Bohnen brauchen später Aufmerksamkeit, wenn sie weich sind, deshalb sollten alle Zutaten bereitstehen. Setze auch den Wasserkocher auf, falls du während des Garens heißes Wasser nachgießen musst: Kaltes Wasser unterbricht den Garprozess und macht die Bohnen zäh.","dauer":5,"tipp":""},{"titel":"Bohnen kochen","aktion":"kochen","text":"Gib die eingeweichten Bohnen mit Zwiebelhälfte, Knoblauch und Epazote in einen Topf und bedecke sie mit etwa 2 Litern frischem Wasser. Bringe sie zum Kochen, schöpfe Schaum ab und lass sie dann abgedeckt bei kleiner Hitze 1,5 bis 2 Stunden sanft köcheln. Salze erst im letzten Drittel der Garzeit, damit die Haut weich bleibt. Sie sind fertig, wenn sie sich zwischen zwei Fingern leicht zerdrücken lassen und innen cremig sind.","dauer":110,"tipp":"Bohnen immer sanft köcheln, nicht sprudelnd kochen: Sonst platzt die Haut und die Bohne wird mehlig."},{"titel":"Zwiebel braten","aktion":"anbraten","text":"Erhitze das Öl oder Schmalz in einer großen Pfanne bei mittlerer Hitze. Gib die gewürfelte Zwiebel hinein und brate sie 5 bis 7 Minuten, bis sie weich und goldbraun ist. Füge den Knoblauch hinzu und brate ihn 30 Sekunden, bis er duftet. Das Fett soll heiß, aber nicht rauchend sein; die Zwiebel liefert die Süße, die später die Bohnen tragen.","dauer":8,"tipp":""},{"titel":"Bohnen stampfen und braten","aktion":"braten","text":"Gib eine Kelle Bohnen mit etwas Kochflüssigkeit in die Pfanne und zerdrücke sie mit dem Stampfer. Gib weitere Kellen hinzu und stampfe sie mit, bis alle Bohnen verarbeitet sind. Brate die Masse 8 bis 10 Minuten unter Rühren, bis sie dick wird und sich vom Pfannenboden löst. Sie ist fertig, wenn ein Löffel im Brei stehen bleibt und die Konsistenz von cremigem Kartoffelpüree hat.","dauer":12,"tipp":""},{"titel":"Abschmecken und servieren","aktion":"abschmecken","text":"Schmecke mit Salz ab; Bohnen brauchen reichlich davon. Wenn die Masse zu fest ist, rühre etwas Kochwasser unter, ist sie zu flüssig, brate sie weiter. Serviere die Frijoles heiß mit Käse, Tortillas oder als Beilage zu Eiern, Tacos und Fleisch. Reste halten sich 4 Tage im Kühlschrank und lassen sich einfrieren; beim Aufwärmen etwas Wasser zugeben.","dauer":2,"tipp":""}],"profitipps":["Bohnen erst im letzten Drittel salzen.","Sanft köcheln, nicht sprudelnd kochen.","Kochwasser aufheben – es verdünnt und gibt Geschmack.","Mit Schmalz traditionell, mit Öl vegan.","Konsistenz nach Wunsch: von rustikal grob bis seidig-glatt."],"varianten":["Mit Chorizo gebraten","Frijoles negros (Schwarze Bohnen) aus Oaxaca","Frijoles de la olla – ungestampft in der Brühe"],"beilagen":["Tortillas","Käse","Eier","Tacos"],"getraenk":"Beliebig; passt zu Bier und Limonade","koeche":[],"quellen":[{"titel":"Uncomplicated Mexican dishes rate among world's best (Guadalajara Reporter)","url":"https://theguadalajarareporter.net/index.php/featured/61332-uncomplicated-mexican-dishes-rate-among-world-s-best"},{"titel":"Recipes: Pozole two ways (KCRW Good Food)","url":"https://www.kcrw.com/shows/good-food/stories/recipes-pozole-two-ways"}],"bild":"teller","farben":["#6b3a22","#a8693a","#e5c99a"],"schlagworte":["Beilage","Grundrezept","vegan"],"vegetarisch_moeglich":true},{"id":"mexiko-aguachile-de-camaron","name":"Aguachile de camarón","originalname":"Aguachile de camarón","kueche":"mexiko","region":"Sinaloa (Pazifikküste)","beliebtheit":76,"hauptkategorie":"fisch","fischsorte":"meeresfruechte","gang":"vorspeise","kurz":"Rohe, aufgeklappte Garnelen in einer feurig-grünen Limetten-Chili-Brühe mit Gurke und roter Zwiebel – frisch, scharf und in Minuten fertig.","hintergrund":"Aguachile bedeutet wörtlich „Chiliwasser“ und stammt von der Küste von Sinaloa im Nordwesten Mexikos. Die ursprüngliche Version war ein Garnelengericht, das mit gekochtem Wasser und winzigen, sehr scharfen Chiltepín-Beeren angemacht wurde; heute ist die Basis Limettensaft mit frischen grünen Chilis und Koriander. Rohe Garnelen oder Fisch werden in der Flüssigkeit kurz „gegart“, dazu kommen Gurkenscheiben und rote Zwiebel. Traditionell wird es im Molcajete serviert und sofort gegessen, mit Tostadas oder Salzcrackern. Anders als beim Ceviche ziehen die Garnelen nur minutenlang, damit sie innen glasig und zart bleiben – der Biss ist das Ziel.","portionen":4,"zeit":{"vorbereitung":25,"garen":0,"ruhen":15},"schwierigkeit":2,"zutaten":[{"gruppe":"Garnelen","liste":[{"menge":500,"einheit":"g","name":"rohe Garnelen, 16/20 oder größer, geschält und entdarmt","hinweis":"Für Rohverzehr nur sehr frische oder tiefgekühlte Ware mit lückenloser Kühlkette verwenden; nicht bei Schwangeren, kleinen Kindern oder Immunschwäche"},{"menge":0.5,"einheit":"TL","name":"Salz","hinweis":"zum Anmachen der Garnelen"}]},{"gruppe":"Grüne Chilibrühe","liste":[{"menge":200,"einheit":"ml","name":"frisch gepresster Limettensaft (ca. 8–10 Limetten)","hinweis":"unbedingt frisch, nie aus der Flasche"},{"menge":3,"einheit":"Stück","name":"grüne Chilis (Serrano, ersatzweise Jalapeño oder Thai-Chili)","hinweis":"für mehr Schärfe Kerne mitmixen"},{"menge":0.5,"einheit":"Bund","name":"Koriandergrün","hinweis":""},{"menge":1,"einheit":"Zehe","name":"Knoblauch","hinweis":""},{"menge":0.5,"einheit":"Stück","name":"Salatgurke","hinweis":"für die Brühe, entkernt"},{"menge":1,"einheit":"TL","name":"Salz","hinweis":""}]},{"gruppe":"Zum Anrichten","liste":[{"menge":1,"einheit":"Stück","name":"Salatgurke","hinweis":"dünn in Scheiben"},{"menge":0.5,"einheit":"Stück","name":"rote Zwiebel","hinweis":"in hauchdünnen Ringen"},{"menge":1,"einheit":"Stück","name":"reife Avocado","hinweis":"in Scheiben"},{"menge":null,"einheit":"","name":"Tostadas oder Saltine-Cracker","hinweis":"zum Servieren"}]}],"ausruestung":["Stabmixer oder Standmixer","Feines Sieb","Flache Servierschüssel oder Molcajete","Scharfes kleines Messer"],"schritte":[{"titel":"Mise en place","aktion":"vorbereiten","text":"Stelle eine flache Schüssel oder Platte kalt, denn Aguachile schmeckt am besten eiskalt. Presse alle Limetten aus und seihe den Saft durch ein Sieb, damit keine Kerne und kein Fruchtfleisch in die Brühe kommen. Wasche Gurke, Koriander und Chilis, schneide die Gurke mit einem Gemüsehobel oder scharfen Messer in fast durchsichtige Scheiben und die Zwiebel in hauchdünne Ringe. Lege die Zwiebelringe für 5 Minuten in Eiswasser, dann werden sie knackig und milder.","dauer":0,"tipp":""},{"titel":"Garnelen entdarmen und aufklappen","aktion":"schneiden","text":"Entferne Köpfe, Schalen und Schwanz. Schneide jede Garnele entlang des Rückens bis fast zur Unterseite ein und ziehe den dunklen Darmfaden heraus. Klappe sie dann wie ein Buch auf (Schmetterlingsschnitt), sodass sie flach liegen und viel Oberfläche für die Brühe bieten. Spüle sie kurz ab und tupfe sie trocken. Das Fleisch soll fest, durchscheinend und frisch nach Meer riechen; riecht es nach Ammoniak oder ist es matschig, entsorge es.","dauer":10,"tipp":"Tiefgekühlte Garnelen langsam im Kühlschrank oder in Eiswasser auftauen, damit sie fest und frisch bleiben."},{"titel":"Garnelen vorsalzen und kühlen","aktion":"marinieren","text":"Verteile die aufgeklappten Garnelen in einer flachen Lage in der kalten Schüssel und bestreue sie leicht mit Salz. Stelle sie für ein paar Minuten in den Kühlschrank, während du die Brühe zubereitest. Das Salz würzt das Fleisch von innen und macht es ein wenig fester. So gehen die Garnelen später nicht in der sauren Flüssigkeit verloren, sondern bleiben bissfest.","dauer":5,"tipp":""},{"titel":"Chilibrühe mixen","aktion":"puerieren","text":"Gib Limettensaft, Chilis, Koriander, Knoblauch, die entkernte Gurke und Salz in den Mixer und püriere alles etwa 30 Sekunden, bis eine leuchtend grüne, fein strukturierte Flüssigkeit entsteht. Sie soll scharf, sauer und kräftig nach Kräutern riechen. Probiere einen Tropfen auf der Zunge: Wird es zu scharf, gib etwas Gurkensaft oder Limette zu; ist es zu zahm, mixe eine weitere Chili mit. Seihe die Brühe durch ein feines Sieb, damit sie klar und glatt wird.","dauer":3,"tipp":"Chilis nie mit bloßen Fingern entkernen und danach nicht die Augen reiben – Handschuhe helfen."},{"titel":"Garnelen in der Brühe ziehen lassen","aktion":"marinieren","text":"Gieße die Brühe über die Garnelen, sodass alle gut bedeckt sind, und lasse sie 10 bis 15 Minuten im Kühlschrank ziehen. Durch die Säure verändert das Fleisch langsam die Farbe von glasig-grau zu zartrosa und wird fester, ähnlich wie beim Garen. Nach etwa 10 Minuten sollten die Garnelen außen deckend rosa, innen aber noch leicht glasig sein; mehr als 20 Minuten machen sie zäh und kreidig. Wende sie einmal, damit sie gleichmäßig ziehen.","dauer":15,"tipp":"Je größer die Garnele, desto länger darf sie ziehen – nach dem Probieren richtig entscheiden."},{"titel":"Gurke und Zwiebel auslegen","aktion":"schichten","text":"Verteile die Gurkenscheiben auf der gekühlten Platte, am besten leicht überlappend, und lege abgetropfte Zwiebelringe darüber. Salze beides ganz leicht und beträufele es mit einem Löffel der Chilibrühe. Dieser knackige Untergrund bietet Biss und Frische, nimmt die Schärfe auf und macht den Teller optisch aus. Arbeite kalt: Die Platte darf nicht warm werden, sonst verliert das Gericht seinen Reiz.","dauer":3,"tipp":""},{"titel":"Anrichten","aktion":"anrichten","text":"Hebe die Garnelen mit einer Gabel aus der Brühe und lege sie in einer Reihe über die Gurke. Gieße so viel Brühe darüber, dass alles gut feucht ist, aber nicht in der Flüssigkeit schwimmt. Verteile Avocadoscheiben, Korianderblätter und, wenn du magst, ein paar dünne Chiliringe obenauf. Die Farben sollen leuchten: das Rosa der Garnelen auf dem Grün der Gurke und der Brühe.","dauer":0,"tipp":"Zusätzliche scharfe Sauce und Limettenspalten am Tisch lassen jeden nach Geschmack nachwürzen."},{"titel":"Sofort servieren","aktion":"garnieren","text":"Serviere den Aguachile sofort mit Tostadas oder Salzcrackern und kaltem Bier. Je länger er steht, desto weiter garen die Garnelen in der Säure und desto weicher wird die Gurke. Iss deshalb gleich nach dem Anrichten. Reste solltest du nicht aufheben, denn rohe Garnelen in Säure sind eine Speise für den Moment.","dauer":0,"tipp":""}],"profitipps":["Frischer Limettensaft und kalte Zutaten sind das Fundament; Flaschensaft schmeckt flach und bitter.","Nur 10–15 Minuten ziehen lassen: Die Garnelen sollen innen glasig und saftig bleiben.","Den Chili sehr fein pürieren und sieben, damit die Brühe seidig wird.","Gurke und Zwiebel hauchdünn schneiden und kalt halten für den Biss.","Nur Garnelen in Rohverzehr-Qualität verwenden und auf lückenlose Kühlung achten."],"varianten":["Aguachile rojo mit getrockneten roten Chilis (Chile de árbol) statt grüner Chilis.","Mit Jakobsmuscheln (Scallop Aguachile) oder Fisch statt Garnelen.","Mit Mango oder Orange für eine fruchtige Note.","Mit gekochten (pochierten) Garnelen für alle, die Rohverzehr meiden."],"beilagen":["Tostadas","Saltine-Cracker","Avocado","Eiskaltes Bier mit Limette"],"getraenk":"Eiskaltes Lagerbier (Pacífico) mit Limette, trockener Weißwein oder ein Mezcal-Margarita.","koeche":[{"name":"Rick Bayless","bezug":"Zeigt auf seiner Webseite verschiedene Aguachile-Varianten (klassisch mit Garnelen, mit Jakobsmuscheln, mit Lachs und Kiwi) und macht das Gericht für ein internationales Publikum zugänglich.","quelle":"https://www.rickbayless.com/recipe/shrimp-in-aguachile/"}],"quellen":[{"titel":"Aguachile – Wikipedia","url":"https://en.wikipedia.org/wiki/Aguachile"},{"titel":"The Classic Shrimp Aguachile – Rick Bayless","url":"https://www.rickbayless.com/recipe/shrimp-in-aguachile/"},{"titel":"Ceviche, Aguachiles and Other Mariscos – Rick Bayless","url":"https://www.rickbayless.com/recipe-category/ceviche-aguachiles-and-other-mariscos/"}],"bild":"meeresfruechte","farben":["#7fb04a","#f0a79a","#2f6b3a"],"schlagworte":["Sinaloa","Roh","Scharf","Limette"],"vegetarisch_moeglich":false},{"id":"mexiko-chilaquiles-rojos","name":"Chilaquiles rojos mit Spiegelei","originalname":"Chilaquiles rojos","kueche":"mexiko","region":"Ganz Mexiko, besonders Mexiko-Stadt","beliebtheit":76,"hauptkategorie":"vegetarisch","fleischsorte":"","gang":"fruehstueck","kurz":"Knusprige Tortillastücke in roter Chilisauce geschwenkt, mit Crema, Zwiebel, Käse und Spiegelei – das mexikanische Katerfrühstück schlechthin.","hintergrund":"Chilaquiles sind ein Frühstücksklassiker in ganz Mexiko und entstanden als clevere Resteverwertung: Alte, harte Tortillas werden in Stücke geschnitten, frittiert und in einer Chilisauce geschwenkt, bis sie weich, aber nicht matschig sind. Man unterscheidet rote (rojos) Sauce aus Tomaten oder getrockneten Chilis und grüne (verdes) aus Tomatillos. Serviert werden sie mit saurer Sahne (Crema), Zwiebel, frischem Käse und Koriander, oft mit einem Spiegelei oder gezupftem Hähnchen. Der amerikanische Koch Rick Bayless beschreibt in seinem Master-Rezept, wie wichtig es ist, die Sauce gut einzukochen und die Chips erst im letzten Moment einzurühren. Typisch ist der Kontrast zwischen noch knusprigem Rand und weicher Mitte.","portionen":4,"zeit":{"vorbereitung":25,"garen":40,"ruhen":0},"schwierigkeit":2,"zutaten":[{"gruppe":"Rote Tomatensauce","liste":[{"menge":700,"einheit":"g","name":"reife Tomaten","hinweis":"Flaschentomaten oder Strauchtomaten"},{"menge":2,"einheit":"Stück","name":"Jalapeño oder Serrano-Chilis","hinweis":"nach gewünschter Schärfe; Samen entfernen macht milder"},{"menge":1,"einheit":"Stück","name":"weiße Zwiebel","hinweis":"in Scheiben"},{"menge":2,"einheit":"Zehe","name":"Knoblauch","hinweis":""},{"menge":1.5,"einheit":"EL","name":"Pflanzenöl","hinweis":""},{"menge":500,"einheit":"ml","name":"Gemüse- oder Hühnerbrühe","hinweis":""},{"menge":1,"einheit":"TL","name":"Salz","hinweis":"nach Geschmack"},{"menge":1,"einheit":"Handvoll","name":"Koriander","hinweis":""}]},{"gruppe":"Tortillas und Toppings","liste":[{"menge":12,"einheit":"Stück","name":"Maistortillas (15 cm), ein bis zwei Tage alt","hinweis":"ersatzweise ca. 250 g dicke Tortilla-Chips (ungesalzen, ungewürzt)"},{"menge":300,"einheit":"ml","name":"Pflanzenöl zum Frittieren","hinweis":"ca. 2 cm hoch"},{"menge":4,"einheit":"Stück","name":"Eier","hinweis":"für Spiegeleier"},{"menge":120,"einheit":"ml","name":"Crème fraîche oder saure Sahne","hinweis":"mit etwas Milch verdünnt (Ersatz für Crema)"},{"menge":0.5,"einheit":"Stück","name":"weiße Zwiebel","hinweis":"in dünnen Ringen"},{"menge":60,"einheit":"g","name":"Queso fresco, Feta oder Parmesan","hinweis":"zerbröckelt oder gerieben"},{"menge":1,"einheit":"Stück","name":"Avocado","hinweis":"optional"}]}],"ausruestung":["große Pfanne mit hohem Rand","Backblech","Pürierstab","Schaumlöffel","Küchenpapier"],"schritte":[{"titel":"Alles vorbereiten","aktion":"vorbereiten","text":"Wasche die Tomaten und halbiere sie, entferne den Stiel der Chilis und schneide die Zwiebel in dicke Scheiben. Schneide die Tortillas in sechs Spalten oder in 3 cm breite Streifen, wenn sie noch feucht sind, lasse sie 15 Minuten antrocknen, damit sie beim Frittieren nicht zu viel Öl aufsaugen. Bereite die Toppings vor: Zwiebelringe schneiden, Käse zerbröseln, Koriander hacken und Crème fraîche mit einem Schuss Milch glatt rühren. Heize den Backofengrill auf höchste Stufe vor.","dauer":0,"tipp":"Je älter und trockener die Tortillas, desto knuspriger bleiben die Chips in der Sauce."},{"titel":"Gemüse rösten","aktion":"grillen","text":"Verteile Tomaten, Chilis, Zwiebelscheiben und Knoblauch auf einem Blech und grille sie auf der obersten Schiene 8 bis 10 Minuten, bis die Haut stellenweise schwarz wird und das Gemüse weich ist, wende dabei einmal. Der leicht rauchige Duft ist erwünscht und gibt der Sauce ihre Tiefe. Entferne die dicke Haut der Tomaten, falls sie sich leicht abziehen lässt, und püriere alles zu einer fast glatten Sauce mit ein paar kleinen Stückchen.","dauer":12,"tipp":""},{"titel":"Sauce einkochen","aktion":"reduzieren","text":"Erhitze das Öl in einer großen Pfanne bei hoher Hitze und gib das Püree auf einmal hinein. Es spritzt und zischt; rühre ständig und koche es 6 bis 8 Minuten ein, bis es dunkler und deutlich dicker ist. Gieße dann die Brühe dazu und koche die Sauce weitere 5 Minuten leicht köchelnd ein, bis sie die Konsistenz von dünnflüssiger Tomatensuppe hat. Schmecke mit Salz ab und rühre Koriander unter. Nimm die Pfanne beiseite und halte die Sauce warm.","dauer":15,"tipp":"Die Sauce soll nicht zu dick sein, denn die Tortillas saugen noch Flüssigkeit auf."},{"titel":"Tortillas frittieren","aktion":"frittieren","text":"Erhitze das Öl in einer tiefen Pfanne auf etwa 180 °C; ein Holzlöffelstiel im Öl sollte lebhaft Bläschen bilden. Frittiere die Tortillastücke in Portionen 2 bis 3 Minuten, bis das Blubbern nachlässt und die Stücke goldgelb und knusprig sind. Hebe sie mit dem Schaumlöffel heraus, lasse sie auf Küchenpapier abtropfen und salze sie leicht. Frittiere nicht zu viel auf einmal, damit die Öltemperatur nicht sinkt und die Chips nicht fettig werden.","dauer":10,"tipp":"Alternativ gute dicke Tortilla-Chips aus der Tüte verwenden, sie halten gut."},{"titel":"Chips in der Sauce schwenken","aktion":"mischen","text":"Erhitze die Sauce in der großen Pfanne bis zum Köcheln. Gib die Chips auf einmal hinein und hebe sie mit einem Holzlöffel um, bis alles gleichmäßig mit Sauce benetzt ist. Nimm die Pfanne sofort vom Herd, decke sie zu und lasse sie 1 bis 2 Minuten stehen, damit die Chips weicher werden, aber noch Biss behalten. Wer sie ganz knusprig mag, serviert sofort; wer sie weicher möchte, lässt sie 3 bis 4 Minuten ziehen.","dauer":3,"tipp":"Chips erst im letzten Moment in die Sauce geben, sonst werden sie matschig."},{"titel":"Spiegeleier braten und anrichten","aktion":"anrichten","text":"Brate die Spiegeleier bei mittlerer Hitze in wenig Öl, so dass das Eiweiß fest und das Eigelb noch flüssig ist. Verteile die Chilaquiles sofort auf vorgewärmte tiefe Teller, lege auf jede Portion ein Spiegelei und beträufle es mit verdünnter Crème fraîche. Streue Zwiebelringe, Käse und Koriander darüber und lege bei Bedarf Avocadoscheiben dazu. Serviere sofort, denn die knusprige Konsistenz hält nur Minuten. Dazu passen schwarze Bohnen oder gezupftes Hähnchen.","dauer":5,"tipp":""}],"profitipps":["Alte, trockene Tortillas sind ideal, sie saugen weniger Öl und bleiben länger knusprig.","Sauce gut einkochen: Sie bestimmt den Geschmack.","Chips erst am Schluss in die Sauce geben und sofort servieren.","Crema, rohe Zwiebel und Käse sind klassische Toppings, die Frische und Fett liefern.","Geröstete Tomaten und Chilis geben die rauchige Tiefe."],"varianten":["Chilaquiles verdes: mit gerösteten Tomatillos statt Tomaten.","Mit gezupftem Hähnchen oder Rindfleisch.","Mit Guajillo-Chilis für eine dunkle, fruchtig-scharfe Sauce.","Chilaquiles divorciados: halb rot, halb grün."],"beilagen":["Frijoles refritos","Avocado","Eier","Hähnchen"],"getraenk":"Café de olla oder frisch gepresster Orangensaft","koeche":[{"name":"Rick Bayless","bezug":"Der amerikanische Mexiko-Koch stellt auf seiner Webseite ein Master-Rezept für Chilaquiles mit Tomaten- oder Tomatillosauce und verschiedenen Toppings bereit und erklärt dort die Technik.","quelle":"https://www.rickbayless.com/recipe/chilaquiles-master-recipe/"}],"quellen":[{"titel":"Rick Bayless: Chilaquiles Master Recipe","url":"https://www.rickbayless.com/recipe/chilaquiles-master-recipe/"},{"titel":"Rick Bayless: Guajillo Chilaquiles","url":"https://www.rickbayless.com/recipe/guajillo-chilaquiles/"},{"titel":"Rick Bayless: Tomatillo Sauced Chilaquiles","url":"https://www.rickbayless.com/recipe/tomatillo-sauced-chilaquiles/"}],"bild":"pfanne","farben":["#b8321f","#e8c15a","#4f6b2a"],"schlagworte":["Mexiko","Frühstück","Tortillas","Resteverwertung","scharf"],"vegetarisch_moeglich":true},{"id":"mexiko-barbacoa-de-res","name":"Barbacoa de Res","originalname":"Barbacoa de res","kueche":"mexiko","region":"Hidalgo / Mexiko-Stadt","beliebtheit":76,"hauptkategorie":"fleisch","fleischsorte":"rind","gang":"hauptgericht","kurz":"Rindfleisch in einer rauchig-würzigen Chili-Marinade, stundenlang im Ofen gegart, bis es auf der Zunge zergeht – die Heimversion des Erdofen-Klassikers.","hintergrund":"Barbacoa bezeichnet in Mexiko eine uralte Garmethode: Fleisch wird in einer mit Agavenblättern ausgekleideten Erdgrube stundenlang über heißen Steinen gegart. Der Begriff ist Ursprung unseres Wortes Barbecue. Am bekanntesten ist die Version aus Hidalgo mit Lamm; im Norden nimmt man Rind, besonders Wangen. Serviert wird das Fleisch am Wochenende in Tacos, begleitet von einer Brühe (Consomé) aus den Fleischsäften und mit viel Koriander, Zwiebel und scharfer Salsa. Zuhause gelingt es im Ofen mit gut abgedichtetem Topf.","portionen":6,"zeit":{"vorbereitung":30,"garen":270,"ruhen":240},"schwierigkeit":2,"zutaten":[{"gruppe":"Fleisch","liste":[{"menge":1.8,"einheit":"kg","name":"Rinderbacken oder Rinderschulter","hinweis":"in 6–8 cm große Stücke"},{"menge":2,"einheit":"TL","name":"Salz","hinweis":""},{"menge":4,"einheit":"Stück","name":"Avocadoblätter oder Bananenblätter","hinweis":"TK-Bananenblätter aus dem Asia-/Lateinamerika-Laden; ersatzweise Backpapier und Alufolie"}]},{"gruppe":"Adobo","liste":[{"menge":5,"einheit":"Stück","name":"getrocknete Guajillo-Chilis","hinweis":""},{"menge":2,"einheit":"Stück","name":"getrocknete Ancho-Chilis","hinweis":""},{"menge":2,"einheit":"Stück","name":"Chipotle-Chilis in Adobo (aus der Dose)","hinweis":""},{"menge":6,"einheit":"Zehe","name":"Knoblauch","hinweis":""},{"menge":60,"einheit":"ml","name":"Apfelessig","hinweis":""},{"menge":1,"einheit":"TL","name":"Kreuzkümmel","hinweis":""},{"menge":1,"einheit":"TL","name":"Oregano","hinweis":""},{"menge":0.5,"einheit":"TL","name":"Zimt","hinweis":""},{"menge":3,"einheit":"Stück","name":"Gewürznelken","hinweis":""},{"menge":1,"einheit":"Stück","name":"Zwiebel","hinweis":""},{"menge":2,"einheit":"Stück","name":"Lorbeerblätter","hinweis":""}]},{"gruppe":"Zum Servieren","liste":[{"menge":18,"einheit":"Stück","name":"Maistortillas","hinweis":""},{"menge":1,"einheit":"Stück","name":"weiße Zwiebel, gewürfelt","hinweis":""},{"menge":1,"einheit":"Bund","name":"Koriander","hinweis":""},{"menge":3,"einheit":"Stück","name":"Limetten","hinweis":""}]}],"ausruestung":["Schmortopf oder Bräter mit Deckel","Alufolie","Standmixer","Sieb"],"schritte":[{"titel":"Mise en place","aktion":"vorbereiten","text":"Schneide das Fleisch in 6 bis 8 Zentimeter große Stücke, entferne dicke Sehnen und salze es rundum mit zwei Teelöffeln Salz. Lass es 15 Minuten bei Raumtemperatur ruhen; so zieht das Salz ein. Entferne bei den Chilis Stiele und Kerne und schäle Knoblauch und Zwiebel. Schneide die Blätter, falls du welche hast, zu Bahnen, die den Topfboden bedecken.","dauer":15,"tipp":""},{"titel":"Chilis rösten und einweichen","aktion":"vorbereiten","text":"Röste die Chilis in einer trockenen Pfanne bei mittlerer Hitze pro Seite 10 bis 15 Sekunden, bis sie duften und biegsam sind. Nicht zu lange rösten; sie werden sonst bitter. Übergieße sie mit 400 Millilitern kochendem Wasser und lass sie 20 Minuten einweichen. Sie sind bereit, wenn das Fruchtfleisch weich und die Haut nicht mehr ledrig ist.","dauer":25,"tipp":""},{"titel":"Adobo pürieren","aktion":"puerieren","text":"Gib die abgetropften Chilis, Chipotles, Knoblauch, Essig, Gewürze, Zwiebel und etwa 150 Millilitern des Einweichwassers in den Mixer und püriere 2 Minuten sehr fein. Streiche die Sauce durch ein Sieb. Sie soll dickflüssig, dunkelrot und rauchig duften. Schmecke vorsichtig: Sie soll kräftig, leicht sauer und scharf sein, denn das Fleisch verdünnt sie stark.","dauer":5,"tipp":""},{"titel":"Fleisch marinieren","aktion":"marinieren","text":"Reibe das Fleisch mit dem Adobo ein, bis alle Seiten bedeckt sind. Lege es in eine Schüssel, decke sie ab und stelle sie für mindestens 4 Stunden, besser über Nacht, in den Kühlschrank. Das Adobo dringt in die Fasern ein und gibt dem Fleisch Farbe und Aroma. Wende es zwischendurch einmal und achte darauf, dass die Marinade auch in die Zwischenräume der Stücke gelangt. Die Farbe wird über Nacht dunkler und das Fleisch schmeckt nach dem Garen deutlich tiefer als bei kurzer Marinierzeit; nimm es vor dem Garen 30 Minuten aus dem Kühlschrank.","dauer":240,"tipp":""},{"titel":"Topf auslegen und befüllen","aktion":"vorbereiten","text":"Heize den Backofen auf 150 Grad Ober-/Unterhitze (130 Grad Umluft) vor. Lege den Boden des Bräters mit Blättern oder Backpapier aus, gib die Lorbeerblätter hinein und setze das Fleisch samt Marinade darauf. Gieße 200 Millilitern Wasser an. Bedecke das Fleisch mit weiteren Blättern oder Backpapier und decke den Bräter mit Alufolie und Deckel dicht ab. Der Dampf darf nicht entweichen.","dauer":10,"tipp":""},{"titel":"Langsam garen","aktion":"schmoren","text":"Stelle den Bräter in den Ofen und lass das Fleisch 4 bis 4,5 Stunden garen. Es ist fertig, wenn es sich mit zwei Gabeln mühelos zerfasern lässt und die Flüssigkeit tiefrot und aromatisch ist. Öffne den Deckel vorsichtig; der Dampf ist heiß. Das Fleisch soll glänzen, weich sein und intensiv nach Chili, Zwiebel und Lorbeer duften.","dauer":270,"tipp":""},{"titel":"Zerzupfen und Consomé gewinnen","aktion":"schneiden","text":"Hebe das Fleisch heraus und zupfe es in Fasern. Entferne Fettstücke. Seihe die Garflüssigkeit ab und schöpfe das Fett ab. Schmecke den Saft mit Salz und Limette ab; er ist der Consomé und wird separat serviert. Mische einen Teil des Saftes unter das Fleisch, damit es saftig bleibt. Probiere ein Stück: Es soll weich, würzig und leicht rauchig schmecken, mit einer angenehmen Schärfe im Abgang. Falls es fad wirkt, gib einen Spritzer Limettensaft und eine Prise Salz dazu, bis der Geschmack klar und frisch ist.","dauer":10,"tipp":""},{"titel":"Tortillas wärmen","aktion":"braten","text":"Erwärme die Tortillas in einer trockenen Pfanne 30 Sekunden pro Seite, bis sie weich sind, und halte sie in einem Tuch warm. Hacke Zwiebel und Koriander und schneide die Limetten. Stelle alles auf den Tisch, damit jeder seine Tacos selbst belegen kann. Zwei Tortillas pro Taco verhindern, dass der saftige Taco durchweicht.","dauer":5,"tipp":""},{"titel":"Anrichten","aktion":"anrichten","text":"Gib zwei Esslöffel Fleisch in jede Tortilla, streue Zwiebel und Koriander darüber und träufle Salsa und Limette darauf. Serviere den Consomé in Tassen dazu. Das Fleisch ist am nächsten Tag noch besser; im Saft lagern hält es saftig. Reste im Kühlschrank 4 Tage, tiefgekühlt 3 Monate; wärme sie im Saft schonend auf. Aus dem restlichen Fleisch wird am nächsten Tag eine hervorragende Füllung für Quesadillas oder Burritos.","dauer":0,"tipp":""}],"profitipps":["Rinderbacken sind ideal: viel Kollagen, sehr zart.","Den Bräter fest abdichten – kein Dampfverlust.","Mit Chipotle ein Raucharoma nachbilden, das im Ofen sonst fehlt.","Consomé unbedingt mitservieren.","Am Vortag marinieren."],"varianten":["Barbacoa de borrego (Lamm) wie in Hidalgo","Barbacoa de chivo (Ziege)","Slow-Cooker-Variante: 8–10 Stunden auf niedriger Stufe"],"beilagen":["Consomé","Mexikanischer Reis","Frijoles refritos","Salsa verde"],"getraenk":"Kräftiges Lagerbier oder Rotwein","koeche":[],"quellen":[{"titel":"Birria (CIA Foodies)","url":"https://www.ciafoodies.com/birria/"},{"titel":"Uncomplicated Mexican dishes rate among world's best (Guadalajara Reporter)","url":"https://theguadalajarareporter.net/index.php/featured/61332-uncomplicated-mexican-dishes-rate-among-world-s-best"}],"bild":"braten-scheiben","farben":["#7a2d17","#b5532a","#e7c08a"],"schlagworte":["Wochenendessen","Schmoren","Tacos"],"vegetarisch_moeglich":false},{"id":"mexiko-caldo-de-res","name":"Caldo de Res – mexikanischer Rindfleisch-Gemüse-Eintopf","originalname":"Caldo de res","kueche":"mexiko","region":"Nordmexiko, landesweit","beliebtheit":75,"hauptkategorie":"fleisch","fleischsorte":"rind","gang":"eintopf","kurz":"Der mexikanische Sonntagseintopf: Rinderhaxe mit Knochen, Mais, Kürbis, Kartoffeln und Kohl in einer klaren, goldenen Brühe, die mit Limette, Koriander und Salsa am Tisch vollendet wird.","hintergrund":"Caldo de res ist in ganz Mexiko ein Klassiker der Hausküche und wird besonders im Norden des Landes gern am Wochenende oder bei kühlem Wetter gekocht. Die Grundidee: Rindfleisch mit Knochen stundenlang sanft garen, bis eine kräftige Brühe entsteht, dann Gemüse hinzufügen, das gerade Saison hat, etwa Maiskolben, Chayote, Zucchini, Möhren, Kartoffeln und Kohl. Der Eintopf wird mit Reis, warmen Tortillas und frischen Beilagen serviert: gehackte Zwiebel, Koriander, Limettenspalten und eine scharfe Salsa. Weil er Markknochen enthält, ist die Brühe reich und leicht gelatinös; das Mark selbst gilt als Delikatesse und wird auf eine Tortilla gestrichen. In Familien ist es ein Gericht, das Geborgenheit und Heilung verspricht – ein Mexikaner würde es dir bei Erkältung oder Kater verschreiben.","portionen":6,"zeit":{"vorbereitung":30,"garen":180,"ruhen":0},"schwierigkeit":1,"zutaten":[{"gruppe":"Für die Brühe","liste":[{"menge":1.2,"einheit":"kg","name":"Rinderhaxe (Beinscheibe) mit Knochen","hinweis":"in Scheiben von 3–4 cm; der Knochen mit Mark gibt Geschmack und Körper"},{"menge":500,"einheit":"g","name":"Rinderrippen oder Markknochen","hinweis":"optional; gibt zusätzlich Tiefe"},{"menge":3.5,"einheit":"l","name":"kaltes Wasser"},{"menge":1,"einheit":"Stück","name":"Zwiebel, halbiert"},{"menge":4,"einheit":"Zehe","name":"Knoblauch, ungeschält angedrückt"},{"menge":2,"einheit":"Blatt","name":"Lorbeerblätter"},{"menge":1,"einheit":"TL","name":"ganze schwarze Pfefferkörner"},{"menge":1,"einheit":"Bund","name":"frischer Koriander (die Stiele für die Brühe)"},{"menge":2,"einheit":"TL","name":"Salz","hinweis":"später nach Geschmack nachsalzen"}]},{"gruppe":"Für das Gemüse","liste":[{"menge":3,"einheit":"Stück","name":"Möhren, in dicke Stücke geschnitten"},{"menge":500,"einheit":"g","name":"festkochende Kartoffeln, in große Würfel"},{"menge":3,"einheit":"Stück","name":"Maiskolben, in 3-cm-Scheiben (Elote)","hinweis":"frisch oder TK; Dosenmais geht notfalls"},{"menge":2,"einheit":"Stück","name":"Zucchini, in dicke Scheiben"},{"menge":2,"einheit":"Stück","name":"Chayote (Stachelgurke), geschält und in Würfel","hinweis":"optional; in Mexiko üblich, im gut sortierten Gemüsehandel; sonst weglassen"},{"menge":400,"einheit":"g","name":"Weißkohl, in 6 Spalten mit Strunk"},{"menge":2,"einheit":"Stück","name":"Tomaten, geviertelt","hinweis":"optional, für leichte Säure"}]},{"gruppe":"Zum Servieren","liste":[{"menge":1,"einheit":"Stück","name":"weiße Zwiebel, fein gewürfelt"},{"menge":1,"einheit":"Bund","name":"frischer Koriander, gehackt"},{"menge":3,"einheit":"Stück","name":"Limetten, in Spalten"},{"menge":12,"einheit":"Stück","name":"Maistortillas, warm"},{"menge":300,"einheit":"g","name":"gekochter Reis (Arroz blanco)"},{"menge":null,"einheit":"","name":"Salsa picante, z. B. Salsa Verde oder Chile de Árbol","hinweis":"nach Geschmack"}]}],"ausruestung":["großer Topf (mind. 6 l)","Schaumkelle","feines Sieb (optional)","Schüsseln für die Beilagen","Tortillawärmer oder Küchentuch"],"schritte":[{"titel":"Fleisch vorbereiten","aktion":"vorbereiten","text":"Nimm das Fleisch etwa 30 Minuten vor dem Kochen aus dem Kühlschrank, damit es nicht eiskalt in den Topf kommt, und spüle die Haxenscheiben kurz unter kaltem Wasser ab. Tupfe sie mit Küchenpapier trocken und würze sie rundum großzügig mit 1 Teelöffel Salz. Schäle die Zwiebel, halbiere sie, drücke die Knoblauchzehen mit der Messerflachseite an, sodass die Schale aufplatzt. Löse die Korianderblätter von den Stielen und bewahre die Blätter im Kühlschrank auf, denn sie kommen erst zum Servieren, die Stiele wandern in die Brühe.","dauer":0,"tipp":"Nicht zu mageres Fleisch nehmen: Der Knochen und das Bindegewebe liefern Geschmack und Körper."},{"titel":"Fleisch scharf anbraten (optional, aber lohnend)","aktion":"anbraten","text":"Erhitze 2 Esslöffel Öl in dem großen Topf bei hoher Hitze, bis es leicht zu rauchen beginnt. Brate die Haxenscheiben in zwei Portionen jeweils 2–3 Minuten pro Seite an, bis sie rundum tiefbraun sind und an den Rändern knusprig werden. Das Anbraten erzeugt Röstaromen, die der Brühe Tiefe geben und sie goldener machen. Verwende nicht zu viele Stücke auf einmal, sonst sinkt die Temperatur und das Fleisch kocht, statt zu bräunen. Das Fleisch wird dabei noch nicht gar.","dauer":10,"tipp":"Traditionell kocht man das Fleisch auch roh an – die Brühe wird dann heller und klarer. Beides ist richtig."},{"titel":"Brühe ansetzen und abschäumen","aktion":"kochen","text":"Gib Fleisch, Knochen, Zwiebel, Knoblauch, Lorbeer, Pfefferkörner und Korianderstiele in den Topf und gieße 3,5 Liter kaltes Wasser auf, sodass alles gut bedeckt ist. Erhitze bei mittlerer Hitze, bis die Brühe zu köcheln beginnt; das dauert etwa 20 Minuten. Es steigen grau-schaumige Eiweißflocken auf, die du mit der Schaumkelle konsequent abschöpfst. Das ist der Schlüssel zu einer klaren, goldgelben Brühe statt einer trüben Suppe. Sobald nur noch weißer, dünner Schaum kommt, reduzierst du die Hitze.","dauer":25,"tipp":"Kaltes Wasser zu Beginn löst das Eiweiß aus dem Fleisch langsam und gibt einen klareren Fond."},{"titel":"Lange und sanft köcheln","aktion":"koecheln","text":"Stelle die Hitze so ein, dass die Brühe nur ganz leicht „zittert“ – ein, zwei Blasen steigen pro Sekunde auf. Lege den Deckel schräg auf, sodass ein kleiner Spalt bleibt, und lass alles 2 bis 2,5 Stunden köcheln. Das Fleisch ist fertig, wenn es sich mit einer Gabel mühelos vom Knochen lösen lässt und das Bindegewebe weich und gelatinös wirkt. Wenn die Flüssigkeit unter das Fleisch sinkt, gießt du heißes Wasser nach. Starkes Sprudeln würde das Fleisch zäh und die Brühe trüb machen.","dauer":140,"tipp":"Pieke mit einer Gabel in den dicksten Teil des Fleischs – es sollte ohne Widerstand einsinken."},{"titel":"Brühe entfetten und Fleisch herausnehmen","aktion":"abseihen","text":"Hebe das Fleisch mit einer Zange auf einen Teller und lass es kurz abkühlen. Entferne Lorbeer, Pfefferkörner, Zwiebel und Korianderstiele mit einer Schaumkelle oder seihe die Brühe durch ein feines Sieb zurück in den Topf. Schöpfe überschüssiges Fett von der Oberfläche mit einem Löffel ab; ein bisschen golden schimmerndes Fett darf bleiben, es trägt Geschmack. Löse das Fleisch in mundgerechte Stücke vom Knochen, entferne Sehnen und große Fettstücke, und das Knochenmark bewahrst du auf.","dauer":10,"tipp":"Das Mark gehört zur Tradition: Streiche es auf eine warme Tortilla mit Salz und Limette."},{"titel":"Hartes Gemüse garen","aktion":"koecheln","text":"Bringe die Brühe wieder auf mittlere Hitze und gib die Möhren und Kartoffeln hinein. Beide brauchen etwa 12–15 Minuten, bis sie gar, aber noch formstabil sind. Gib nach 5 Minuten die Maiskolben-Scheiben dazu, denn Mais braucht ein bisschen weniger. Rühre nur vorsichtig, damit die Kartoffelwürfel nicht zerfallen. Probiere die Brühe jetzt und würze mit Salz nach: Sie sollte kräftig, rinderig und leicht süßlich vom Mais schmecken.","dauer":15,"tipp":"Festkochende Kartoffeln verwenden – mehlige zerfallen und machen die Brühe trüb."},{"titel":"Weiches Gemüse zugeben","aktion":"koecheln","text":"Füge nun Zucchini, Chayote, Weißkohl und Tomaten hinzu und lege das Fleisch zurück in den Topf. Lass alles noch 8–10 Minuten leise köcheln, bis auch der Kohl weich ist, aber noch Farbe hat. Zucchini und Kohl garen schnell und verlieren sonst ihre Konsistenz; ideal sind Stücke, die sich mit einem Löffel teilen lassen, ohne zu zerfallen. Schmecke noch einmal ab, füge bei Bedarf Salz hinzu und gib einen Spritzer Limettensaft in den Topf, der alle Aromen auffrischt.","dauer":10,"tipp":"Nicht überkochen: Zuletzt zugegebene Gemüsestücke sollen noch ihre Form halten."},{"titel":"Anrichten und am Tisch vollenden","aktion":"anrichten","text":"Schöpfe in tiefe Schalen jeweils ein Stück Fleisch mit Knochen, ein Stück Mais, Kartoffel, Möhre, Zucchini und Kohl und gieße die heiße Brühe darüber. Stelle Schüsselchen mit gehackter Zwiebel, Koriander, Limettenspalten und Salsa auf den Tisch, damit jeder seinen Teller selbst abschmecken kann. Dazu gibt es warme Tortillas und weißen Reis, den man entweder in die Brühe gibt oder daneben isst. Der Duft von Rindfleisch, Mais und frischer Limette ist das Erkennungszeichen eines guten Caldo.","dauer":0,"tipp":"Einen Löffel Reis in die Schale geben und mit der Brühe mischen – so isst man es in Mexiko."}],"profitipps":["Knochen mit Mark verwenden: Sie geben Geschmack, Körper und das beliebte Mark als Extra.","Brühe niemals sprudelnd kochen, sondern nur leicht zittern lassen – das macht das Fleisch zart und die Brühe klar.","Gemüse gestaffelt zugeben: harte Sorten (Möhre, Kartoffel) zuerst, zarte (Zucchini, Kohl) zuletzt, so bleibt alles bissfest.","Frische Limette und Koriander erst am Tisch – sie bringen Frische in die fette, schwere Brühe.","Am Vortag kochen: Die Brühe wird noch geschmackvoller, das Fett lässt sich kalt leichter abheben."],"varianten":["Caldo de Res mit Kichererbsen (Garbanzos), wie in manchen Regionen üblich.","Mit Chipotle-Chili in der Brühe für rauchige Schärfe.","Caldo de Pollo: mit Hähnchenschenkeln statt Rind – leichter und schneller.","Caldo Tlalpeño: Hühnersuppe mit Chipotle, Kichererbsen und Avocado als Verwandter."],"beilagen":["weißer Reis","warme Maistortillas","Salsa verde oder roja","Limettenspalten","gehackte Zwiebel und Koriander"],"getraenk":"Agua de Jamaica (Hibiskustee), Horchata oder ein kaltes mexikanisches Bier (Pacífico, Modelo)","koeche":[],"quellen":[{"titel":"How to make caldo de res – MasterClass","url":"https://www.masterclass.com/articles/how-to-make-caldo-de-res"}],"bild":"eintopf","farben":["#b8742f","#e3b76b","#6b8e3d"],"schlagworte":["Sonntagsessen","Rindfleisch","Mais","Heilsuppe","Mexiko"],"vegetarisch_moeglich":false},{"id":"mexiko-tostadas-de-tinga","name":"Tostadas de Tinga de Pollo","originalname":"Tostadas de tinga de pollo","kueche":"mexiko","region":"Puebla","beliebtheit":75,"hauptkategorie":"fleisch","fleischsorte":"huhn","gang":"snack","kurz":"Knusprige Tostadas mit rauchig-pikant geschmortem Hähnchen in Tomaten-Chipotle-Sauce, Bohnen, Salat, Crema und Käse.","hintergrund":"Tinga stammt aus Puebla und besteht aus gezupftem Fleisch in einer Sauce aus Tomaten, Zwiebeln und Chipotles in Adobo. Der Name wird manchmal auf ‚tingar‘ (durcheinanderbringen) zurückgeführt. Tinga gilt als Alltags- und Partyessen und wird auf Tostadas, in Tacos oder Tortas serviert. Die Tostada (frittierte oder gebackene Tortilla) ist die knusprige Unterlage, die mit Bohnen bestrichen wird.","portionen":4,"zeit":{"vorbereitung":30,"garen":40,"ruhen":0},"schwierigkeit":2,"zutaten":[{"gruppe":"Tinga","liste":[{"menge":700,"einheit":"g","name":"Hähnchenschenkel oder -brust","hinweis":""},{"menge":0.5,"einheit":"Stück","name":"Zwiebel (für den Fond)","hinweis":""},{"menge":2,"einheit":"Zehe","name":"Knoblauch (für den Fond)","hinweis":""},{"menge":400,"einheit":"g","name":"Tomaten","hinweis":""},{"menge":2,"einheit":"Stück","name":"Chipotles in Adobo","hinweis":"Dose; scharf, nach Geschmack mehr oder weniger"},{"menge":1,"einheit":"Stück","name":"Zwiebel, in dünne Streifen","hinweis":""},{"menge":2,"einheit":"Zehe","name":"Knoblauch","hinweis":""},{"menge":2,"einheit":"EL","name":"Pflanzenöl","hinweis":""},{"menge":1,"einheit":"TL","name":"Oregano","hinweis":""},{"menge":1,"einheit":"TL","name":"Salz","hinweis":""}]},{"gruppe":"Tostadas","liste":[{"menge":8,"einheit":"Stück","name":"Tostadas (fertig) oder Maistortillas","hinweis":"selbst: Tortillas im Ofen bei 200 °C 8–10 Minuten backen oder frittieren"},{"menge":200,"einheit":"g","name":"Frijoles refritos","hinweis":"siehe Rezept"},{"menge":150,"einheit":"g","name":"Römersalat oder Eisbergsalat","hinweis":"fein geschnitten"},{"menge":100,"einheit":"ml","name":"Crema oder Schmand","hinweis":""},{"menge":100,"einheit":"g","name":"Queso fresco oder Feta","hinweis":""},{"menge":1,"einheit":"Stück","name":"Avocado","hinweis":""},{"menge":1,"einheit":"Stück","name":"Limette","hinweis":""}]}],"ausruestung":["Topf","Standmixer","Pfanne","Backblech"],"schritte":[{"titel":"Mise en place","aktion":"vorbereiten","text":"Schneide die Zwiebel für die Sauce in dünne Streifen, halbiere die Tomaten und schäle den Knoblauch. Schneide Salat in feine Streifen, würfle die Avocado und bröckle den Käse. Stelle die Zutaten für die Tostadas bereit, damit du später zügig belegen kannst. Heize den Backofen auf 200 Grad vor, falls du die Tostadas selbst backst.","dauer":10,"tipp":""},{"titel":"Hähnchen garen","aktion":"kochen","text":"Gib das Fleisch mit halber Zwiebel, 2 Knoblauchzehen und Salz in einen Topf und bedecke es mit Wasser. Bringe es zum Kochen und lass es bei kleiner Hitze 20 Minuten simmern, bis es durch ist (Kerntemperatur 74 Grad). Hebe es heraus und zupfe es in feine Fasern. Hebe 200 Millilitern der Brühe auf; sie geht später in die Sauce.","dauer":25,"tipp":""},{"titel":"Tomaten rösten","aktion":"braten","text":"Röste die Tomaten in einer trockenen Pfanne oder unter dem Grill 8 bis 10 Minuten, bis die Haut platzt und schwarz wird. Das gibt Rauch und Süße. Lass sie kurz abkühlen. Die Haut kann dranbleiben; sie wird mitpüriert. Röststellen sind erwünscht, ganz schwarze Tomaten sind zu viel. Wenn du keinen Grill hast, genügt eine schwere Pfanne ohne Fett; wende die Tomaten alle 2 bis 3 Minuten, bis sie rundum weich und leicht eingefallen sind und ihr Saft karamellisiert am Pfannenboden klebt.","dauer":10,"tipp":""},{"titel":"Sauce pürieren","aktion":"puerieren","text":"Gib Tomaten, Chipotles, Adobo-Sauce aus der Dose, 1 Knoblauchzehe und 100 Millilitern Brühe in den Mixer und püriere 1 Minute glatt. Probiere vorsichtig: Chipotles sind scharf, mit der Zeit steigt die Schärfe. Beginne mit zwei Chilis und füge nach Geschmack mehr hinzu. Die Sauce soll rauchig, leicht süß und pikant sein.","dauer":5,"tipp":""},{"titel":"Zwiebel braten","aktion":"anbraten","text":"Erhitze das Öl in einer großen Pfanne bei mittlerer Hitze und brate die Zwiebelstreifen 8 bis 10 Minuten, bis sie weich und golden sind. Sie sollen süß duften und leicht karamellisieren, ohne zu verbrennen. Diese Zwiebeln geben der Tinga Süße und Biss. Rühre häufig und senke die Hitze, sobald die Streifen Farbe annehmen; verbrannte Zwiebeln bringen Bitterkeit in die Sauce, die sich nicht mehr ausgleichen lässt. Sie sind fertig, wenn sie sich zwischen den Fingern weich und süßlich anfühlen.","dauer":10,"tipp":""},{"titel":"Tinga köcheln","aktion":"koecheln","text":"Gieße die Sauce zu den Zwiebeln, füge Oregano und das zerzupfte Hähnchen hinzu und lass alles 12 bis 15 Minuten bei kleiner Hitze köcheln. Die Sauce soll eindicken und das Fleisch glänzend umhüllen. Schmecke mit Salz ab. Wenn es zu trocken wird, gib einen Schuss Brühe dazu; wird es zu feucht, lass es offen weiter einkochen. Zum Schluss soll das Fleisch von einer glänzenden, tiefroten Sauce überzogen sein, die nicht vom Löffel tropft. Probiere und schmecke mit Salz und, falls gewünscht, mit einem Spritzer Limettensaft ab.","dauer":15,"tipp":""},{"titel":"Tostadas rösten","aktion":"backen","text":"Lege die Tortillas auf ein Blech, bestreiche sie mit etwas Öl und backe sie 8 bis 10 Minuten bei 200 Grad, bis sie goldbraun und knusprig sind; wende sie einmal. Fertig gekaufte Tostadas wärmst du 3 Minuten im Ofen auf. Sie sollen laut knacken, wenn du sie zerbrichst. Achte beim Backen auf die Ränder, die schneller bräunen als die Mitte; ein Blech mit Backpapier verhindert, dass die Tortillas am Metall festkleben. Lass sie kurz auskühlen, denn dabei werden sie noch knuspriger.","dauer":10,"tipp":""},{"titel":"Belegen und anrichten","aktion":"schichten","text":"Bestreiche jede Tostada mit einer Schicht Frijoles refritos, belege sie mit Tinga, streue Salat, Käse und Avocadowürfel darauf und gib einen Klecks Crema dazu. Träufle Limettensaft darüber. Serviere sofort, denn die Tostada weicht rasch durch. Iss sie aus der Hand und beuge dich über den Teller, denn sie bricht gern.","dauer":0,"tipp":""}],"profitipps":["Chipotles dosieren: Sie sind sehr scharf.","Bohnen bilden eine Schutzschicht gegen Durchweichen.","Tinga am Vortag zubereiten; sie wird besser.","Tostadas knackig halten, erst zum Schluss belegen.","Zwiebel richtig karamellisieren für Süße."],"varianten":["Mit Schweinefleisch oder Chorizo","Vegetarisch mit Pilzen oder Jackfruit","Tinga als Taco oder Torta"],"beilagen":["Guacamole","Reis","Salsa verde"],"getraenk":"Kaltes Bier oder Agua de Jamaica","koeche":[],"quellen":[{"titel":"Uncomplicated Mexican dishes rate among world's best (Guadalajara Reporter)","url":"https://theguadalajarareporter.net/index.php/featured/61332-uncomplicated-mexican-dishes-rate-among-world-s-best"},{"titel":"Tacos al Pastor Named The World's Tastiest Dish (Journey Mexico)","url":"https://www.journeymexico.com/?p=32652"}],"bild":"taco","farben":["#b8451f","#7a9a3a","#f1e1b0"],"schlagworte":["Puebla","Snack","Partyessen"],"vegetarisch_moeglich":true},{"id":"mexiko-pescado-a-la-veracruzana","name":"Pescado a la veracruzana","originalname":"Pescado a la veracruzana","kueche":"mexiko","region":"Veracruz","beliebtheit":72,"hauptkategorie":"fisch","fischsorte":"fisch","gang":"hauptgericht","kurz":"Zartes Fischfilet auf Tomatensauce mit Oliven, Kapern und eingelegten Jalapeños – das Hafengericht von Veracruz mit spanisch-mexikanischer Seele.","hintergrund":"Pescado a la veracruzana, „Fisch nach Art von Veracruz“, ist der Klassiker der Golfküste. Die Sauce aus Tomaten, Zwiebeln, Knoblauch, grünen Oliven, Kapern und scharfen Chilis erinnert an die spanische Küche und zeigt, wie der Hafen von Veracruz Handelswaren aus Europa mit mexikanischen Zutaten verband. Traditionell wird ein ganzer roter Schnapper (huachinango) in der Sauce gegart oder im Ofen gebacken; heute nimmt man auch Filets. Rick Bayless nutzt Oliven (Manzanilla), Kapern und eingelegte Jalapeños als salzig-würzige, scharfe Trias. Gegessen wird der Fisch mit weißem Reis oder Kartoffeln.","portionen":4,"zeit":{"vorbereitung":25,"garen":35,"ruhen":15},"schwierigkeit":2,"zutaten":[{"gruppe":"Fisch","liste":[{"menge":4,"einheit":"Stück","name":"Fischfilet mit oder ohne Haut, je 180 g","hinweis":"Original: Red Snapper. In Deutschland: Dorade, Wolfsbarsch, Zander oder Kabeljau; festes, weißes Fleisch"},{"menge":3,"einheit":"EL","name":"Limettensaft","hinweis":"zum Marinieren"},{"menge":1,"einheit":"TL","name":"Salz","hinweis":""},{"menge":2,"einheit":"EL","name":"Olivenöl","hinweis":"zum Anbraten"}]},{"gruppe":"Veracruzana-Sauce","liste":[{"menge":4,"einheit":"EL","name":"Olivenöl","hinweis":""},{"menge":1,"einheit":"Stück","name":"weiße Zwiebel, in dünnen Scheiben","hinweis":""},{"menge":4,"einheit":"Zehe","name":"Knoblauch, gehackt","hinweis":""},{"menge":800,"einheit":"g","name":"Tomaten, gehackt (frisch geröstet oder Dose)","hinweis":"Bayless verwendet Dosentomaten, feuergeröstet; sonst gute Eiertomaten"},{"menge":2,"einheit":"Blatt","name":"Lorbeer","hinweis":""},{"menge":1,"einheit":"TL","name":"mexikanischer Oregano, getrocknet","hinweis":"gewöhnlicher Oregano geht auch"},{"menge":3,"einheit":"EL","name":"glatte Petersilie, gehackt","hinweis":""},{"menge":100,"einheit":"g","name":"grüne Oliven, entsteint und in Scheiben","hinweis":"Manzanilla-Oliven"},{"menge":3,"einheit":"EL","name":"Kapern, abgespült","hinweis":""},{"menge":3,"einheit":"Stück","name":"eingelegte Jalapeños, in Streifen","hinweis":"im Glas; Pepperoni als Ersatz"},{"menge":100,"einheit":"ml","name":"Wasser oder Fischfond","hinweis":""}]},{"gruppe":"Beilage","liste":[{"menge":600,"einheit":"g","name":"kleine Kartoffeln","hinweis":"halbiert, im Ofen geröstet; oder weißer Reis"}]}],"ausruestung":["Große Pfanne mit hohem Rand","Ofenfeste Form oder Pfanne","Backblech für Kartoffeln"],"schritte":[{"titel":"Mise en place","aktion":"vorbereiten","text":"Schneide die Zwiebel in dünne Scheiben, hacke Knoblauch und Petersilie, schneide die Oliven in Ringe und die Jalapeños in Streifen und spüle die Kapern ab. Hacke die Tomaten, falls frische verwendet werden, und entferne den Strunk. Halbiere die Kartoffeln und heize den Ofen auf 200 °C Ober-/Unterhitze (180 °C Umluft) vor. Die Sauce kocht eine Weile, daher fängst du mit ihr zuerst an.","dauer":0,"tipp":""},{"titel":"Kartoffeln rösten","aktion":"backen","text":"Vermenge die halbierten Kartoffeln mit Olivenöl und Salz und lege sie mit der Schnittfläche nach unten auf ein Backblech. Röste sie im Ofen etwa 35 Minuten, bis die Unterseite goldbraun und knusprig und das Innere weich ist. Du erkennst es am Einstechen: Ein Messer gleitet ohne Widerstand hinein. Die Kartoffeln begleiten die würzige Sauce und nehmen sie gut auf.","dauer":35,"tipp":"Das Rösten läuft im Ofen, während du Sauce und Fisch machst – starte diesen Schritt als Erstes."},{"titel":"Fisch marinieren","aktion":"marinieren","text":"Lege die Filets in eine flache Schale, beträufele sie mit Limettensaft, salze sie und lasse sie 15 Minuten im Kühlschrank ruhen; wende sie einmal. Der Saft würzt den Fisch, macht ihn leicht fester und nimmt Fischgeruch. Länger als 20 Minuten solltest du nicht marinieren, denn die Säure verändert sonst die Konsistenz. Tupfe die Filets vor dem Anbraten gründlich trocken.","dauer":15,"tipp":""},{"titel":"Zwiebel und Knoblauch anschwitzen","aktion":"anbraten","text":"Erhitze das Olivenöl für die Sauce in einer großen Pfanne bei mittlerer Hitze. Gib die Zwiebelscheiben hinein und brate sie 6 bis 8 Minuten, bis sie weich, glasig und an den Rändern leicht goldfarben sind. Dann kommt der Knoblauch für 30 Sekunden dazu; er soll duften, aber nicht bräunen. Die Basis soll süßlich und aromatisch riechen, bevor die Tomaten dazukommen.","dauer":8,"tipp":""},{"titel":"Sauce kochen","aktion":"koecheln","text":"Gib die Tomaten, Lorbeer, Oregano, Petersilie sowie die Hälfte der Oliven, Kapern und Jalapeños in die Pfanne. Koche alles bei starker Hitze 10 Minuten und rühre dabei oft, bis die Flüssigkeit eindampft und eine dicke Sauce entsteht. Gieße Wasser oder Fond zu und lasse sie weitere 15 Minuten leise köcheln. Sie soll sämig, tiefrot und kräftig würzig sein, mit Säure von Tomate, Salz von Oliven und Kapern und Schärfe der Jalapeños. Schmecke vorsichtig mit Salz ab.","dauer":25,"tipp":"Die Oliven und Kapern bringen schon viel Salz mit – erst am Ende nachsalzen."},{"titel":"Fisch anbraten","aktion":"braten","text":"Erhitze Olivenöl in einer großen beschichteten oder gusseisernen Pfanne bei hoher Hitze, bis es leicht schimmert. Lege die trockenen Filets mit der Hautseite (falls vorhanden) nach unten hinein und brate sie etwa 2 Minuten, bis sie goldbraun sind; wende sie dann kurz. Der Fisch muss nicht durch sein, er wird gleich im Ofen fertig. Brate in zwei Portionen, damit die Pfanne heiß bleibt.","dauer":5,"tipp":""},{"titel":"Im Ofen fertig garen","aktion":"backen","text":"Lege die angebratenen Filets auf ein Gitter über einem Blech oder in eine ofenfeste Form und stelle sie 8 bis 10 Minuten bei 200 °C in den Ofen. Das schonende Garen mit Umgebungswärme lässt das Eiweiß gleichmäßig stocken. Der Fisch ist gar, wenn sich das Fleisch an der dicksten Stelle in Lamellen teilt, undurchsichtig weiß ist und die Kerntemperatur etwa 60 bis 62 °C erreicht hat.","dauer":10,"tipp":""},{"titel":"Anrichten","aktion":"anrichten","text":"Löffele die heiße Sauce auf vorgewärmte Teller, setze die Fischfilets darauf und garniere sie mit den restlichen Oliven, Kapern und Jalapeñostreifen. Verteile die gerösteten Kartoffeln rund um den Fisch und bestreue alles mit etwas Petersilie. Serviere sofort, solange die Sauce dampft. Die Sauce soll nicht über das Filet gegossen werden, sondern darunter liegen, damit der Fisch sichtbar bleibt.","dauer":0,"tipp":""}],"profitipps":["Die Sauce lässt sich gut vorbereiten, der Fisch wird erst kurz vor dem Servieren gebraten.","Die Hälfte der Oliven, Kapern und Jalapeños zum Garnieren aufheben – das gibt frische Säure und Biss.","Fisch nur kurz marinieren und sehr gut trocken tupfen, damit er schön Farbe bekommt.","Keinen scharfen Chili zu früh in die Sauce geben, er verliert sonst seine Frische.","Mit Fond statt Wasser wird die Sauce noch runder."],"varianten":["Ganzer roter Schnapper (huachinango) im Ofen mit der Sauce.","Mit Garnelen oder Tintenfisch statt Fisch.","Mit einem Schuss Weißwein oder einer Prise Zimt (Veracruz-typisch).","Als Pescado a la veracruzana mit Reis und gebratenen Kochbananen."],"beilagen":["Geröstete Kartoffeln","Weißer Reis","Gebratene Kochbananen","Tortillas"],"getraenk":"Kühler Weißwein (Albariño, Verdejo) oder ein kaltes Lagerbier.","koeche":[{"name":"Rick Bayless","bezug":"Beschreibt Oliven, Kapern und eingelegte Jalapeños als Kern des Veracruz-Stils und bietet eine vereinfachte Version mit Mahi Mahi, feuergerösteten Tomaten und gerösteten Kartoffeln an.","quelle":"https://www.rickbayless.com/recipe/mahi-mahi-a-la-veracruzana"}],"quellen":[{"titel":"Mahi Mahi a la Veracruzana – Rick Bayless","url":"https://www.rickbayless.com/recipe/mahi-mahi-a-la-veracruzana"},{"titel":"Seared Fish with Tomatoes, Olives and Pickled Jalapeños – Rick Bayless","url":"https://www.rickbayless.com/recipe/seared-fish-with-tomatoes-olives-and-pickled-jalapenos/"},{"titel":"Halibut Veracruz – Food.com","url":"https://www.food.com/amp/recipe/halibut-veracruz-340236"}],"bild":"fisch","farben":["#c4452d","#6b8a3a","#f1e2c1"],"schlagworte":["Veracruz","Golfküste","Oliven und Kapern","Tomatensauce"],"vegetarisch_moeglich":false},{"id":"mexiko-arroz-rojo","name":"Mexikanischer Reis (Arroz Rojo)","originalname":"Arroz rojo a la mexicana","kueche":"mexiko","region":"ganz Mexiko","beliebtheit":72,"hauptkategorie":"vegan","fleischsorte":"","gang":"beilage","kurz":"Körniger roter Reis, in Öl goldbraun angeröstet und in Tomatenbrühe gegart – die klassische Beilage der Comida corrida.","hintergrund":"Arroz rojo, auch Arroz a la mexicana genannt, gehört zu den Standardbeilagen in Mexiko und steht auf nahezu jedem Mittagstisch (comida corrida). Der Reis wird zuerst gewaschen und in heißem Öl angeröstet, bevor Tomatenpüree und Brühe dazukommen. Das Anrösten sorgt für körnige Konsistenz; werden die Körner zu früh mit Flüssigkeit übergossen, wird der Reis klebrig. Meist kommen Erbsen und Möhren dazu.","portionen":4,"zeit":{"vorbereitung":10,"garen":30,"ruhen":15},"schwierigkeit":1,"zutaten":[{"gruppe":"Reis","liste":[{"menge":250,"einheit":"g","name":"Langkornreis","hinweis":"keine Rundkorn- oder Milchreisart"},{"menge":3,"einheit":"EL","name":"Pflanzenöl","hinweis":""},{"menge":2,"einheit":"Stück","name":"reife Tomaten","hinweis":""},{"menge":0.25,"einheit":"Stück","name":"Zwiebel","hinweis":""},{"menge":2,"einheit":"Zehe","name":"Knoblauch","hinweis":""},{"menge":500,"einheit":"ml","name":"Hühner- oder Gemüsebrühe","hinweis":"für vegan: Gemüsebrühe"},{"menge":1,"einheit":"TL","name":"Salz","hinweis":""},{"menge":50,"einheit":"g","name":"Erbsen, TK","hinweis":"optional"},{"menge":1,"einheit":"Stück","name":"Möhre, gewürfelt","hinweis":"optional"},{"menge":1,"einheit":"Stück","name":"frische Chili","hinweis":"optional, ganz mitgegart"}]}],"ausruestung":["Topf mit gut schließendem Deckel","Standmixer","Sieb"],"schritte":[{"titel":"Reis waschen und abtropfen","aktion":"vorbereiten","text":"Gib den Reis in ein Sieb und wasche ihn unter kaltem Wasser, bis das Wasser fast klar ist; die Stärke auf den Körnern würde den Reis sonst klebrig machen. Lass ihn anschließend 15 Minuten abtropfen, damit er beim Anrösten nicht spritzt. Der Reis soll sich trocken anfühlen und einzelne Körner zeigen. Je gründlicher du abspülst und abtropfen lässt, desto körniger wird das Ergebnis. Währenddessen kannst du schon Gemüse schneiden und die Brühe erhitzen, damit sie später heiß in den Topf kommt.","dauer":15,"tipp":""},{"titel":"Tomatenpüree herstellen","aktion":"puerieren","text":"Püriere Tomaten, Zwiebel und Knoblauch mit 100 Millilitern Brühe im Mixer sehr fein. Das Püree soll flüssig und gleichmäßig sein; Haut und Kerne dürfen bleiben, werden aber fein zermahlen. Es ergibt etwa 300 Milliliter und bildet die Farbe und das Aroma des Reises. Probiere das Püree: Es soll frisch nach Tomate schmecken, nur leicht säuerlich. Sind die Tomaten blass und wässrig, hilft ein Teelöffel Tomatenmark im Mixer für Farbe und Tiefe.","dauer":5,"tipp":""},{"titel":"Reis anrösten","aktion":"anbraten","text":"Erhitze das Öl in einem Topf bei mittlerer Hitze und gib den abgetropften Reis hinein. Rühre ihn 5 bis 7 Minuten, bis die Körner goldfarben und leicht transparent an den Rändern sind und nussig duften. Das Anrösten versiegelt die Körner und verhindert Verkleben. Bräune ihn nicht zu dunkel, sonst wird er bitter.","dauer":7,"tipp":"Das Anrösten ist der Unterschied zwischen körnigem und klebrigem Reis."},{"titel":"Püree zugeben","aktion":"braten","text":"Gieße das Tomatenpüree in den Topf; es zischt kräftig. Rühre 2 bis 3 Minuten, bis die Flüssigkeit zum großen Teil verdampft ist und der Reis das Püree aufgenommen hat. Er soll rötlich glänzen. Das Anbraten des Pürees nimmt ihm die rohe Säure und lässt das Aroma tiefer werden. Der Reis ist bereit für die Brühe, wenn die Masse am Topfboden leicht ansetzt und das Öl sichtbar an den Rändern austritt; rühre dann gleich weiter, damit nichts anbrennt.","dauer":3,"tipp":""},{"titel":"Brühe zugeben und garen","aktion":"koecheln","text":"Gieße die heiße Brühe an, füge Salz, Möhren, Erbsen und die ganze Chili hinzu und rühre einmal um. Bringe zum Kochen, dann sofort auf kleinste Hitze reduzieren und mit fest schließendem Deckel 18 bis 20 Minuten garen. Nicht umrühren und nicht den Deckel heben, sonst entweicht Dampf. Der Reis ist fertig, wenn alle Flüssigkeit aufgesogen und kleine Dampflöcher an der Oberfläche sichtbar sind.","dauer":20,"tipp":""},{"titel":"Quellen lassen und auflockern","aktion":"ruhen","text":"Nimm den Topf vom Herd und lass den Reis zugedeckt 10 bis 15 Minuten ruhen; der Dampf verteilt sich gleichmäßig. Entferne die Chili und lockere den Reis mit einer Gabel auf. Schmecke mit Salz ab. Er soll körnig, locker und satt rot sein. Serviere ihn sofort oder halte ihn zugedeckt warm. Reste lassen sich im Kühlschrank 3 Tage aufbewahren und mit einem Schuss Wasser in der Pfanne oder Mikrowelle wieder erwärmen, ohne dass sie hart werden.","dauer":15,"tipp":""}],"profitipps":["Reis gründlich waschen und abtropfen lassen.","Reis anrösten, bis er duftet und goldfarben ist.","Brühe heiß zugeben, nicht kalt.","Deckel nicht öffnen und nicht rühren.","Nach dem Garen 10 Minuten ruhen lassen."],"varianten":["Arroz verde mit Koriander und Poblano","Arroz blanco mit Knoblauch und Zwiebel","Mit Mais und Paprika"],"beilagen":["Frijoles refritos","Hähnchen","Mole","Enchiladas"],"getraenk":"Passt zu allen mexikanischen Getränken","koeche":[],"quellen":[{"titel":"Uncomplicated Mexican dishes rate among world's best (Guadalajara Reporter)","url":"https://theguadalajarareporter.net/index.php/featured/61332-uncomplicated-mexican-dishes-rate-among-world-s-best"},{"titel":"Tacos al Pastor Named The World's Tastiest Dish (Journey Mexico)","url":"https://www.journeymexico.com/?p=32652"}],"bild":"reis","farben":["#c4452a","#e07a4a","#f4d8a8"],"schlagworte":["Beilage","Comida corrida","vegan"],"vegetarisch_moeglich":true},{"hauptkategorie":"fisch","fleischsorte":"","vegetarisch_moeglich":false,"id":"mexiko-pescado-zarandeado","name":"Pescado zarandeado – gegrillter Fisch von der Pazifikküste","originalname":"Pescado zarandeado","kueche":"mexiko","region":"Pazifikküste (Nayarit, Sinaloa, Jalisco)","beliebtheit":68,"fischsorte":"fisch","gang":"hauptgericht","themen":["grill"],"kurz":"Ein aufgeklappter ganzer Fisch in einer Marinade aus Chilis, Tomate, Knoblauch und Soja, über Glut gegrillt, bis die Haut knusprig ist – mit Tortillas, Zwiebel und Limette serviert.","hintergrund":"Pescado zarandeado ist ein Strandklassiker der mexikanischen Pazifikküste, der als Spezialität der Küste von Nayarit bis Jalisco gilt. Ein ganzer Fisch wird aufgeklappt, mariniert und in einem Grillkorb über Holzkohle gegart, wobei er mehrmals gewendet wird: Zarandear bedeutet schütteln oder hin und her bewegen. Rick Bayless weist darauf hin, dass der Fisch klare asiatische Einflüsse zeigt: Sojasauce und geröstete Chilis in Öl gehören zur Küste ebenso wie Achiote. Am Tisch isst man den Fisch mit den Fingern in warme Tortillas gewickelt, mit roter Zwiebel, Limette und Salsa.","portionen":4,"zeit":{"vorbereitung":35,"garen":25,"ruhen":45},"schwierigkeit":2,"zutaten":[{"gruppe":"Fisch","liste":[{"menge":1.4,"einheit":"kg","name":"ganzer Fisch (Wolfsbarsch, Dorade royal oder Red Snapper), küchenfertig","hinweis":"Fischtheke bitten, ihn zu schuppen und auszunehmen; ersatzweise zwei kleinere Fische à 700 g"},{"menge":1,"einheit":"TL","name":"Salz","hinweis":""},{"menge":2,"einheit":"EL","name":"Pflanzenöl","hinweis":"zum Einölen des Rosts"}]},{"gruppe":"Marinade","liste":[{"menge":3,"einheit":"Stück","name":"getrocknete Guajillo-Chilis","hinweis":"entstielt, entkernt"},{"menge":1,"einheit":"Stück","name":"getrocknete Ancho-Chili","hinweis":"entstielt, entkernt"},{"menge":100,"einheit":"ml","name":"Tomatensauce oder passierte Tomaten","hinweis":""},{"menge":4,"einheit":"Zehe","name":"Knoblauch","hinweis":""},{"menge":2,"einheit":"EL","name":"Sojasauce","hinweis":""},{"menge":1,"einheit":"EL","name":"Worcestershiresauce","hinweis":""},{"menge":2,"einheit":"EL","name":"Limettensaft","hinweis":""},{"menge":1,"einheit":"TL","name":"mexikanischer Oregano","hinweis":""},{"menge":1,"einheit":"TL","name":"Salz","hinweis":""}]},{"gruppe":"Zum Servieren","liste":[{"menge":12,"einheit":"Stück","name":"Maistortillas","hinweis":"warm"},{"menge":1,"einheit":"Stück","name":"rote Zwiebel","hinweis":"in dünnen Ringen"},{"menge":3,"einheit":"Stück","name":"Limetten","hinweis":"in Spalten"},{"menge":1,"einheit":"Stück","name":"Avocado","hinweis":"optional"},{"menge":null,"einheit":"","name":"scharfe Salsa","hinweis":"nach Geschmack"}]}],"ausruestung":["Holzkohle- oder Gasgrill","Fischgrillkorb (stark empfohlen)","Mixer","Scharfes Messer","Pinsel"],"schritte":[{"titel":"Frische prüfen und vorbereiten","aktion":"vorbereiten","text":"Der Fisch soll klare, gewölbte Augen, leuchtend rote Kiemen und glänzende, fest sitzende Schuppen haben. Der Geruch soll nach frischem Meerwasser sein, nicht fischig. Falls nicht schon erledigt, schuppe ihn mit dem Messerrücken gegen die Schuppenrichtung unter Wasser, nimm ihn aus und spüle die Bauchhöhle. Tupfe ihn von innen und außen gründlich trocken. Trockene Haut brennt später nicht an dem Rost an und wird knusprig.","dauer":10,"tipp":"Schuppen unter laufendem Wasser entfernen, sie fliegen sonst durch die ganze Küche."},{"titel":"Fisch aufklappen","aktion":"schneiden","text":"Lege den Fisch auf die Seite. Schneide mit einem langen, scharfen Messer vom Kopf zum Schwanz entlang der Rückenmitte direkt neben der Rückenflosse ein, bis du die Wirbelsäule spürst, und führe das Messer flach am Rückgrat entlang, ohne den Bauch zu durchtrennen. Klappe den Fisch auf wie ein Buch (Schmetterlingsschnitt). Die Bauchhaut bleibt als Scharnier erhalten; die Gräte kann bleiben, sie hält den Fisch zusammen. Ritze das Fleisch diagonal in 2 cm Abstand ein.","dauer":10,"tipp":"Bei Unsicherheit lässt du dir den Fisch an der Fischtheke aufklappen."},{"titel":"Chilis zubereiten","aktion":"anbraten","text":"Röste die Chilis in einer trockenen Pfanne 15 Sekunden pro Seite, bis sie duften, ohne zu verbrennen. Übergieße sie mit heißem Wasser und lasse sie 15 Minuten einweichen, bis sie weich sind. Das Rösten weckt die Fruchtaromen, schwarz geröstete Chilis machen die Marinade bitter. Gieße ab und behalte etwas Einweichwasser.","dauer":15,"tipp":"Guajillo bringt Frucht und Farbe, Ancho Süße und Tiefe."},{"titel":"Marinade pürieren","aktion":"puerieren","text":"Püriere Chilis, Tomatensauce, Knoblauch, Sojasauce, Worcestershiresauce, Limettensaft, Oregano und Salz im Mixer zu einer glatten, dunkelroten Paste; füge bei Bedarf einen Schluck Einweichwasser hinzu. Streiche die Marinade durch ein Sieb, damit Chilihäute zurückbleiben. Probiere: Sie soll kräftig salzig, leicht scharf, sauer und rauchig schmecken. Sie soll den Fisch würzen, deshalb darf sie ruhig deutlich sein.","dauer":5,"tipp":"Soja und Worcestershire sorgen für Umami: Das ist der asiatische Einschlag der Küste."},{"titel":"Fisch marinieren","aktion":"marinieren","text":"Salze den Fisch von innen und außen leicht und streiche die Marinade mit einem Pinsel gleichmäßig über die Fleischseite, in die Einschnitte und auch auf die Haut. Decke ihn ab und lasse ihn 30 bis 45 Minuten im Kühlschrank ziehen. Eine längere Zeit ist nicht nötig, denn die Säure der Limette greift das Fleisch an. Nimm den Fisch 15 Minuten vor dem Grillen heraus.","dauer":45,"tipp":"Streiche einen Teil der Marinade beiseite, um den Fisch beim Grillen damit zu bestreichen."},{"titel":"Grill vorbereiten","aktion":"grillen","text":"Heize den Grill auf mittlere Hitze von etwa 180 bis 200 °C vor, bei Holzkohle bis die Kohle weiß glüht. Reibe den Grillkorb gründlich mit Öl ein und lege den Fisch hinein, die Haut nach außen. Der Korb verhindert, dass die empfindliche Haut am Rost festklebt und beim Wenden reißt. Prüfe die Hitze mit der Hand: Du solltest sie 5 Sekunden über dem Rost halten können.","dauer":10,"tipp":"Zu starke Hitze verbrennt die Marinade, bevor der Fisch gar ist."},{"titel":"Grillen und wenden","aktion":"grillen","text":"Lege den Korb auf den Grill und wende ihn alle 3 bis 4 Minuten, damit der Fisch gleichmäßig gart und die Marinade karamellisiert, ohne zu verbrennen. Zwischen den Wendungen pinselst du ihn mit der zurückgehaltenen Marinade ein. Insgesamt braucht ein Fisch von 1,4 kg etwa 15 bis 20 Minuten. Die Haut wird knusprig, an manchen Stellen dunkel, das Fleisch beginnt sich zu lösen und duftet nach Rauch und Chili.","dauer":18,"tipp":"Hast du keinen Korb, nimm zwei Pfannenwender und wende vorsichtig."},{"titel":"Garpunkt prüfen und ruhen","aktion":"ruhen","text":"Der Fisch ist gar, wenn das Fleisch an der dicksten Stelle neben der Gräte blickdicht weiß ist und sich leicht mit der Gabel lösen lässt; die Kerntemperatur liegt bei 58 bis 62 °C. Nimm den Korb vom Grill und lasse den Fisch 3 Minuten ruhen, damit die Säfte sich verteilen. Öffne den Korb vorsichtig und lege den Fisch auf eine große Platte.","dauer":3,"tipp":""},{"titel":"Anrichten und essen","aktion":"anrichten","text":"Stelle den Fisch mitten auf den Tisch, mit Tortillas, roten Zwiebelringen, Limettenspalten, Avocado und Salsa. Jeder löst mit den Fingern Fleischstücke vom Fisch, legt sie in eine Tortilla, gibt Zwiebel, Salsa und einen Spritzer Limette dazu und isst. Das knusprige Fleisch an Rand und Haut gilt als Delikatesse. Ein kaltes Bier passt hervorragend dazu.","dauer":0,"tipp":""}],"profitipps":["Fisch möglichst ganz mit Haut und Gräten grillen: Das hält ihn saftig.","Grillkorb ist der Schlüssel; ohne ihn bleibt die Haut am Rost kleben.","Nicht zu heiß grillen: Die Marinade enthält Zucker aus Tomate und Chili und verbrennt schnell.","Wenden, mehrmals: Das 'Schütteln' (zarandear) sorgt für gleichmäßiges Garen.","Fisch am Tisch mit den Fingern essen: Die Kruste und das Fleisch an den Backen sind die besten Stücke."],"varianten":["Mit Achiote-Paste (Annatto) statt Chilis, wie in manchen Küstenrezepten.","Mit einer dünnen Schicht Mayonnaise unter der Marinade für extra Saftigkeit.","Mit Garnelen oder Fischfilets im Korb statt eines ganzen Fisches.","Als Tacos zarandeados mit Krautsalat und Salsa."],"beilagen":["Warme Maistortillas","Pico de gallo","Rote Zwiebel mit Limette","Reis oder Bohnen"],"getraenk":"Kaltes mexikanisches Bier mit Limette, Mezcal oder Agua de jamaica.","koeche":[{"name":"Rick Bayless","bezug":"In seiner Version des Fish Zarandeado ersetzt er das in Mexiko ungebräuchliche Achiote durch ein Püree aus gerösteten Anchos mit Tomatensauce, Knoblauch, Sojasauce und Worcestershire, grillt den Fisch im geölten Grillkorb und wendet ihn alle drei bis vier Minuten; er verweist dabei auf den asiatischen Einschlag der Westküste.","quelle":"https://www.rickbayless.com/recipe/fish-zarandeado/"}],"quellen":[{"titel":"Fish Zarandeado – Rick Bayless","url":"https://www.rickbayless.com/recipe/fish-zarandeado/"},{"titel":"Mexican cuisine – Wikipedia","url":"https://en.wikipedia.org/wiki/Mexican_cuisine"}],"bild":"fisch","farben":["#a63a1d","#d98a2c","#f2e1bd"],"schlagworte":["Mexiko","Grillen","Nayarit","Ganzer Fisch","Strand"]}]);
